window.TEXTBOOK_TEXTS = Object.assign(window.TEXTBOOK_TEXTS || {}, {"hsk3-1":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"这是杨同乐吗？他怎么跟白家月在一起？","pinyin":"Zhè shì Yáng Tónglè ma? Tā zěnme gēn Bái Jiāyuè zài yìqǐ?","speaker":"刘明","vi":"Đây là Dương Đồng Lạc à? Sao anh ấy lại ở cùng Bạch Gia Nguyệt vậy?"},{"hanzi":"他不是杨同乐，他叫李文，是白家月的好朋友。","pinyin":"Tā bú shì Yáng Tónglè, tā jiào Lǐ Wén, shì Bái Jiāyuè de hǎo péngyou.","speaker":"王一雪","vi":"Anh ấy không phải Dương Đồng Lạc, anh ấy tên là Lý Văn, là bạn thân của Bạch Gia Nguyệt."},{"hanzi":"我还以为是同乐呢，他们看上去有点儿像。","pinyin":"Wǒ hái yǐwéi shì Tónglè ne, tāmen kànshàngqù yǒudiǎnr xiàng.","speaker":"刘明","vi":"Anh còn tưởng là Đồng Lạc chứ, nhìn họ hơi giống nhau đấy."},{"hanzi":"是长得有点儿像，但是他比同乐高，身高有一米八。","pinyin":"Shì zhǎng de yǒudiǎnr xiàng, dànshì tā bǐ Tónglè gāo, shēngāo yǒu yì mǐ bā.","speaker":"王一雪","vi":"Trông cũng hơi giống thật, nhưng anh ấy cao hơn Đồng Lạc, cao tới một mét tám cơ."},{"hanzi":"看起来也比同乐瘦一点儿。","pinyin":"Kànqǐlái yě bǐ Tónglè shòu yìdiǎnr.","speaker":"刘明","vi":"Nhìn cũng có vẻ gầy hơn Đồng Lạc một chút."},{"hanzi":"下个星期家月和李文要来北京，我去机场接他们。","pinyin":"Xià ge xīngqī Jiāyuè hé Lǐ Wén yào lái Běijīng, wǒ qù jīchǎng jiē tāmen.","speaker":"王一雪","vi":"Tuần sau Gia Nguyệt và Lý Văn sẽ đến Bắc Kinh, em ra sân bay đón họ."},{"hanzi":"他们哪天到北京？我跟你一起去机场接他们吧。","pinyin":"Tāmen nǎ tiān dào Běijīng? Wǒ gēn nǐ yìqǐ qù jīchǎng jiē tāmen ba.","speaker":"刘明","vi":"Họ ngày nào đến Bắc Kinh thế? Anh đi sân bay đón họ cùng em nhé."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"他不是杨同乐，他叫李文，是白家月的好朋友。\" (Cậu ấy không phải Dương Đồng Nhạc, cậu ấy tên Lý Văn, là bạn thân của Bạch Gia Nguyệt.), nên đáp án đúng là Lý Văn, bạn thân của Bạch Gia Nguyệt.","options":["王一雪的男朋友杨同乐","白家月的好朋友李文","王一雪的弟弟刘明","李文的哥哥"],"q":"照片里跟白家月在一起的人是谁？"},{"answerIdx":2,"explanation":"Trong bài có câu \"但是他比同乐高，身高有一米八。\" (nhưng cậu ấy cao hơn Đồng Nhạc, cao 1m8.) và \"看起来也比同乐瘦一点儿。\" (nhìn cũng gầy hơn Đồng Nhạc một chút.), nên đáp án đúng là cao hơn và gầy hơn Dương Đồng Nhạc một chút.","options":["比杨同乐矮，也比他胖一点儿","和杨同乐一样高，但是比他瘦","比杨同乐高，也比他瘦一点儿","身高一米八，但是比杨同乐胖一点儿"],"q":"和杨同乐比，李文看起来怎么样？"}],"scene":"在家里，刘明和王一雪在沙发上聊天儿。","sceneVi":"Ở nhà, Lưu Minh và Vương Nhất Tuyết đang trò chuyện trên ghế sô pha."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"我的行李怎么还没出来？是不是丢了？","pinyin":"Wǒ de xíngli zěnme hái méi chūlái? Shì bu shì diū le?","speaker":"白家月","vi":"Sao hành lý của mình vẫn chưa ra nhỉ? Có phải bị mất rồi không?"},{"hanzi":"你的行李箱是什么样的？","pinyin":"Nǐ de xínglixiāng shì shénme yàng de?","speaker":"李文","vi":"Va li của bạn trông như thế nào?"},{"hanzi":"是一个黑色的箱子，上面写着我的名字和电话号码。","pinyin":"Shì yí ge hēisè de xiāngzi, shàngmiàn xiězhe wǒ de míngzi hé diànhuà hàomǎ.","speaker":"白家月","vi":"Là một chiếc va li màu đen, phía trên có ghi tên và số điện thoại của mình."},{"hanzi":"我好像在哪儿看到过这个箱子，是不是有人拿错了？","pinyin":"Wǒ hǎoxiàng zài nǎr kàndào guo zhège xiāngzi, shì bu shì yǒu rén ná cuò le?","speaker":"李文","vi":"Hình như mình đã nhìn thấy chiếc va li này ở đâu đó rồi, có phải có ai cầm nhầm không?"},{"hanzi":"我们快找谁问一下吧，箱子里有不少重要的东西。","pinyin":"Wǒmen kuài zhǎo shéi wèn yíxià ba, xiāngzi lǐ yǒu bùshǎo zhòngyào de dōngxi.","speaker":"白家月","vi":"Chúng ta mau tìm ai đó hỏi thử xem, trong va li có không ít đồ quan trọng."},{"hanzi":"别着急，我们拿着护照和机票，去服务台问问吧。","pinyin":"Bié zháojí, wǒmen názhe hùzhào hé jīpiào, qù fúwùtái wènwen ba.","speaker":"李文","vi":"Đừng lo lắng, chúng ta cầm hộ chiếu và vé máy bay ra quầy dịch vụ hỏi thử xem."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"是一个黑色的箱子，上面写着我的名字和电话号码。\" (Là một chiếc va li màu đen, bên trên có viết tên và số điện thoại của tôi.), nên đáp án đúng là chiếc va li màu đen có ghi tên và số điện thoại của cô ấy.","options":["是一个白色的箱子，上面只有她的名字","是一个黑色的箱子，上面写着她的名字和电话号码","是一个很大很重的红色箱子","上面什么都没写，里面没有重要的东西"],"q":"白家月的行李箱是什么样的？"},{"answerIdx":2,"explanation":"Trong bài có câu \"别着急，我们拿着护照和机票，去服务台问问吧。\" (Đừng lo lắng, chúng ta cầm hộ chiếu và vé máy bay ra quầy dịch vụ hỏi xem sao.), nên đáp án đúng là mang hộ chiếu và vé máy bay đến quầy dịch vụ hỏi.","options":["先走出机场去找王一雪和刘明","在行李领取处一直等下去","拿着护照和机票去服务台问一问","给拿错箱子的人打电话"],"q":"没有看到行李箱，李文打算怎么帮白家月？"}],"scene":"在机场，李文和白家月在行李领取处。","sceneVi":"Tại sân bay, Lý Văn và Bạch Gia Nguyệt đang ở khu vực nhận hành lý."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"飞机早就到了，你看见白家月他们了吗？","pinyin":"Fēijī zǎo jiù dào le, nǐ kànjiàn Bái Jiāyuè tāmen le ma?","speaker":"刘明","vi":"Máy bay đã hạ cánh từ sớm rồi, em đã thấy nhóm Bạch Gia Nguyệt chưa?"},{"hanzi":"没有，他们应该快出来了。","pinyin":"Méiyǒu, tāmen yīnggāi kuài chūlái le.","speaker":"王一雪","vi":"Chưa ạ, chắc họ sắp ra rồi."},{"hanzi":"我们站到中间去吧，这样他们好找一些。","pinyin":"Wǒmen zhàn dào zhōngjiān qù ba, zhèyàng tāmen hǎo zhǎo yìxiē.","speaker":"刘明","vi":"Chúng ta đứng ra giữa đi, như vậy họ sẽ dễ tìm hơn một chút."},{"hanzi":"你看那个高个子的人是李文吗？","pinyin":"Nǐ kàn nàge gāogèzi de rén shì Lǐ Wén ma?","speaker":"王一雪","vi":"Anh nhìn xem người cao lớn kia có phải là Lý Văn không?"},{"hanzi":"你说的是哪个？那个穿着黑衣服的短头发的年轻人？","pinyin":"Nǐ shuō de shì nǎge? Nàge chuānzhe hēi yīfu de duǎn tóufa de niánqīngrén?","speaker":"刘明","vi":"Em nói người nào? Cái người trẻ tuổi tóc ngắn mặc áo đen kia à?"},{"hanzi":"对，那个人就是李文！你看，家月在他后面呢。","pinyin":"Duì, nàge rén jiù shì Lǐ Wén! Nǐ kàn, Jiāyuè zài tā hòumiàn ne.","speaker":"王一雪","vi":"Đúng rồi, người đó chính là Lý Văn đấy! Anh nhìn kìa, Gia Nguyệt đang ở phía sau anh ấy."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"我们站到中间去吧，这样他们好找一些。\" (Chúng ta đứng ra chính giữa đi, như vậy họ sẽ dễ tìm hơn một chút.), nên đáp án đúng là đứng ở giữa để Bạch Gia Nguyệt và Lý Văn dễ tìm thấy họ hơn.","options":["因为中间有座位，可以坐着休息","因为站在中间，白家月和李文更容易找到他们","因为飞机还没到，中间比较凉快","因为服务台就在大厅中间"],"q":"刘明为什么建议站到中间去？"},{"answerIdx":0,"explanation":"Trong bài có câu \"你看那个高个子的人是李文吗？\" (Anh nhìn người cao lớn kia có phải Lý Văn không?) và \"那个穿着黑衣服的短头发的年轻人？\" (Cậu thanh niên tóc ngắn mặc áo đen kia à?), nên đáp án đúng là cao lớn, tóc ngắn, mặc quần áo màu đen.","options":["高个子、短头发、穿着黑衣服","矮个子、长头发、穿着黑衣服","高个子、戴着帽子、拿着白色的包","走在白家月后面的年轻人"],"q":"在机场大厅出现的李文是什么样子的？"}],"scene":"在机场大厅，刘明和王一雪接机。","sceneVi":"Tại sảnh sân bay, Lưu Minh và Vương Nhất Tuyết đang đón người."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"昨天我到北京了。","pinyin":"Zuótiān wǒ dào Běijīng le.","speaker":"Đoạn văn","vi":"Hôm qua tôi đã đến Bắc Kinh rồi."},{"hanzi":"虽然路上花了十几个小时，但是跟家月坐在一起，我觉得时间过得很快。","pinyin":"Suīrán lùshang huā le shí jǐ ge xiǎoshí, dànshì gēn Jiāyuè zuò zài yìqǐ, wǒ juéde shíjiān guò de hěn kuài.","speaker":"Đoạn văn","vi":"Tuy trên đường mất hơn mười tiếng đồng hồ, nhưng ngồi cùng Gia Nguyệt, tôi cảm thấy thời gian trôi qua rất nhanh."},{"hanzi":"到机场的时候，家月发现行李箱不见了，我带她去服务台，帮助她找到了行李箱。","pinyin":"Dào jīchǎng de shíhou, Jiāyuè fāxiàn xínglixiāng bújiàn le, wǒ dài tā qù fúwùtái, bāngzhù tā zhǎodào le xínglixiāng.","speaker":"Đoạn văn","vi":"Khi đến sân bay, Gia Nguyệt phát hiện va li hành lý không thấy đâu, tôi đưa cô ấy đến quầy dịch vụ và giúp cô ấy tìm lại được va li."},{"hanzi":"走出机场的时候，已经八点多了，我们一出来就看见了王老师的姐姐，她看起来比照片上年轻。","pinyin":"Zǒuchū jīchǎng de shíhou, yǐjīng bā diǎn duō le, wǒmen yì chūlái jiù kànjiàn le Wáng lǎoshī de jiějie, tā kànqǐlái bǐ zhàopiàn shàng niánqīng.","speaker":"Đoạn văn","vi":"Lúc đi ra khỏi sân bay đã hơn tám giờ rồi, chúng tôi vừa ra ngoài đã nhìn thấy chị gái của thầy/cô Vương, chị ấy trông trẻ hơn trong ảnh."},{"hanzi":"晚上，一雪姐带我们去吃了一家很好吃的中国菜。","pinyin":"Wǎnshang, Yīxuě jiě dài wǒmen qù chī le yì jiā hěn hǎochī de Zhōngguó cài.","speaker":"Đoạn văn","vi":"Buổi tối, chị Nhất Tuyết dẫn chúng tôi đi ăn ở một nhà hàng món Trung Quốc rất ngon."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài có câu \"虽然路上花了十几个小时，但是跟家月坐在一起，我觉得时间过得很快。\" (Tuy trên đường mất hơn mười tiếng, nhưng ngồi cùng Gia Nguyệt nên tôi thấy thời gian trôi qua rất nhanh.), nên đáp án đúng là vì ngồi cùng Bạch Gia Nguyệt.","options":["因为他在飞机上一直睡觉","因为飞机上有很多好吃的东西","因为他和白家月坐在一起","因为他一直在看电影和看书"],"q":"在飞机上花了十几个小时，李文为什么还是觉得时间过得很快？"},{"answerIdx":2,"explanation":"Trong bài có câu \"我们一出来就看见了王老师的姐姐，她看起来比照片上年轻。\" (Chúng tôi vừa ra ngoài đã nhìn thấy chị gái của thầy/cô Vương, chị ấy trông trẻ hơn trong ảnh.), nên đáp án đúng là trông trẻ hơn so với trong ảnh.","options":["比照片上胖一点儿","和照片上不太像","比照片上年轻","看起来很累，因为等了很久"],"q":"李文见到王老师的姐姐时，觉得她怎么样？"}],"scene":"在宾馆房间，李文在写日记。","sceneVi":"Trong phòng khách sạn, Lý Văn đang viết nhật ký."}],"hsk3-2":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"家月、李文，你们看看菜单，想吃点儿什么？","pinyin":"Jiāyuè, Lǐ Wén, nǐmen kànkan càidān, xiǎng chī diǎnr shénme?","speaker":"王一雪","vi":"Gia Nguyệt, Lý Văn, hai bạn xem thực đơn đi, muốn ăn chút gì nào?"},{"hanzi":"谢谢一雪姐，我都可以，你们点吧。","pinyin":"Xièxie Yīxuě jiě, wǒ dōu kěyǐ, nǐmen diǎn ba.","speaker":"李文","vi":"Cảm ơn chị Nhất Tuyết, em món gì cũng được, mọi người gọi đi ạ."},{"hanzi":"飞了这么远，现在还真是又饿又渴。","pinyin":"Fēi le zhème yuǎn, xiànzài hái zhēn shì yòu è yòu kě.","speaker":"白家月","vi":"Bay xa như vậy, giờ đúng là vừa đói vừa khát thật."},{"hanzi":"那多点点儿，别客气。你们喝什么饮料？","pinyin":"Nà duō diǎn diǎnr, bié kèqi. Nǐmen hē shénme yǐnliào?","speaker":"王一雪","vi":"Vậy gọi nhiều một chút đi, đừng khách sáo. Các bạn uống đồ uống gì?"},{"hanzi":"好久没喝中国茶，也好久没吃饺子了。我想喝绿茶、吃饺子，可以吗？","pinyin":"Hǎojiǔ méi hē Zhōngguó chá, yě hǎojiǔ méi chī jiǎozi le. Wǒ xiǎng hē lǜchá, chī jiǎozi, kěyǐ ma?","speaker":"白家月","vi":"Lâu rồi không uống trà Trung Quốc, cũng lâu rồi không ăn sủi cảo. Em muốn uống trà xanh và ăn sủi cảo, được không ạ?"},{"hanzi":"没问题。你们看看还想吃什么。","pinyin":"Méi wèntí. Nǐmen kànkan hái xiǎng chī shénme.","speaker":"王一雪","vi":"Không vấn đề gì. Các bạn xem còn muốn ăn gì nữa không."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"飞了这么远，现在还真是又饿又渴。\" (Bay xa như vậy, giờ đúng là vừa đói vừa khát.), nên đáp án đúng là vừa đói vừa khát.","options":["刚睡醒，不太想吃东西","又饿又渴","只是有点儿渴，不饿","又冷又累，只想喝热茶"],"q":"在饭馆点菜的时候，白家月现在感觉怎么样？"},{"answerIdx":2,"explanation":"Trong bài có câu \"我想喝绿茶、吃饺子，可以吗？\" (Em muốn uống trà xanh, ăn sủi cảo, được không ạ?), nên đáp án đúng là trà xanh và sủi cảo.","options":["红茶和面条","咖啡和蛋糕","绿茶和饺子","奶茶和烤鸭"],"q":"白家月想点什么饮料和吃的？"}],"scene":"在饭馆，王一雪、刘明、白家月和李文在点菜。","sceneVi":"Ở nhà hàng, Vương Nhất Tuyết, Lưu Minh, Bạch Gia Nguyệt và Lý Văn đang gọi món."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"服务员，再给我们拿一双筷子、一个勺子和一个碗。","pinyin":"Fúwùyuán, zài gěi wǒmen ná yì shuāng kuàizi, yí ge sháozi hé yí ge wǎn.","speaker":"王一雪","vi":"Nhân viên phục vụ ơi, lấy thêm cho chúng tôi một đôi đũa, một cái thìa và một cái bát nhé."},{"hanzi":"好的，请等一下，我马上去拿。","pinyin":"Hǎo de, qǐng děng yíxià, wǒ mǎshàng qù ná.","speaker":"服务员","vi":"Vâng ạ, xin đợi một chút, tôi đi lấy ngay đây."},{"hanzi":"这家饭馆的服务很热情，菜也都做得很好吃。你们尝尝，看喜不喜欢这些菜。","pinyin":"Zhè jiā fànguǎn de fúwù hěn rèqíng, cài yě dōu zuò de hěn hǎochī. Nǐmen chángchang, kàn xǐ bu xǐhuan zhèxiē cài.","speaker":"王一雪","vi":"Phục vụ của nhà hàng này rất nhiệt tình, món ăn cũng đều nấu rất ngon. Các bạn nếm thử xem có thích những món này không."},{"hanzi":"哪个菜都好吃。您点的这些菜真不错。","pinyin":"Nǎge cài dōu hǎochī. Nín diǎn de zhèxiē cài zhēn búcuò.","speaker":"白家月","vi":"Món nào cũng ngon cả. Những món chị gọi thật sự rất tuyệt."},{"hanzi":"这里的饭菜又便宜又好吃，我们经常来，服务员都记住我们爱吃的菜了。","pinyin":"Zhèlǐ de fàncài yòu piányi yòu hǎochī, wǒmen jīngcháng lái, fúwùyuán dōu jìzhù wǒmen ài chī de cài le.","speaker":"王一雪","vi":"Đồ ăn ở đây vừa rẻ vừa ngon, bọn chị thường xuyên đến, nhân viên phục vụ nhớ hết những món bọn chị thích ăn rồi."},{"hanzi":"王姐，您经常来吃饭，今天送您一些水果，请慢用。","pinyin":"Wáng jiě, nín jīngcháng lái chīfàn, jīntiān sòng nín yìxiē shuǐguǒ, qǐng màn yòng.","speaker":"服务员","vi":"Chị Vương, chị thường xuyên đến ăn, hôm nay xin tặng chị một ít hoa quả, chúc chị dùng bữa ngon miệng."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài có câu \"服务员，再给我们拿一双筷子、一个勺子和一个碗。\" (Phục vụ ơi, lấy thêm cho chúng tôi một đôi đũa, một cái thìa và một cái bát.), nên đáp án đúng là một đôi đũa, một cái thìa và một cái bát.","options":["一张菜单和一壶绿茶","两双筷子和两个盘子","一双筷子、一个勺子和一个碗","一双筷子和一些水果"],"q":"王一雪让服务员再拿什么东西过来？"},{"answerIdx":2,"explanation":"Trong bài có câu \"王姐，您经常来吃饭，今天送您一些水果，请慢用。\" (Chị Vương, chị thường xuyên đến ăn cơm, hôm nay quán tặng chị một ít hoa quả, chúc chị ngon miệng.), nên đáp án đúng là vì Vương Nhất Tuyết thường xuyên đến ăn ở nhà hàng này.","options":["因为今天饭馆刚刚开门","因为他们点了很多很贵的菜","因为王一雪经常来这家饭馆吃饭","因为今天是白家月的生日"],"q":"服务员为什么今天送给王一雪他们一些水果？"}],"scene":"在饭馆，王一雪、刘明、白家月和李文一起吃饭。","sceneVi":"Ở nhà hàng, Vương Nhất Tuyết, Lưu Minh, Bạch Gia Nguyệt và Lý Văn cùng nhau ăn cơm."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"这个鸡肉饭太好吃了，我要再来吃一次。","pinyin":"Zhège jīròufàn tài hǎochī le, wǒ yào zài lái chī yí cì.","speaker":"白家月","vi":"Món cơm gà này ngon quá đi mất, em nhất định phải đến ăn lại một lần nữa."},{"hanzi":"你可以拿走这张菜单，看看下次还吃点儿什么。","pinyin":"Nǐ kěyǐ názǒu zhè zhāng càidān, kànkan xià cì hái chī diǎnr shénme.","speaker":"李文","vi":"Bạn có thể cầm tờ thực đơn này về, xem lần sau còn muốn ăn thêm món gì nữa."},{"hanzi":"不用拿菜单，在手机上就能看到，也可以选好了让他们给你送。","pinyin":"Búyòng ná càidān, zài shǒujī shàng jiù néng kàndào, yě kěyǐ xuǎnhǎo le ràng tāmen gěi nǐ sòng.","speaker":"王一雪","vi":"Không cần lấy thực đơn đâu, trên điện thoại là xem được ngay, cũng có thể chọn xong rồi bảo họ giao đến cho bạn."},{"hanzi":"他们家还能送外卖？","pinyin":"Tāmen jiā hái néng sòng wàimài?","speaker":"白家月","vi":"Nhà hàng này còn có thể giao đồ ăn tận nơi nữa à?"},{"hanzi":"对，现在很多饭馆都能送外卖，想吃什么就点什么。","pinyin":"Duì, xiànzài hěn duō fànguǎn dōu néng sòng wàimài, xiǎng chī shénme jiù diǎn shénme.","speaker":"王一雪","vi":"Đúng vậy, bây giờ rất nhiều nhà hàng đều có thể giao đồ ăn, muốn ăn gì thì gọi món đó."},{"hanzi":"那真是太方便了！","pinyin":"Nà zhēn shì tài fāngbiàn le!","speaker":"白家月","vi":"Vậy thì thật sự tiện lợi quá rồi!"}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"这个鸡肉饭太好吃了，我要再来吃一次。\" (Cơm thịt gà này ngon quá, tôi nhất định sẽ quay lại ăn thêm một lần nữa.), nên đáp án đúng là vì cơm thịt gà ở đây quá ngon.","options":["因为这家饭馆的水果都是免费的","因为她觉得这里的鸡肉饭太好吃了","因为这里离她住的宾馆很近","因为服务员非常热情，还送了她菜单"],"q":"白家月为什么说以后还要再来这家饭馆吃一次？"},{"answerIdx":2,"explanation":"Trong bài có câu \"不用拿菜单，在手机上就能看到，也可以选好了让他们给你送。\" (Không cần cầm thực đơn đâu, trên điện thoại là xem được rồi, cũng có thể chọn xong rồi bảo họ giao đến cho bạn.) và \"现在很多饭馆都能送外卖\" (bây giờ rất nhiều nhà hàng đều có thể giao đồ ăn), nên đáp án đúng là xem thực đơn trên điện thoại và gọi giao đồ ăn tận nơi.","options":["必须拿着纸菜单来饭馆点","只能让李文帮忙打电话点菜","可以在手机上看菜单点菜，还能让饭馆送外卖","只能晚上去饭馆里吃，不能送外卖"],"q":"按照王一雪说的，白家月以后怎么点这家饭馆的菜？"}],"scene":"在饭馆，王一雪、刘明、白家月和李文继续边吃边聊。","sceneVi":"Ở nhà hàng, Vương Nhất Tuyết, Lưu Minh, Bạch Gia Nguyệt và Lý Văn tiếp tục vừa ăn vừa trò chuyện."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"这些年在国外，我很少自己做饭。","pinyin":"Zhèxiē nián zài guówài, wǒ hěn shǎo zìjǐ zuòfàn.","speaker":"Đoạn văn","vi":"Những năm qua ở nước ngoài, tôi rất ít khi tự nấu cơm."},{"hanzi":"早饭我吃一个面包，有时候吃一块蛋糕，再喝一杯咖啡。","pinyin":"Zǎofàn wǒ chī yí ge miànbāo, yǒushíhou chī yí kuài dàngāo, zài hē yì bēi kāfēi.","speaker":"Đoạn văn","vi":"Bữa sáng tôi ăn một chiếc bánh mì, thỉnh thoảng ăn một miếng bánh ngọt, rồi uống thêm một cốc cà phê."},{"hanzi":"午饭和晚饭也都在外面吃。","pinyin":"Wǔfàn hé wǎnfàn yě dōu zài wàimiàn chī.","speaker":"Đoạn văn","vi":"Bữa trưa và bữa tối cũng đều ăn ở ngoài."},{"hanzi":"快要考试的时候又忙又累，没时间出去吃饭，家里又什么吃的都没有，我可能好几天只吃方便面。","pinyin":"Kuài yào kǎoshì de shíhou yòu máng yòu lèi, méi shíjiān chūqù chīfàn, jiālǐ yòu shénme chī de dōu méiyǒu, wǒ kěnéng hǎo jǐ tiān zhǐ chī fāngbiànmiàn.","speaker":"Đoạn văn","vi":"Lúc sắp thi vừa bận vừa mệt, không có thời gian ra ngoài ăn, trong nhà lại chẳng có đồ gì để ăn, có thể mấy ngày liền tôi chỉ ăn mì ăn liền."},{"hanzi":"现在回到中国了，每天能吃到妈妈做的饭，我真是太高兴了！","pinyin":"Xiànzài huídào Zhōngguó le, měitiān néng chīdào māma zuò de fàn, wǒ zhēn shì tài gāoxìng le!","speaker":"Đoạn văn","vi":"Bây giờ về đến Trung Quốc rồi, ngày nào cũng được ăn cơm mẹ nấu, tôi thật sự vui quá!"},{"hanzi":"有时候妈妈只做几个简单的菜，我也非常爱吃，因为什么都没有妈妈做的饭好吃。","pinyin":"Yǒushíhou māma zhǐ zuò jǐ ge jiǎndān de cài, wǒ yě fēicháng ài chī, yīnwèi shénme dōu méiyǒu māma zuò de fàn hǎochī.","speaker":"Đoạn văn","vi":"Có lúc mẹ chỉ nấu vài món đơn giản thôi, tôi cũng rất thích ăn, vì chẳng có gì ngon bằng cơm mẹ nấu cả."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"快要考试的时候又忙又累，没时间出去吃饭，家里又什么吃的都没有，我可能好几天只吃方便面。\" (Lúc sắp thi vừa bận vừa mệt, không có thời gian ra ngoài ăn cơm, trong nhà lại chẳng có đồ ăn gì, có khi mấy ngày liền tôi chỉ ăn mì ăn liền.), nên đáp án đúng là vì vừa bận vừa mệt, không có thời gian ra ngoài ăn và trong nhà không có đồ ăn.","options":["因为他最喜欢吃方便面，不喜欢在外面吃","因为那时候他又忙又累，没时间出去吃饭，家里也没有别的东西吃","因为在国外买面包和蛋糕太贵了","因为他天天在学校图书馆学习，图书馆只卖方便面"],"q":"在国外的时候，为什么快要考试时李文可能好几天只吃方便面？"},{"answerIdx":2,"explanation":"Trong bài có câu \"现在回到中国了，每天能吃到妈妈做的饭，我真是太高兴了！\" (Bây giờ về Trung Quốc rồi, ngày nào cũng được ăn cơm mẹ nấu, tôi thật sự rất vui sướng!), nên đáp án đúng là mỗi ngày đều được ăn cơm mẹ nấu.","options":["在中国每天都可以吃饺子和鸡肉饭","回到中国以后不需要再参加考试了","每天都能吃到妈妈做的饭","可以经常去外面跟朋友一起吃方便面"],"q":"回到中国以后，什么事情让李文觉得非常高兴？"}],"scene":"在李文家，李文在写日记。","sceneVi":"Ở nhà Lý Văn, Lý Văn đang viết nhật ký."}],"hsk3-3":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"小雪的初中离家有点儿远，咱们换一个近点儿的房子吧。","pinyin":"Xiǎoxuě de chūzhōng lí jiā yǒudiǎnr yuǎn, zánmen huàn yí gè jìndiǎnr de fángzi ba.","speaker":"王一雪","vi":"Trường cấp hai của Tiểu Tuyết hơi xa nhà, chúng ta đổi sang một căn nhà gần hơn chút đi."},{"hanzi":"好啊，我上网看看。你觉得这个小区怎么样？","pinyin":"Hǎo a, wǒ shàngwǎng kànkan. Nǐ juéde zhège xiǎoqū zěnmeyàng?","speaker":"刘明","vi":"Được thôi, để anh lên mạng xem thử. Em thấy khu dân cư này thế nào?"},{"hanzi":"环境挺好的，离地铁站还不远。","pinyin":"Huánjìng tǐng hǎo de, lí dìtiězhàn hái bù yuǎn.","speaker":"王一雪","vi":"Môi trường khá tốt đấy, lại còn không xa ga tàu điện ngầm."},{"hanzi":"房子里面也不错，空调和洗衣机都是新的。","pinyin":"Fángzi lǐmiàn yě búcuò, kōngtiáo hé xǐyījī dōu shì xīn de.","speaker":"刘明","vi":"Bên trong nhà cũng ổn lắm, điều hòa và máy giặt đều là đồ mới."},{"hanzi":"是不错，但是我不喜欢住一层。","pinyin":"Shì búcuò, dànshì wǒ bù xǐhuan zhù yì céng.","speaker":"王一雪","vi":"Ổn thật đấy, nhưng em không thích ở tầng một."},{"hanzi":"这个一层带一个小花园，我觉得咱们可以去看看。","pinyin":"Zhège yì céng dài yí gè xiǎo huāyuán, wǒ juéde zánmen kěyǐ qù kànkan.","speaker":"刘明","vi":"Căn tầng một này có kèm một khu vườn nhỏ, anh thấy chúng ta có thể đi xem thử."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, Vương Nhất Tuyết nói \"小雪的初中离家有点儿远，咱们换一个近点儿的房子吧。\" (Trường cấp hai của Tiểu Tuyết hơi xa nhà, chúng ta đổi một căn nhà gần hơn chút đi.), nên lý do họ muốn đổi nhà là trường của Tiểu Tuyết cách nhà hơi xa.","options":["现在的房子没有小花园","小雪的初中离家有点儿远","现在的房子空调和洗衣机都坏了","现在的房子离地铁站太远了"],"q":"王一雪和刘明为什么想换房子？"},{"answerIdx":2,"explanation":"Trong bài, Vương Nhất Tuyết nói \"是不错，但是我不喜欢住一层。\" (Cũng ổn đấy, nhưng em không thích ở tầng một.), nên điểm khiến cô ấy chưa ưng ý là căn nhà nằm ở tầng một.","options":["小区的环境不太好","离地铁站太远了","房子在一层","房子里的空调太旧了"],"q":"关于刘明在网上看到的房子，王一雪不太喜欢什么？"}],"scene":"在家里，刘明和王一雪在聊天儿。","sceneVi":"Ở nhà, Lưu Minh và Vương Nhất Tuyết đang trò chuyện."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"我今天早上来的时候，灯还开着。","pinyin":"Wǒ jīntiān zǎoshang lái de shíhou, dēng hái kāizhe.","speaker":"王一雪","vi":"Sáng nay lúc em đến, đèn vẫn còn đang bật."},{"hanzi":"我这几天忙坏了，可能走的时候忘关了。","pinyin":"Wǒ zhè jǐ tiān máng huài le, kěnéng zǒu de shíhou wàng guān le.","speaker":"刘明","vi":"Mấy hôm nay anh bận muốn chết, có lẽ lúc đi quên tắt rồi."},{"hanzi":"冰箱不能用，这些吃的东西放在哪儿？","pinyin":"Bīngxiāng bù néng yòng, zhèxiē chī de dōngxi fàng zài nǎr?","speaker":"王一雪","vi":"Tủ lạnh không dùng được, mấy đồ ăn này để ở đâu bây giờ?"},{"hanzi":"不可能吧？冰箱是新买的，我来看看。","pinyin":"Bù kěnéng ba? Bīngxiāng shì xīn mǎi de, wǒ lái kànkan.","speaker":"刘明","vi":"Không thể nào chứ? Tủ lạnh là mới mua mà, để anh ra xem thử."},{"hanzi":"洗衣机也坏了吗？","pinyin":"Xǐyījī yě huài le ma?","speaker":"王一雪","vi":"Máy giặt cũng hỏng rồi à?"},{"hanzi":"没坏，但是卫生间没打扫好，还不能洗衣服。","pinyin":"Méi huài, dànshì wèishēngjiān méi dǎsǎo hǎo, hái bù néng xǐ yīfu.","speaker":"刘明","vi":"Không hỏng, nhưng nhà vệ sinh chưa dọn xong nên vẫn chưa giặt quần áo được."},{"hanzi":"星期天我们真的能搬家吗？","pinyin":"Xīngqītiān wǒmen zhēn de néng bānjiā ma?","speaker":"王一雪","vi":"Chủ nhật chúng ta thật sự chuyển nhà được không đấy?"}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, Lưu Minh nói \"我这几天忙坏了，可能走的时候忘关了。\" (Mấy hôm nay anh bận túi bụi, có lẽ lúc đi quên tắt rồi.), nên đèn vẫn bật là do Lưu Minh có thể đã quên tắt khi rời đi.","options":["王一雪昨天晚上忘记关了","刘明走的时候可能忘记关了","家里一直有人在收拾房间","新家的灯坏了，关不上"],"q":"王一雪今天早上来新家时，为什么灯还开着？"},{"answerIdx":2,"explanation":"Trong bài, Lưu Minh giải thích \"没坏，但是卫生间没打扫好，还不能洗衣服。\" (Không hỏng đâu, nhưng nhà vệ sinh chưa dọn xong, vẫn chưa giặt đồ được.), nên nguyên nhân chưa giặt đồ được là nhà vệ sinh chưa dọn xong.","options":["洗衣机是旧的，已经坏了","新家还没有买洗衣机","卫生间还没有打扫好","房间里没有地方放衣服"],"q":"现在为什么还不能在新家洗衣服？"}],"scene":"在新家，王一雪在收拾房间，刘明进来了。","sceneVi":"Ở nhà mới, Vương Nhất Tuyết đang dọn dẹp phòng thì Lưu Minh bước vào."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"这个月花了不少钱。","pinyin":"Zhège yuè huā le bù shǎo qián.","speaker":"王一雪","vi":"Tháng này tiêu không ít tiền rồi."},{"hanzi":"是的，我们买了很多搬家时要用的东西。","pinyin":"Shì de, wǒmen mǎi le hěn duō bānjiā shí yào yòng de dōngxi.","speaker":"刘明","vi":"Đúng vậy, chúng ta đã mua rất nhiều đồ cần dùng khi chuyển nhà."},{"hanzi":"咱们办张信用卡吧，花的钱可以慢慢还。听说中国银行的服务不错，办了信用卡买东西还能便宜。","pinyin":"Zánmen bàn zhāng xìnyòngkǎ ba, huā de qián kěyǐ mànmàn huán. Tīngshuō Zhōngguó Yínháng de fúwù búcuò, bàn le xìnyòngkǎ mǎi dōngxi hái néng piányi.","speaker":"王一雪","vi":"Chúng ta làm một chiếc thẻ tín dụng đi, tiền tiêu rồi có thể từ từ trả. Nghe nói dịch vụ của Ngân hàng Trung Quốc khá tốt, làm thẻ tín dụng rồi khi mua đồ còn được rẻ hơn nữa."},{"hanzi":"好啊！中国银行很近，走路几分钟就能到。咱们什么时候去？","pinyin":"Hǎo a! Zhōngguó Yínháng hěn jìn, zǒulù jǐ fēnzhōng jiù néng dào. Zánmen shénme shíhou qù?","speaker":"刘明","vi":"Được đấy! Ngân hàng Trung Quốc rất gần, đi bộ vài phút là tới. Bao giờ chúng ta đi?"},{"hanzi":"今天下午？","pinyin":"Jīntiān xiàwǔ?","speaker":"王一雪","vi":"Chiều nay thì sao?"},{"hanzi":"我下午要去医院，很晚才能回来。","pinyin":"Wǒ xiàwǔ yào qù yīyuàn, hěn wǎn cái néng huílái.","speaker":"刘明","vi":"Chiều nay anh phải đi bệnh viện, rất muộn mới về được."},{"hanzi":"那我下午自己去吧。","pinyin":"Nà wǒ xiàwǔ zìjǐ qù ba.","speaker":"王一雪","vi":"Vậy chiều nay em tự đi nhé."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, Vương Nhất Tuyết nói \"听说中国银行的服务不错，办了信用卡买东西还能便宜。\" (Nghe nói dịch vụ của Ngân hàng Trung Quốc rất tốt, làm thẻ tín dụng rồi mua đồ còn được rẻ hơn.), nên đó là lý do cô ấy muốn làm thẻ ở Ngân hàng Trung Quốc.","options":["因为中国银行就在医院旁边","因为中国银行服务不错，买东西还能便宜","因为他们还没有钱买搬家的东西","因为刘明在中国银行工作"],"q":"王一雪为什么想办中国银行的信用卡？"},{"answerIdx":2,"explanation":"Trong bài, vì buổi chiều Lưu Minh phải đi bệnh viện và về muộn nên Vương Nhất Tuyết nói \"那我下午自己去吧。\" (Vậy chiều nay em tự đi vậy.), nên chiều nay Vương Nhất Tuyết sẽ tự đi ngân hàng.","options":["刘明一个人去","王一雪和刘明一起去","王一雪自己去","他们明天上午再去"],"q":"今天下午谁去银行办信用卡？"}],"scene":"在家里，刘明和王一雪在客厅聊天儿。","sceneVi":"Ở nhà, Lưu Minh và Vương Nhất Tuyết đang trò chuyện ở phòng khách."},{"id":4,"isNarrative":false,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"我觉得这个星期就能搬家。我明天去买一些纸箱，很快就能准备好。搬家那天，我想请几位朋友来帮忙，最多一天就能搬完。","pinyin":"Wǒ juéde zhège xīngqī jiù néng bānjiā. Wǒ míngtiān qù mǎi yìxiē zhǐxiāng, hěn kuài jiù néng zhǔnbèi hǎo. Bānjiā nà tiān, wǒ xiǎng qǐng jǐ wèi péngyou lái bāngmáng, zuìduō yì tiān jiù néng bān wán.","speaker":"刘明","vi":"Anh thấy tuần này là có thể chuyển nhà được rồi. Ngày mai anh đi mua ít thùng giấy, rất nhanh sẽ chuẩn bị xong. Hôm chuyển nhà, anh định nhờ vài người bạn đến giúp, nhiều nhất một ngày là chuyển xong."},{"hanzi":"我觉得下个月才能搬家。这周开始准备，下周去打扫新家，这么多事情最少需要两个星期才能做完。搬家那天，我们应该找一家搬家公司。","pinyin":"Wǒ juéde xià gè yuè cái néng bānjiā. Zhè zhōu kāishǐ zhǔnbèi, xià zhōu qù dǎsǎo xīnjiā, zhème duō shìqing zuìshǎo xūyào liǎng gè xīngqī cái néng zuò wán. Bānjiā nà tiān, wǒmen yīnggāi zhǎo yì jiā bānjiā gōngsī.","speaker":"王一雪","vi":"Em thấy tháng sau mới chuyển nhà được. Tuần này bắt đầu chuẩn bị, tuần sau đi dọn dẹp nhà mới, nhiều việc thế này ít nhất cần hai tuần mới làm xong. Hôm chuyển nhà, chúng ta nên tìm một công ty chuyển nhà."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, Lưu Minh nói \"我觉得这个星期就能搬家……搬家那天，我想请几位朋友来帮忙，最多一天就能搬完。\" (Anh thấy tuần này là có thể chuyển nhà rồi... Ngày chuyển nhà, anh muốn mời vài người bạn đến giúp, nhiều nhất một ngày là chuyển xong.), nên anh ấy định chuyển nhà trong tuần này và nhờ vài người bạn đến giúp.","options":["下个月请搬家公司来帮忙","这个星期请几位朋友来帮忙","明天一个人先搬一部分东西","等两个星期以后再找朋友帮忙"],"q":"关于搬家，刘明打算怎么搬？"},{"answerIdx":2,"explanation":"Trong bài, Vương Nhất Tuyết nói \"这周开始准备，下周去打扫新家，这么多事情最少需要两个星期才能做完。\" (Tuần này bắt đầu chuẩn bị, tuần sau đi dọn nhà mới, nhiều việc như vậy ít nhất cần hai tuần mới làm xong.), nên cô ấy cho rằng tháng sau mới chuyển nhà được.","options":["因为她明天买不到纸箱","因为朋友这个星期没有时间","因为这么多事情最少需要两个星期才能做完","因为搬家公司这个月没有空"],"q":"王一雪为什么觉得下个月才能搬家？"}],"scene":"在家里，刘明和王一雪讨论搬家计划。","sceneVi":"Ở nhà, Lưu Minh và Vương Nhất Tuyết đang thảo luận kế hoạch chuyển nhà."}],"hsk3-4":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"这个假期咱们去哪儿玩玩吧。","pinyin":"Zhège jiàqī zánmen qù nǎr wánwan ba.","speaker":"杨同乐","vi":"Kỳ nghỉ này chúng mình đi đâu đó chơi đi."},{"hanzi":"好啊，你想去哪儿，咱们就去哪儿。","pinyin":"Hǎo a, nǐ xiǎng qù nǎr, zánmen jiù qù nǎr.","speaker":"王一飞","vi":"Được thôi, anh muốn đi đâu thì chúng mình đi đấy."},{"hanzi":"你喜欢海，找个海边住几天，怎么样？","pinyin":"Nǐ xǐhuan hǎi, zhǎo gè hǎibiān zhù jǐ tiān, zěnmeyàng?","speaker":"杨同乐","vi":"Em thích biển, tìm một vùng biển ở vài ngày thì sao?"},{"hanzi":"现在去海边有点儿冷。","pinyin":"Xiànzài qù hǎibiān yǒudiǎnr lěng.","speaker":"王一飞","vi":"Bây giờ đi biển hơi lạnh."},{"hanzi":"那去草原吧？草原一点儿也不冷。","pinyin":"Nà qù cǎoyuán ba? Cǎoyuán yìdiǎnr yě bù lěng.","speaker":"杨同乐","vi":"Thế đi thảo nguyên nhé? Thảo nguyên không lạnh chút nào đâu."},{"hanzi":"这个主意好！我好久没骑马了。","pinyin":"Zhège zhǔyi hǎo! Wǒ hǎojiǔ méi qímǎ le.","speaker":"王一飞","vi":"Ý kiến này hay đấy! Em lâu lắm rồi chưa cưỡi ngựa."},{"hanzi":"对，在草原上骑马、吃羊肉、看月亮，一定很有意思。","pinyin":"Duì, zài cǎoyuán shàng qímǎ, chī yángròu, kàn yuèliang, yídìng hěn yǒuyìsi.","speaker":"杨同乐","vi":"Đúng vậy, cưỡi ngựa, ăn thịt cừu, ngắm trăng trên thảo nguyên chắc chắn rất thú vị."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, khi Dương Đồng Nhạc gợi ý đi biển, Vương Nhất Phi trả lời \"现在去海边有点儿冷。\" (Bây giờ đi biển hơi lạnh.), nên lý do anh ấy không muốn đi biển là trời hơi lạnh.","options":["因为他不喜欢海","因为现在去海边有点儿冷","因为海边没有好玩儿的地方","因为他更想去看月亮"],"q":"王一飞为什么现在不想去海边？"},{"answerIdx":1,"explanation":"Trong bài, Dương Đồng Nhạc nói \"在草原上骑马、吃羊肉、看月亮，一定很有意思。\" (Ở trên thảo nguyên cưỡi ngựa, ăn thịt cừu, ngắm trăng, nhất định rất thú vị.), nên họ có thể cưỡi ngựa, ăn thịt cừu và ngắm trăng.","options":["游泳、吃海鲜、晒太阳","骑马、吃羊肉、看月亮","爬山、照相、喝茶","散步、看星星、吃水果"],"q":"根据对话，他们决定去草原做什么？"}],"scene":"在王一飞家客厅，杨同乐和王一飞在聊天儿。","sceneVi":"Tại phòng khách nhà Vương Nhất Phi, Dương Đồng Nhạc và Vương Nhất Phi đang trò chuyện."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"出去玩的机票买好了吗？","pinyin":"Chūqù wán de jīpiào mǎi hǎo le ma?","speaker":"杨同乐","vi":"Vé máy bay đi chơi đã mua xong chưa?"},{"hanzi":"买好了。星期六上午十点一刻起飞。","pinyin":"Mǎi hǎo le. Xīngqīliù shàngwǔ shí diǎn yí kè qǐfēi.","speaker":"王一飞","vi":"Mua xong rồi. 10 giờ 15 phút sáng thứ Bảy cất cánh."},{"hanzi":"宾馆也选好了吗？","pinyin":"Bīnguǎn yě xuǎn hǎo le ma?","speaker":"杨同乐","vi":"Khách sạn cũng chọn xong rồi à?"},{"hanzi":"是的，这家宾馆很特别，跟别的都不一样，一出门就能看见牛和羊！","pinyin":"Shì de, zhè jiā bīnguǎn hěn tèbié, gēn biéde dōu bù yíyàng, yì chūmén jiù néng kànjiàn niú hé yáng!","speaker":"王一飞","vi":"Đúng vậy, khách sạn này rất đặc biệt, không giống bất kỳ chỗ nào khác, vừa bước ra cửa là có thể nhìn thấy trâu bò và cừu!"},{"hanzi":"太好了！你看看要带什么东西？","pinyin":"Tài hǎo le! Nǐ kànkan yào dài shénme dōngxi?","speaker":"杨同乐","vi":"Tuyệt quá! Em xem thử cần mang theo những gì?"},{"hanzi":"我们不用带太多东西，别忘了拿上新买的相机。","pinyin":"Wǒmen búyòng dài tài duō dōngxi, bié wàng le náshang xīn mǎi de xiàngjī.","speaker":"王一飞","vi":"Chúng ta không cần mang quá nhiều đồ đâu, đừng quên mang theo chiếc máy ảnh mới mua nhé."},{"hanzi":"一定不会忘带的。我现在就去准备行李。","pinyin":"Yídìng bú huì wàng dài de. Wǒ xiànzài jiù qù zhǔnbèi xíngli.","speaker":"杨同乐","vi":"Chắc chắn sẽ không quên mang đâu. Anh đi chuẩn bị hành lý ngay đây."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài, Vương Nhất Phi giới thiệu \"这家宾馆很特别，跟别的都不一样，一出门就能看见牛和羊！\" (Khách sạn này rất đặc biệt, không giống những nơi khác, vừa ra khỏi cửa là có thể nhìn thấy bò và cừu!), nên điểm đặc biệt là ra khỏi cửa đã thấy bò và cừu.","options":["离飞机场特别近","房间里有很多新东西","一出门就能看见牛和羊","是新开的，非常便宜"],"q":"王一飞选的宾馆有什么特别的地方？"},{"answerIdx":3,"explanation":"Trong bài, Vương Nhất Phi dặn \"我们不用带太多东西，别忘了拿上新买的相机。\" (Chúng ta không cần mang quá nhiều đồ, đừng quên mang theo chiếc máy ảnh mới mua.), nên thứ không được quên mang theo là chiếc máy ảnh mới mua.","options":["护照和机票","厚衣服和运动鞋","吃的东西和水果","新买的相机"],"q":"王一飞提醒杨同乐别忘了带什么？"}],"scene":"在王一飞家客厅，杨同乐和王一飞在聊天儿。","sceneVi":"Tại phòng khách nhà Vương Nhất Phi, Dương Đồng Nhạc và Vương Nhất Phi đang trò chuyện."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"欢迎你们！我是你们的司机，我姓李，叫我小李就可以。","pinyin":"Huānyíng nǐmen! Wǒ shì nǐmen de sījī, wǒ xìng Lǐ, jiào wǒ Xiǎo Lǐ jiù kěyǐ.","speaker":"小李","vi":"Chào mừng anh chị! Tôi là tài xế của anh chị, tôi họ Lý, gọi tôi là Tiểu Lý là được."},{"hanzi":"您好！不好意思，飞机晚点了，让您久等了。","pinyin":"Nínhǎo! Bùhǎoyìsi, fēijī wǎndiǎn le, ràng nín jiǔ děng le.","speaker":"杨同乐","vi":"Chào anh! Ngại quá, máy bay bị trễ chuyến, để anh phải đợi lâu rồi."},{"hanzi":"没关系。除了这个行李箱以外，还有别的东西吗？","pinyin":"Méi guānxi. Chúle zhège xínglixiāng yǐwài, hái yǒu biéde dōngxi ma?","speaker":"小李","vi":"Không sao đâu. Ngoài chiếc vali này ra, còn đồ đạc nào khác nữa không ạ?"},{"hanzi":"还有一个包，我自己拿就可以。","pinyin":"Hái yǒu yí gè bāo, wǒ zìjǐ ná jiù kěyǐ.","speaker":"杨同乐","vi":"Còn một cái túi nữa, tôi tự cầm là được rồi."},{"hanzi":"车在一层，请跟我来。","pinyin":"Chē zài yì céng, qǐng gēn wǒ lái.","speaker":"小李","vi":"Xe đỗ ở tầng một, xin mời đi theo tôi."},{"hanzi":"我们住的宾馆离机场远吗？","pinyin":"Wǒmen zhù de bīnguǎn lí jīchǎng yuǎn ma?","speaker":"杨同乐","vi":"Khách sạn chúng tôi ở có xa sân bay không?"},{"hanzi":"不远，三十分钟就能到。两位到了可以先休息休息，晚饭的时候我叫你们。","pinyin":"Bù yuǎn, sānshí fēnzhōng jiù néng dào. Liǎng wèi dào le kěyǐ xiān xiūxi xiūxi, wǎnfàn de shíhou wǒ jiào nǐmen.","speaker":"小李","vi":"Không xa đâu, ba mươi phút là tới. Hai anh chị đến nơi có thể nghỉ ngơi trước một lát, đến giờ ăn tối tôi sẽ gọi anh chị."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, Dương Đồng Nhạc nói \"不好意思，飞机晚点了，让您久等了。\" (Ngại quá, máy bay bị trễ chuyến, để anh đợi lâu rồi.), nên lý do họ đến muộn là máy bay bị trễ chuyến.","options":["因为他们找错了机场的门","因为他们的飞机晚点了","因为他们带的行李太多了","因为他们起床起晚了"],"q":"为什么杨同乐对小李说“不好意思，让您久等了”？"},{"answerIdx":2,"explanation":"Trong bài, Tiểu Lý nói \"不远，三十分钟就能到。\" (Không xa đâu, ba mươi phút là tới rồi.), mà 30 phút chính là nửa tiếng (半个小时), nên đáp án đúng là nửa tiếng.","options":["十五分钟","二十分钟","半个小时","一个小时"],"q":"从机场到他们住的宾馆要多长时间？"}],"scene":"在机场，杨同乐和王一飞走出来，跟他们预约的司机兼导游见面。","sceneVi":"Tại sân bay, Dương Đồng Nhạc và Vương Nhất Phi bước ra ngoài, gặp tài xế kiêm hướng dẫn viên mà họ đã đặt trước."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"今天是我们旅游的第一天。","pinyin":"Jīntiān shì wǒmen lǚyóu de dì-yī tiān.","speaker":"Đoạn văn","vi":"Hôm nay là ngày đầu tiên trong chuyến du lịch của chúng tôi."},{"hanzi":"我们很早就起床去机场了，没想到飞机晚点了。","pinyin":"Wǒmen hěn zǎo jiù qǐchuáng qù jīchǎng le, méi xiǎngdào fēijī wǎndiǎn le.","speaker":"Đoạn văn","vi":"Chúng tôi dậy rất sớm để ra sân bay, không ngờ máy bay lại bị trễ chuyến."},{"hanzi":"我们到的时候，天已经黑了，但是司机小李一直在机场等我们，一点儿也没着急。","pinyin":"Wǒmen dào de shíhou, tiān yǐjīng hēi le, dànshì sījī Xiǎo Lǐ yìzhí zài jīchǎng děng wǒmen, yìdiǎnr yě méi zháojí.","speaker":"Đoạn văn","vi":"Lúc chúng tôi đến nơi thì trời đã tối rồi, nhưng tài xế Tiểu Lý vẫn luôn đợi chúng tôi ở sân bay, không hề sốt ruột chút nào."},{"hanzi":"他特别热情，路上给我们介绍了很多东西，还准备了水果。","pinyin":"Tā tèbié rèqíng, lùshang gěi wǒmen jièshào le hěn duō dōngxi, hái zhǔnbèi le shuǐguǒ.","speaker":"Đoạn văn","vi":"Anh ấy cực kỳ nhiệt tình, trên đường đi giới thiệu cho chúng tôi rất nhiều thứ, lại còn chuẩn bị cả hoa quả nữa."},{"hanzi":"宾馆的房间跟我想的一样漂亮，又大又干净，我非常满意。","pinyin":"Bīnguǎn de fángjiān gēn wǒ xiǎng de yíyàng piàoliang, yòu dà yòu gānjìng, wǒ fēicháng mǎnyì.","speaker":"Đoạn văn","vi":"Phòng khách sạn đẹp đúng như tôi nghĩ, vừa rộng rãi vừa sạch sẽ, tôi vô cùng hài lòng."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài có câu \"司机小李一直在机场等我们，一点儿也没着急。他特别热情，路上给我们介绍了很多东西，还准备了水果。\" (Tài xế Tiểu Lý luôn đợi chúng tôi ở sân bay, không hề sốt ruột chút nào. Anh ấy vô cùng nhiệt tình, trên đường giới thiệu cho chúng tôi rất nhiều thứ, còn chuẩn bị cả trái cây.), nên câu đúng là anh ấy luôn đợi ở sân bay và còn chuẩn bị trái cây.","options":["因为等太久，他有点儿着急","他在路上只开车，没说话","他一直在机场等，还准备了水果","他没有去机场，在宾馆等他们"],"q":"关于司机小李，下面哪句话是对的？"},{"answerIdx":0,"explanation":"Trong bài có câu \"宾馆的房间跟我想的一样漂亮，又大又干净，我非常满意。\" (Phòng khách sạn đẹp giống như tôi nghĩ, vừa rộng vừa sạch, tôi vô cùng hài lòng.), nên Vương Nhất Phi nhận xét phòng vừa rộng vừa sạch và rất hài lòng.","options":["又大又干净，非常满意","很漂亮，但是有点儿小","很干净，但是离路边太近","跟他想的不太一样，有点儿旧"],"q":"王一飞觉得宾馆的房间怎么样？"}],"scene":"在宾馆房间，王一飞在写日记。","sceneVi":"Trong phòng khách sạn, Vương Nhất Phi đang viết nhật ký."}],"hsk3-5":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"这个星期总是阴天，今天终于晴了。","pinyin":"Zhège xīngqī zǒngshì yīntiān, jīntiān zhōngyú qíng le.","speaker":"白家月","vi":"Tuần này lúc nào cũng âm u, hôm nay cuối cùng cũng nắng rồi."},{"hanzi":"现在天气好得很！我们去爬山怎么样？","pinyin":"Xiànzài tiānqì hǎo de hěn! Wǒmen qù páshān zěnmeyàng?","speaker":"李文","vi":"Bây giờ thời tiết đẹp lắm! Chúng ta đi leo núi thế nào?"},{"hanzi":"好啊！又能锻炼身体，又能照好看的照片。","pinyin":"Hǎo a! Yòu néng duànliàn shēntǐ, yòu néng zhào hǎokàn de zhàopiàn.","speaker":"白家月","vi":"Được đấy! Vừa rèn luyện sức khỏe được, vừa chụp được những bức ảnh đẹp."},{"hanzi":"那我带点儿水和吃的，咱们现在就去？","pinyin":"Nà wǒ dài diǎnr shuǐ hé chī de, zánmen xiànzài jiù qù?","speaker":"李文","vi":"Vậy mình mang một chút nước và đồ ăn, bây giờ chúng ta đi luôn nhé?"},{"hanzi":"我回去穿上运动鞋，拿上大衣。要不要叫一雪姐一起去？","pinyin":"Wǒ huíqù chuānshàng yùndòngxié, náshàng dàyī. Yào bu yào jiào Yīxuě jiě yìqǐ qù?","speaker":"白家月","vi":"Mình về đi giày thể thao, lấy áo khoác. Có nên rủ chị Nhất Tuyết đi cùng không?"},{"hanzi":"好主意。给她打个电话吧。","pinyin":"Hǎo zhǔyi. Gěi tā dǎ ge diànhuà ba.","speaker":"李文","vi":"Ý kiến hay đấy. Gọi điện thoại cho chị ấy đi."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài, Bạch Gia Nguyệt nói \"这个星期总是阴天，今天终于晴了。\" (Tuần này toàn trời âm u, hôm nay cuối cùng cũng nắng rồi.) và Lý Văn nói \"现在天气好得很！\" (Bây giờ thời tiết đẹp lắm!), nên hôm nay trời cuối cùng đã nắng và thời tiết rất đẹp.","options":["还是阴天，有点儿冷","下小雨了，不能爬山","终于晴了，天气很好","刮风了，需要穿大衣"],"q":"今天的天气怎么样？"},{"answerIdx":1,"explanation":"Trong bài, Bạch Gia Nguyệt nói \"我回去穿上运动鞋，拿上大衣。\" (Tôi về xỏ giày thể thao, lấy thêm áo khoác dài.), nên trước khi đi leo núi cô ấy cần về nhà đi giày thể thao và lấy áo khoác.","options":["带点儿水和吃的东西","穿运动鞋，拿上大衣","拿照相机和手机","去叫王一雪一起出发"],"q":"去爬山以前，白家月要回家做什么？"}],"scene":"在街上，白家月和李文边散步边聊天儿。","sceneVi":"Trên đường, Bạch Gia Nguyệt và Lý Văn vừa đi dạo vừa trò chuyện."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"这些照片是谁给您照的？张张都非常好看。","pinyin":"Zhèxiē zhàopiàn shì shéi gěi nín zhào de? Zhāngzhāng dōu fēicháng hǎokàn.","speaker":"白家月","vi":"Những bức ảnh này là ai chụp cho chị thế? Tấm nào cũng rất đẹp."},{"hanzi":"一飞。她对拍照一直很感兴趣，经常给我照相。","pinyin":"Yīfēi. Tā duì pāizhào yìzhí hěn gǎn xìngqù, jīngcháng gěi wǒ zhàoxiàng.","speaker":"王一雪","vi":"Nhất Phi. Em ấy trước giờ rất thích chụp ảnh, thường xuyên chụp ảnh cho chị."},{"hanzi":"我喜欢您大笑的这张，看起来很漂亮。","pinyin":"Wǒ xǐhuan nín dàxiào de zhè zhāng, kàn qǐlái hěn piàoliang.","speaker":"白家月","vi":"Em thích tấm chị cười lớn này, trông rất xinh đẹp."},{"hanzi":"我觉得这张有点儿难看，那时候我不知道她在给我照相。","pinyin":"Wǒ juéde zhè zhāng yǒudiǎnr nánkàn, nà shíhou wǒ bù zhīdào tā zài gěi wǒ zhàoxiàng.","speaker":"王一雪","vi":"Chị thấy tấm này hơi xấu một chút, lúc đó chị không biết em ấy đang chụp ảnh cho chị."},{"hanzi":"这样的照片才好看。我也喜欢拍照，爬山的时候我给您照几张照片吧。","pinyin":"Zhèyàng de zhàopiàn cái hǎokàn. Wǒ yě xǐhuan pāizhào, páshān de shíhou wǒ gěi nín zhào jǐ zhāng zhàopiàn ba.","speaker":"白家月","vi":"Ảnh như thế này mới đẹp chứ. Em cũng thích chụp ảnh, lúc leo núi em chụp cho chị vài tấm nhé."},{"hanzi":"好，我可以比较一下你们两个谁的水平高。","pinyin":"Hǎo, wǒ kěyǐ bǐjiào yíxià nǐmen liǎng ge shéi de shuǐpíng gāo.","speaker":"王一雪","vi":"Được, chị có thể so sánh xem trình độ của hai đứa ai cao hơn."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, Vương Nhất Tuyết nói \"我觉得这张有点儿难看，那时候我不知道她在给我照相。\" (Chị thấy tấm này hơi xấu, lúc đó chị không biết em ấy đang chụp ảnh cho chị.), nên lý do là lúc đó chị ấy không biết Nhất Phi đang chụp ảnh cho mình.","options":["因为那张照片照得不清楚","因为照相的时候她不知道一飞在拍照","因为一飞对拍照不感兴趣","因为当时天气不好，没有太阳"],"q":"王一雪为什么觉得自己大笑的那张照片有点儿难看？"},{"answerIdx":2,"explanation":"Trong bài, Bạch Gia Nguyệt nói \"我也喜欢拍照，爬山的时候我给您照几张照片吧。\" (Em cũng thích chụp ảnh, lúc leo núi em chụp cho chị vài tấm nhé.), nên cô ấy định chụp cho Vương Nhất Tuyết vài bức ảnh.","options":["请一飞给她们两个拍照","教王一雪怎么用手机拍照","给王一雪照几张照片","看看王一雪的手机里有什么照片"],"q":"爬山的时候，白家月打算做什么？"}],"scene":"在出租车上，王一雪和白家月在聊天儿。","sceneVi":"Trên xe taxi, Vương Nhất Tuyết và Bạch Gia Nguyệt đang trò chuyện."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"家月，这里挺漂亮的，咱们在这里拍照吧。","pinyin":"Jiāyuè, zhèlǐ tǐng piàoliang de, zánmen zài zhèlǐ pāizhào ba.","speaker":"王一雪","vi":"Gia Nguyệt, chỗ này đẹp ghê, chúng ta chụp ảnh ở đây đi."},{"hanzi":"这边没有太阳，咱们去那边吧。","pinyin":"Zhèbiān méiyǒu tàiyáng, zánmen qù nàbiān ba.","speaker":"白家月","vi":"Bên này không có nắng, chúng ta sang bên kia đi."},{"hanzi":"好。你觉得我站在这些树中间怎么样？","pinyin":"Hǎo. Nǐ juéde wǒ zhàn zài zhèxiē shù zhōngjiān zěnmeyàng?","speaker":"王一雪","vi":"Được. Em thấy chị đứng ở giữa những cái cây này thế nào?"},{"hanzi":"挺好的。等一下，后边走过去两个人。","pinyin":"Tǐng hǎo de. Děng yíxià, hòubiān zǒu guòqù liǎng ge rén.","speaker":"白家月","vi":"Đẹp lắm. Đợi một chút, phía sau có hai người đi qua."},{"hanzi":"我准备好了，你照的时候告诉我。","pinyin":"Wǒ zhǔnbèi hǎo le, nǐ zhào de shíhou gàosu wǒ.","speaker":"王一雪","vi":"Chị chuẩn bị xong rồi, lúc nào em chụp thì bảo chị nhé."},{"hanzi":"你不用看着我，想干什么都可以。","pinyin":"Nǐ búyòng kànzhe wǒ, xiǎng gàn shénme dōu kěyǐ.","speaker":"白家月","vi":"Chị không cần nhìn vào em đâu, muốn làm gì cũng được."},{"hanzi":"树上飞来了几只鸟，我就看它们吧。","pinyin":"Shù shang fēi lái le jǐ zhī niǎo, wǒ jiù kàn tāmen ba.","speaker":"王一雪","vi":"Trên cây có mấy con chim bay tới, chị nhìn chúng nó vậy."},{"hanzi":"啊，手机没电了。","pinyin":"A, shǒujī méi diàn le.","speaker":"白家月","vi":"Á, điện thoại hết pin rồi."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài, Bạch Gia Nguyệt nói \"挺好的。等一下，后边走过去两个人。\" (Đẹp lắm. Đợi chút, phía sau có hai người đi qua.), nên cô ấy bảo Vương Nhất Tuyết đợi một lát vì có hai người đi qua phía sau.","options":["因为那边没有太阳","因为手机突然没电了","因为后边走过去两个人","因为树上飞来了几只鸟"],"q":"王一雪站在树中间以后，白家月为什么让她等一下？"},{"answerIdx":3,"explanation":"Trong bài, ở câu cuối Bạch Gia Nguyệt nói \"啊，手机没电了。\" (Á, điện thoại hết pin rồi.), nên cuối cùng họ không chụp được ảnh ngay lúc đó vì điện thoại của Bạch Gia Nguyệt hết pin.","options":["拍到了，她拍了王一雪看鸟的照片","没拍到，因为树太多，看不清楚","没拍到，因为后边一直有人走过去","没拍到，因为白家月的手机没电了"],"q":"最后白家月给王一雪拍到照片了吗？为什么？"}],"scene":"在山上，王一雪和白家月边走边聊。","sceneVi":"Trên núi, Vương Nhất Tuyết và Bạch Gia Nguyệt vừa đi vừa trò chuyện."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"家月，我收到了你的那封邮件，也看到了你给我照的照片，张张都很漂亮。","pinyin":"Jiāyuè, wǒ shōudào le nǐ de nà fēng yóujiàn, yě kàndào le nǐ gěi wǒ zhào de zhàopiàn, zhāngzhāng dōu hěn piàoliang.","speaker":"Đoạn văn","vi":"Gia Nguyệt, chị nhận được email của em rồi, cũng đã xem những bức ảnh em chụp cho chị, tấm nào cũng rất đẹp."},{"hanzi":"我已经告诉了一飞，你的拍照水平比她高，她难过得很，哈哈。","pinyin":"Wǒ yǐjīng gàosu le Yīfēi, nǐ de pāizhào shuǐpíng bǐ tā gāo, tā nánguò de hěn, hāhā.","speaker":"Đoạn văn","vi":"Chị đã nói với Nhất Phi rồi, trình độ chụp ảnh của em cao hơn em ấy, em ấy buồn lắm đấy, ha ha."},{"hanzi":"不知道你对中国的音乐有没有兴趣？","pinyin":"Bù zhīdào nǐ duì Zhōngguó de yīnyuè yǒu méiyǒu xìngqù?","speaker":"Đoạn văn","vi":"Không biết em có hứng thú với âm nhạc Trung Quốc không?"},{"hanzi":"我送你一张明天下午音乐会的门票。","pinyin":"Wǒ sòng nǐ yì zhāng míngtiān xiàwǔ yīnyuèhuì de ménpiào.","speaker":"Đoạn văn","vi":"Chị tặng em một tấm vé buổi hòa nhạc chiều mai."},{"hanzi":"音乐会七点多结束，你听完了音乐会就来我家吃饭，尝尝我做的中国菜。","pinyin":"Yīnyuèhuì qī diǎn duō jiéshù, nǐ tīngwán le yīnyuèhuì jiù lái wǒ jiā chīfàn, chángchang wǒ zuò de Zhōngguó cài.","speaker":"Đoạn văn","vi":"Buổi hòa nhạc hơn bảy giờ kết thúc, em nghe xong buổi hòa nhạc thì qua nhà chị ăn cơm, nếm thử món ăn Trung Quốc chị nấu."},{"hanzi":"你觉得怎么样？","pinyin":"Nǐ juéde zěnmeyàng?","speaker":"Đoạn văn","vi":"Em thấy thế nào?"}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"我已经告诉了一飞，你的拍照水平比她高，她难过得很，哈哈。\" (Chị đã nói với Nhất Phi rồi, trình độ chụp ảnh của em cao hơn em ấy, em ấy buồn lắm đấy, haha.), nên Vương Nhất Tuyết đánh giá trình độ chụp ảnh của Bạch Gia Nguyệt cao hơn Nhất Phi.","options":["还可以，跟一飞的差不多","比一飞的拍照水平高","没一飞照得那么好看","只有几张照片看起来不错"],"q":"王一雪觉得白家月的拍照水平怎么样？"},{"answerIdx":1,"explanation":"Trong bài có câu \"你听完了音乐会就来我家吃饭，尝尝我做的中国菜。\" (Em nghe xong buổi hòa nhạc thì đến nhà chị ăn cơm, nếm thử món Trung Quốc chị nấu nhé.), nên Vương Nhất Tuyết mời Bạch Gia Nguyệt đến nhà chị ăn cơm và thử món Trung Quốc chị nấu.","options":["去咖啡厅喝咖啡、聊天儿","来自己家吃她做的中国菜","再一起去山上照几张相","给一飞发一封邮件"],"q":"明天听完音乐会以后，王一雪请白家月做什么？"}],"scene":"在咖啡厅里，王一雪给白家月发短信。","sceneVi":"Trong quán cà phê, Vương Nhất Tuyết nhắn tin cho Bạch Gia Nguyệt."}],"hsk3-6":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"家月，咱们该买去上海的票了。你打算怎么去上海？","pinyin":"Jiāyuè, zánmen gāi mǎi qù Shànghǎi de piào le. Nǐ dǎsuàn zěnme qù Shànghǎi?","speaker":"李文","vi":"Gia Nguyệt, chúng ta nên mua vé đi Thượng Hải rồi. Cậu dự định đi Thượng Hải bằng cách nào?"},{"hanzi":"我还没坐过高铁，咱们坐高铁去，怎么样？","pinyin":"Wǒ hái méi zuòguo gāotiě, zánmen zuò gāotiě qù, zěnmeyàng?","speaker":"白家月","vi":"Mình vẫn chưa đi tàu cao tốc bao giờ, chúng ta đi tàu cao tốc nhé, thế nào?"},{"hanzi":"没问题，从北京到上海的高铁很多，非常方便。","pinyin":"Méi wèntí, cóng Běijīng dào Shànghǎi de gāotiě hěn duō, fēicháng fāngbiàn.","speaker":"李文","vi":"Không vấn đề gì, tàu cao tốc từ Bắc Kinh đi Thượng Hải rất nhiều, vô cùng tiện lợi."},{"hanzi":"行！怎么买高铁票？","pinyin":"Xíng! Zěnme mǎi gāotiě piào?","speaker":"白家月","vi":"Được đấy! Mua vé tàu cao tốc như thế nào?"},{"hanzi":"用手机App就能买。给我你的护照，我帮你买。","pinyin":"Yòng shǒujī App jiù néng mǎi. Gěi wǒ nǐ de hùzhào, wǒ bāng nǐ mǎi.","speaker":"李文","vi":"Dùng ứng dụng trên điện thoại là mua được ngay. Đưa hộ chiếu của cậu đây, mình mua giúp cậu."},{"hanzi":"早就听说过高铁，终于可以坐上了。","pinyin":"Zǎo jiù tīngshuōguo gāotiě, zhōngyú kěyǐ zuòshàng le.","speaker":"白家月","vi":"Mình đã nghe nói về tàu cao tốc từ lâu rồi, cuối cùng cũng được đi thử rồi."},{"hanzi":"高铁又快又舒服，你一定会喜欢的。","pinyin":"Gāotiě yòu kuài yòu shūfu, nǐ yídìng huì xǐhuan de.","speaker":"李文","vi":"Tàu cao tốc vừa nhanh vừa thoải mái, cậu nhất định sẽ thích."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, Bạch Gia Nguyệt nói \"我还没坐过高铁，咱们坐高铁去，怎么样？\" (Tôi vẫn chưa từng đi tàu cao tốc, chúng ta đi tàu cao tốc nhé, thấy sao?) và \"早就听说过高铁，终于可以坐上了。\" (Tôi nghe nói về tàu cao tốc từ lâu rồi, cuối cùng cũng được đi rồi.), nên cô ấy muốn đi tàu cao tốc vì chưa từng đi bao giờ và đã nghe nói từ lâu.","options":["因为高铁票比飞机票便宜很多","因为她还没坐过高铁，早就听说过了","因为只有高铁能从北京到上海","因为李文在高铁站工作"],"q":"白家月为什么想坐高铁去上海？"},{"answerIdx":2,"explanation":"Trong bài, Lý Văn nói \"用手机App就能买。给我你的护照，我帮你买。\" (Dùng ứng dụng điện thoại là mua được. Đưa hộ chiếu của bạn cho tôi, tôi mua giúp bạn.), nên Lý Văn sẽ cầm hộ chiếu của Bạch Gia Nguyệt và dùng điện thoại mua vé giúp cô ấy.","options":["他们要去火车站窗口排队买票","白家月用手机自己买两个人的票","李文拿白家月的护照，用手机帮她买票","坐高铁不需要用护照买票"],"q":"关于买高铁票，下面哪句话是对的？"}],"scene":"在咖啡厅里，李文和白家月在聊天儿。","sceneVi":"Trong quán cà phê, Lý Văn và Bạch Gia Nguyệt đang trò chuyện."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"过了前面的路口就到高铁站了。","pinyin":"Guò le qiánmiàn de lùkǒu jiù dào gāotiězhàn le.","speaker":"刘明","vi":"Qua ngã tư phía trước là tới ga tàu cao tốc rồi."},{"hanzi":"我看见了。马上就到了，这条路车很多，您小心点儿。","pinyin":"Wǒ kànjiàn le. Mǎshàng jiù dào le, zhè tiáo lù chē hěn duō, nín xiǎoxīn diǎnr.","speaker":"白家月","vi":"Em nhìn thấy rồi. Sắp tới nơi rồi, con đường này nhiều xe lắm, anh cẩn thận một chút."},{"hanzi":"好，你们还有一个小时，应该不会迟到的。","pinyin":"Hǎo, nǐmen hái yǒu yí ge xiǎoshí, yīnggāi búhuì chídào de.","speaker":"刘明","vi":"Ừ, hai người vẫn còn một tiếng nữa, chắc sẽ không bị muộn đâu."},{"hanzi":"我发现这条路车多，红绿灯也多。","pinyin":"Wǒ fāxiàn zhè tiáo lù chē duō, hónglǜdēng yě duō.","speaker":"白家月","vi":"Em thấy con đường này vừa nhiều xe, lại vừa nhiều đèn giao thông nữa."},{"hanzi":"是啊，这条路我走过一次，后来再也不走了。","pinyin":"Shì a, zhè tiáo lù wǒ zǒuguo yí cì, hòulái zài yě bù zǒu le.","speaker":"刘明","vi":"Đúng vậy, con đường này anh từng đi một lần, sau đó không bao giờ đi nữa."},{"hanzi":"那您今天为什么走了这条路？","pinyin":"Nà nín jīntiān wèishénme zǒu le zhè tiáo lù?","speaker":"白家月","vi":"Vậy sao hôm nay anh lại đi con đường này thế?"},{"hanzi":"我一急就走错了。如果没走错，二十分钟以前就到了。","pinyin":"Wǒ yì jí jiù zǒucuò le. Rúguǒ méi zǒucuò, èrshí fēnzhōng yǐqián jiù dào le.","speaker":"刘明","vi":"Anh vội quá nên đi nhầm đường. Nếu không đi nhầm thì hai mươi phút trước đã tới nơi rồi."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài, Lưu Minh nói \"好，你们还有一个小时，应该不会迟到的。\" (Được rồi, hai bạn vẫn còn một tiếng nữa, chắc sẽ không trễ đâu.), nên họ vẫn còn một tiếng đồng hồ.","options":["二十分钟","半个小时","一个小时","已经迟到了"],"q":"离坐高铁的时间还有多久？"},{"answerIdx":1,"explanation":"Trong bài, Lưu Minh giải thích \"我一急就走错了。如果没走错，二十分钟以前就到了。\" (Tôi vội quá nên đi nhầm đường rồi. Nếu không đi nhầm thì hai mươi phút trước đã tới rồi.), nên lý do hôm nay ông đi vào con đường đó là vì vội nên đi nhầm.","options":["因为他以前没走过这条路","因为他一着急就走错了","因为这条路比别的路近一些","因为白家月让他走这条路的"],"q":"刘明今天为什么走了这条车多、红绿灯也多的路？"}],"scene":"在车上，刘明开车送白家月和李文去高铁站。","sceneVi":"Trên xe, Lưu Minh lái xe đưa Bạch Gia Nguyệt và Lý Văn đến ga tàu cao tốc."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"李文，我的耳机没电了，你有充电宝吗？","pinyin":"Lǐ Wén, wǒ de ěrjī méi diàn le, nǐ yǒu chōngdiànbǎo ma?","speaker":"白家月","vi":"Lý Văn, tai nghe của mình hết pin rồi, cậu có sạc dự phòng không?"},{"hanzi":"有，这些常用的东西我都放在包里了，我给你拿。","pinyin":"Yǒu, zhèxiē chángyòng de dōngxi wǒ dōu fàng zài bāo lǐ le, wǒ gěi nǐ ná.","speaker":"李文","vi":"Có, những đồ hay dùng này mình đều để hết trong túi rồi, để mình lấy cho cậu."},{"hanzi":"前面的人越来越多。","pinyin":"Qiánmiàn de rén yuèláiyuè duō.","speaker":"白家月","vi":"Người phía trước ngày càng đông."},{"hanzi":"对，马上就进高铁站了。咱们一起走，别分开。","pinyin":"Duì, mǎshàng jiù jìn gāotiězhàn le. Zánmen yìqǐ zǒu, bié fēnkāi.","speaker":"李文","vi":"Đúng thế, sắp vào trong ga tàu cao tốc rồi. Chúng ta đi cùng nhau nhé, đừng tách nhau ra."},{"hanzi":"好，你检查一下，高铁票都拿好了吗？","pinyin":"Hǎo, nǐ jiǎnchá yíxià, gāotiě piào dōu náhǎo le ma?","speaker":"白家月","vi":"Ừ, cậu kiểm tra lại xem, vé tàu cao tốc đã cầm kỹ chưa?"},{"hanzi":"不用拿票，刷护照就能检票进站。","pinyin":"Búyòng ná piào, shuā hùzhào jiù néng jiǎnpiào jìn zhàn.","speaker":"李文","vi":"Không cần lấy vé đâu, quẹt hộ chiếu là có thể soát vé vào ga rồi."},{"hanzi":"去哪里检票？","pinyin":"Qù nǎlǐ jiǎnpiào?","speaker":"白家月","vi":"Đi đâu để soát vé vậy?"},{"hanzi":"检票口在二层，我们一会儿坐电梯上去。","pinyin":"Jiǎnpiàokǒu zài èr céng, wǒmen yìhuìr zuò diàntī shàngqù.","speaker":"李文","vi":"Cổng soát vé ở tầng hai, lát nữa chúng ta đi thang máy lên."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, Lý Văn nói \"不用拿票，刷护照就能检票进站。\" (Không cần lấy vé đâu, quét hộ chiếu là có thể soát vé vào ga.), nên họ vào ga soát vé bằng cách quét hộ chiếu.","options":["拿着高铁票检票进站","刷护照就能检票进站","用手机里的照片检票进站","请高铁站的服务员带进去"],"q":"他们怎么检票进高铁站？"},{"answerIdx":2,"explanation":"Trong bài, Lý Văn nói \"检票口在二层，我们一会儿坐电梯上去。\" (Cửa soát vé ở tầng hai, lát nữa chúng ta đi thang máy lên.), nên cửa soát vé ở tầng hai và họ sẽ đi thang máy lên đó.","options":["在一层，走过去就行","在二层，走楼梯上去","在二层，坐电梯上去","在三层，坐电梯上去"],"q":"检票口在哪里？他们打算怎么上去？"}],"scene":"在高铁站，李文和白家月排队安检、检票。","sceneVi":"Ở ga tàu cao tốc, Lý Văn và Bạch Gia Nguyệt xếp hàng kiểm tra an ninh và soát vé."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"这次放假，我去了北京，还去了上海。","pinyin":"Zhè cì fàngjià, wǒ qù le Běijīng, hái qù le Shànghǎi.","speaker":"Đoạn văn","vi":"Kỳ nghỉ lần này, mình đã đi Bắc Kinh, còn đi cả Thượng Hải nữa."},{"hanzi":"我是从北京南站坐高铁去的上海。","pinyin":"Wǒ shì cóng Běijīng Nán Zhàn zuò gāotiě qù de Shànghǎi.","speaker":"Đoạn văn","vi":"Mình đi tàu cao tốc từ Ga Nam Bắc Kinh đến Thượng Hải."},{"hanzi":"我觉得坐在高铁上跟坐在家里的沙发上一样，又安静又舒服。","pinyin":"Wǒ juéde zuò zài gāotiě shang gēn zuò zài jiālǐ de shāfā shang yíyàng, yòu ānjìng yòu shūfu.","speaker":"Đoạn văn","vi":"Mình cảm thấy ngồi trên tàu cao tốc giống như ngồi trên ghế sô-pha ở nhà vậy, vừa yên tĩnh vừa thoải mái."},{"hanzi":"坐累了就站一会儿，饿了就点外卖。","pinyin":"Zuòlèi le jiù zhàn yíhuìr, è le jiù diǎn wàimài.","speaker":"Đoạn văn","vi":"Ngồi mỏi rồi thì đứng một lát, đói thì gọi đồ ăn giao tận nơi."},{"hanzi":"对，你没听错，高铁上可以点外卖，只需要选择好车站和想吃的东西，到站时不用下车，服务员就会给你拿过来。","pinyin":"Duì, nǐ méi tīngcuò, gāotiě shang kěyǐ diǎn wàimài, zhǐ xūyào xuǎnzé hǎo chēzhàn hé xiǎng chī de dōngxi, dào zhàn shí búyòng xiàchē, fúwùyuán jiù huì gěi nǐ ná guòlái.","speaker":"Đoạn văn","vi":"Đúng vậy, cậu không nghe nhầm đâu, trên tàu cao tốc có thể gọi đồ ăn ngoài, chỉ cần chọn sẵn nhà ga và món muốn ăn, khi tàu đến ga không cần xuống xe, nhân viên phục vụ sẽ mang tới cho cậu."},{"hanzi":"现在喜欢坐高铁的人越来越多。","pinyin":"Xiànzài xǐhuan zuò gāotiě de rén yuèláiyuè duō.","speaker":"Đoạn văn","vi":"Hiện nay người thích đi tàu cao tốc ngày càng nhiều."},{"hanzi":"我爸妈来中国旅游的时候，必须带他们也坐一次高铁。","pinyin":"Wǒ bàmā lái Zhōngguó lǚyóu de shíhou, bìxū dài tāmen yě zuò yí cì gāotiě.","speaker":"Đoạn văn","vi":"Khi bố mẹ mình sang Trung Quốc du lịch, nhất định phải đưa họ đi tàu cao tốc một lần."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài có câu \"只需要选择好车站和想吃的东西，到站时不用下车，服务员就会给你拿过来。\" (Chỉ cần chọn sẵn nhà ga và món muốn ăn, khi đến ga không cần xuống tàu, nhân viên phục vụ sẽ mang tới cho bạn.), nên khi đến ga không cần xuống tàu mà nhân viên sẽ mang đồ ăn tới.","options":["自己下车去车站里面拿","叫司机停车后去买过来","不用下车，到站时服务员会拿过来","上车以前在高铁站门口拿好"],"q":"在高铁上点外卖以后，怎么拿到吃的东西？"},{"answerIdx":0,"explanation":"Trong bài có câu \"我爸妈来中国旅游的时候，必须带他们也坐一次高铁。\" (Khi bố mẹ tôi sang Trung Quốc du lịch, nhất định phải đưa họ đi tàu cao tốc một lần.), nên khi bố mẹ sang Trung Quốc du lịch, cô ấy nhất định sẽ đưa họ đi tàu cao tốc một lần.","options":["坐一次高铁","去北京南站吃外卖","在上海买新沙发","从上海坐飞机回北京"],"q":"白家月的爸妈来中国旅游的时候，她一定要带他们做什么？"}],"scene":"在家里，白家月给安妮打电话介绍自己的旅行。","sceneVi":"Ở nhà, Bạch Gia Nguyệt gọi điện thoại cho Annie kể về chuyến du lịch của mình."}],"hsk3-7":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"这辆自行车是小雪八岁的时候买的，看起来有点儿旧了。","pinyin":"Zhè liàng zìxíngchē shì Xiǎoxuě bā suì de shíhou mǎi de, kàn qǐlái yǒudiǎnr jiù le.","speaker":"王一雪","vi":"Chiếc xe đạp này là mua hồi Tiểu Tuyết tám tuổi, trông hơi cũ rồi."},{"hanzi":"是啊，她现在长高了，这辆车已经太矮了。","pinyin":"Shì a, tā xiànzài zhǎng gāo le, zhè liàng chē yǐjīng tài ǎi le.","speaker":"刘明","vi":"Đúng vậy, bây giờ con bé cao lên rồi, chiếc xe này đã quá thấp rồi."},{"hanzi":"商场里开了一家自行车店，咱们给她买辆新的吧。","pinyin":"Shāngchǎng lǐ kāi le yì jiā zìxíngchē diàn, zánmen gěi tā mǎi liàng xīn de ba.","speaker":"王一雪","vi":"Trong trung tâm thương mại mới mở một cửa hàng xe đạp, chúng ta mua cho con bé một chiếc mới đi."},{"hanzi":"好，咱们带小雪一起去，让她试一下。","pinyin":"Hǎo, zánmen dài Xiǎoxuě yìqǐ qù, ràng tā shì yíxià.","speaker":"刘明","vi":"Được, chúng ta dẫn Tiểu Tuyết cùng đi, để con bé thử một chút."},{"hanzi":"那今天就去吧！我也想再看看衣服。咱们怎么去？","pinyin":"Nà jīntiān jiù qù ba! Wǒ yě xiǎng zài kànkan yīfu. Zánmen zěnme qù?","speaker":"王一雪","vi":"Vậy hôm nay đi luôn đi! Em cũng muốn xem thêm quần áo nữa. Chúng ta đi bằng gì?"},{"hanzi":"商场不远，咱们可以走着去。","pinyin":"Shāngchǎng bù yuǎn, zánmen kěyǐ zǒuzhe qù.","speaker":"刘明","vi":"Trung tâm thương mại không xa, chúng ta có thể đi bộ tới đó."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài Vương Nhất Tuyết nói \"这辆自行车是小雪八岁的时候买的，看起来有点儿旧了\" (Chiếc xe đạp này mua lúc Tiểu Tuyết 8 tuổi, trông hơi cũ rồi) và Lưu Minh nói \"她现在长高了，这辆车已经太矮了\" (Con bé giờ cao lên rồi, chiếc xe này đã quá thấp rồi), nên họ muốn mua xe mới vì xe cũ hơi cũ và quá thấp so với Tiểu Tuyết.","options":["小雪的自行车坏了，不能骑了","旧车有点儿旧，而且对长高了的小雪来说太矮了","小雪八岁了，以前没有自行车","商场里的自行车今天正在打折"],"q":"王一雪和刘明为什么想给小雪买一辆新自行车？"},{"answerIdx":2,"explanation":"Trong bài Lưu Minh nói \"商场不远，咱们可以走着去\" (Trung tâm thương mại không xa, chúng ta có thể đi bộ đến đó), nên họ dự định đi bộ.","options":["骑自行车去","坐公共汽车去","走着去","坐出租车去"],"q":"他们打算怎么去商场？"}],"scene":"在家里，王一雪和刘明商量去买东西。","sceneVi":"Ở nhà, Vương Nhất Tuyết và Lưu Minh bàn bạc đi mua đồ."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"你看我穿这条黄色的短裤好看吗？","pinyin":"Nǐ kàn wǒ chuān zhè tiáo huángsè de duǎnkù hǎokàn ma?","speaker":"王一雪","vi":"Anh xem em mặc chiếc quần đùi màu vàng này có đẹp không?"},{"hanzi":"大小合适，但我觉得那条裙子比短裤更好看。","pinyin":"Dàxiǎo héshì, dàn wǒ juéde nà tiáo qúnzi bǐ duǎnkù gèng hǎokàn.","speaker":"刘明","vi":"Kích cỡ vừa vặn, nhưng anh thấy chiếc váy kia đẹp hơn quần đùi."},{"hanzi":"裙子比短裤贵一点儿。","pinyin":"Qúnzi bǐ duǎnkù guì yìdiǎnr.","speaker":"王一雪","vi":"Váy đắt hơn quần đùi một chút."},{"hanzi":"贵多少？","pinyin":"Guì duōshao?","speaker":"刘明","vi":"Đắt hơn bao nhiêu?"},{"hanzi":"裙子480，短裤400。","pinyin":"Qúnzi sìbǎi bāshí, duǎnkù sìbǎi.","speaker":"王一雪","vi":"Váy 480, quần đùi 400."},{"hanzi":"裙子不比短裤贵多少，还是买裙子吧，你穿裙子更好看。","pinyin":"Qúnzi bù bǐ duǎnkù guì duōshao, háishi mǎi qúnzi ba, nǐ chuān qúnzi gèng hǎokàn.","speaker":"刘明","vi":"Váy không đắt hơn quần đùi bao nhiêu đâu, hay là mua váy đi, em mặc váy đẹp hơn."},{"hanzi":"我多看看再决定。你看，那边有买二送一！","pinyin":"Wǒ duō kànkan zài juédìng. Nǐ kàn, nàbiān yǒu mǎi èr sòng yī!","speaker":"王一雪","vi":"Em xem thêm đã rồi quyết định. Anh nhìn kìa, bên kia có chương trình mua 2 tặng 1!"}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài Vương Nhất Tuyết nói \"裙子480，短裤400\" (Váy 480 tệ, quần đùi 400 tệ), nên chiếc váy đắt hơn chiếc quần đùi 80 tệ.","options":["裙子比短裤贵八十块钱","短裤比裙子贵八十块钱","裙子和短裤一样贵","裙子比短裤便宜得多"],"q":"关于这条裙子和短裤的价格，下面哪一项是对的？"},{"answerIdx":2,"explanation":"Trong bài Vương Nhất Tuyết nói \"我多看看再决定。你看，那边有买二送一！\" (Em xem thêm nhiều chút rồi mới quyết định. Anh xem, đằng kia có mua 2 tặng 1 kìa!), nên cô ấy dự định xem thêm rồi mới quyết định.","options":["马上买那条黄色的短裤","听刘明的话，只买那条裙子","再多看看，然后才决定买什么","不买了，直接回家"],"q":"最后王一雪打算怎么做？"}],"scene":"在商场，刘明和王一雪买完自行车，又来挑选衣服。","sceneVi":"Ở trung tâm thương mại, Lưu Minh và Vương Nhất Tuyết mua xong xe đạp, lại qua chọn quần áo."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"西瓜又大又新鲜，不甜不要钱！","pinyin":"Xīguā yòu dà yòu xīnxiān, bù tián bú yào qián!","speaker":"店员","vi":"Dưa hấu vừa to vừa tươi, không ngọt không lấy tiền!"},{"hanzi":"西瓜看起来不错，怎么卖？","pinyin":"Xīguā kàn qǐlái búcuò, zěnme mài?","speaker":"王一雪","vi":"Dưa hấu trông ngon đấy, bán thế nào vậy?"},{"hanzi":"五块钱一公斤。来，您先尝尝这块冰西瓜，甜极了！","pinyin":"Wǔ kuài qián yì gōngjīn. Lái, nín xiān chángchang zhè kuài bīng xīguā, tián jíle!","speaker":"店员","vi":"Năm tệ một ki-lô-gam. Nào, chị nếm thử miếng dưa hấu ướp lạnh này trước đi, ngọt cực kỳ!"},{"hanzi":"是挺甜的！帮我选个大点儿的，再来两斤香蕉。","pinyin":"Shì tǐng tián de! Bāng wǒ xuǎn ge dàdiǎnr de, zài lái liǎng jīn xiāngjiāo.","speaker":"王一雪","vi":"Ngọt thật đấy! Chọn giúp tôi một quả to một chút, lấy thêm hai cân chuối nữa."},{"hanzi":"一共五十八块五毛。","pinyin":"Yígòng wǔshíbā kuài wǔ máo.","speaker":"店员","vi":"Tổng cộng năm mươi tám tệ năm hào."},{"hanzi":"我买了这么多，便宜点儿吧。","pinyin":"Wǒ mǎi le zhème duō, piányi diǎnr ba.","speaker":"王一雪","vi":"Tôi mua nhiều thế này, bớt chút đi."},{"hanzi":"您给我五十五吧，不能再便宜了。","pinyin":"Nín gěi wǒ wǔshíwǔ ba, bù néng zài piányi le.","speaker":"店员","vi":"Chị đưa tôi năm mươi lăm tệ nhé, không thể rẻ hơn nữa đâu."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài Vương Nhất Tuyết nói với nhân viên bán hàng \"帮我选个大点儿的，再来两斤香蕉\" (Chọn giúp tôi một quả dưa hấu to hơn chút, lấy thêm hai cân chuối nữa), nên cô ấy đã mua một quả dưa hấu và hai cân (jin) chuối.","options":["一个大西瓜和两公斤苹果","一个西瓜和两斤香蕉","一块冰西瓜和五斤香蕉","两斤西瓜和一斤香蕉"],"q":"王一雪在商店里买了什么水果？"},{"answerIdx":2,"explanation":"Trong bài, tổng tiền ban đầu là 58,5 tệ, sau khi Vương Nhất Tuyết mặc cả thì nhân viên nói \"您给我五十五吧，不能再便宜了\" (Chị đưa tôi 55 tệ nhé, không thể rẻ hơn nữa đâu), nên cô ấy phải trả 55 tệ.","options":["五十块钱","五十八块五毛","五十五块钱","五十三块五毛"],"q":"便宜以后，王一雪需要付多少钱？"}],"scene":"在商店，王一雪在买东西。","sceneVi":"Ở cửa hàng, Vương Nhất Tuyết đang mua đồ."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"这几天我们在新家坐着看电视的时候，又发现了新问题。","pinyin":"Zhè jǐ tiān wǒmen zài xīn jiā zuòzhe kàn diànshì de shíhou, yòu fāxiàn le xīn wèntí.","speaker":"Đoạn văn","vi":"Mấy ngày nay khi chúng tôi ngồi xem ti vi ở nhà mới, lại phát hiện ra vấn đề mới."},{"hanzi":"房子大了，电视看起来就有点儿小。","pinyin":"Fángzi dà le, diànshì kàn qǐlái jiù yǒudiǎnr xiǎo.","speaker":"Đoạn văn","vi":"Nhà rộng ra rồi, ti vi trông có vẻ hơi nhỏ."},{"hanzi":"这个电视是我们结婚时买的，是时候换个新电视了。","pinyin":"Zhège diànshì shì wǒmen jiéhūn shí mǎi de, shì shíhou huàn ge xīn diànshì le.","speaker":"Đoạn văn","vi":"Chiếc ti vi này là mua hồi chúng tôi kết hôn, đã đến lúc đổi một chiếc ti vi mới rồi."},{"hanzi":"今天我一直在网上选电视，没想到，现在的电视不但便宜，而且用着非常方便，有的电视叫它一声就能开机。","pinyin":"Jīntiān wǒ yìzhí zài wǎngshang xuǎn diànshì, méi xiǎngdào, xiànzài de diànshì búdàn piányi, érqiě yòngzhe fēicháng fāngbiàn, yǒude diànshì jiào tā yì shēng jiù néng kāijī.","speaker":"Đoạn văn","vi":"Hôm nay tôi cứ chọn ti vi trên mạng suốt, không ngờ ti vi bây giờ không những rẻ, mà dùng còn vô cùng tiện lợi, có chiếc ti vi chỉ cần gọi một tiếng là có thể bật máy."},{"hanzi":"我看了好几个，都很满意，晚上让一雪来决定吧。","pinyin":"Wǒ kàn le hǎo jǐ gè, dōu hěn mǎnyì, wǎnshang ràng Yīxuě lái juédìng ba.","speaker":"Đoạn văn","vi":"Tôi đã xem qua mấy chiếc rồi, đều rất hài lòng, tối nay để Nhất Tuyết quyết định vậy."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"房子大了，电视看起来就有点儿小。这个电视是我们结婚时买的，是时候换个新电视了\" (Nhà lớn rồi, ti vi nhìn có vẻ hơi nhỏ. Chiếc ti vi này mua lúc chúng tôi kết hôn, đã đến lúc đổi một chiếc ti vi mới rồi), nên nguyên nhân là nhà mới rộng khiến ti vi cũ trông hơi nhỏ.","options":["旧电视坏了，打不开了","新家房子大了，旧电视显得有点儿小","王一雪不喜欢旧电视的颜色","网上的新电视比旧电视贵"],"q":"刘明为什么想换一个新电视？"},{"answerIdx":0,"explanation":"Trong bài có câu \"没想到，现在的电视不但便宜，而且用着非常方便，有的电视叫它一声就能开机\" (Không ngờ ti vi bây giờ không những rẻ mà dùng còn rất tiện lợi, có chiếc chỉ cần gọi một tiếng là có thể bật máy), nên Lưu Minh thấy ti vi hiện nay vừa rẻ vừa dùng rất tiện.","options":["现在的电视不但便宜，而且用着很方便","网上的电视太贵了，不值得买","网上的电视都很小，他不太满意","现在的电视都必须用遥控器开机"],"q":"刘明在网上选电视时有什么发现？"}],"scene":"在家里，刘明在看电视。","sceneVi":"Ở nhà, Lưu Minh đang xem ti vi."}],"hsk3-8":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"天中，最近常看见你来体育馆。","pinyin":"Tiānzhōng, zuìjìn cháng kànjiàn nǐ lái tǐyùguǎn.","speaker":"李文","vi":"Thiên Trung, dạo này thường thấy cậu đến nhà thi đấu."},{"hanzi":"我每天下午都来跑一个小时步。","pinyin":"Wǒ měitiān xiàwǔ dōu lái pǎo yí gè xiǎoshí bù.","speaker":"陈天中","vi":"Chiều nào mình cũng đến chạy bộ một tiếng."},{"hanzi":"你的运动习惯真不错。","pinyin":"Nǐ de yùndòng xíguàn zhēn búcuò.","speaker":"李文","vi":"Thói quen vận động của cậu thật tốt."},{"hanzi":"因为我今年胖了十多斤，不能再胖下去了，有点儿不健康。","pinyin":"Yīnwèi wǒ jīnnián pàng le shí duō jīn, bù néng zài pàng xiàqù le, yǒudiǎnr bú jiànkāng.","speaker":"陈天中","vi":"Vì năm nay mình béo lên hơn mười cân rồi, không thể cứ béo tiếp được nữa, hơi không khỏe mạnh."},{"hanzi":"我下课以后常去打羽毛球，你也来玩吧。","pinyin":"Wǒ xiàkè yǐhòu cháng qù dǎ yǔmáoqiú, nǐ yě lái wán ba.","speaker":"李文","vi":"Sau khi tan học mình thường đi đánh cầu lông, cậu cũng đến chơi đi."},{"hanzi":"我知道，但是你们的水平太高了，我打得不怎么样。","pinyin":"Wǒ zhīdào, dànshì nǐmen de shuǐpíng tài gāo le, wǒ dǎ de bù zěnmeyàng.","speaker":"陈天中","vi":"Mình biết, nhưng trình độ của các cậu cao quá, mình đánh chẳng ra sao cả."},{"hanzi":"没关系，我可以教你。","pinyin":"Méi guānxi, wǒ kěyǐ jiāo nǐ.","speaker":"李文","vi":"Không sao đâu, mình có thể dạy cậu."}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài Trần Thiên Trung nói \"因为我今年胖了十多斤，不能再胖下去了，有点儿不健康\" (Vì năm nay mình béo lên hơn chục cân rồi, không thể béo thêm nữa, hơi không khỏe mạnh), nên cậu ấy chạy bộ mỗi chiều để giữ sức khỏe.","options":["因为他今年胖了十多斤，想保持健康","因为他每天都要练习羽毛球比赛","因为体育馆离他的家很近","因为李文每天下午都约他来跑步"],"q":"陈天中为什么每天下午都来体育馆跑步？"},{"answerIdx":2,"explanation":"Trong bài Lý Văn rủ \"我下课以后常去打羽毛球，你也来玩吧\" (Sau giờ học mình thường đi đánh cầu lông, cậu cũng đến chơi nhé) và nói thêm \"没关系，我可以教你\" (Không sao đâu, mình có thể dạy cậu), nên Lý Văn định dạy đánh cầu lông.","options":["跑步","游泳","打羽毛球","打网球"],"q":"李文打算教陈天中什么运动？"}],"scene":"在学校的体育馆，李文遇到了陈天中。","sceneVi":"Ở nhà thi đấu của trường, Lý Văn gặp Trần Thiên Trung."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"你怎么了？看上去有点儿不舒服。","pinyin":"Nǐ zěnme le? Kàn shàngqù yǒudiǎnr bù shūfu.","speaker":"安妮","vi":"Cậu làm sao thế? Trông có vẻ hơi khó chịu."},{"hanzi":"昨天游完泳以后，耳朵一直有点儿疼。","pinyin":"Zuótiān yóuwán yǒng yǐhòu, ěrduo yìzhí yǒudiǎnr téng.","speaker":"陈天中","vi":"Hôm qua sau khi bơi xong, tai cứ hơi đau suốt."},{"hanzi":"是不是感冒了？发烧吗？","pinyin":"Shì bú shì gǎnmào le? Fāshāo ma?","speaker":"安妮","vi":"Có phải bị cảm rồi không? Có sốt không?"},{"hanzi":"好像发低烧了。","pinyin":"Hǎoxiàng fā dīshāo le.","speaker":"陈天中","vi":"Hình như bị sốt nhẹ rồi."},{"hanzi":"我送你去医院，让医生检查一下吧。","pinyin":"Wǒ sòng nǐ qù yīyuàn, ràng yīshēng jiǎnchá yíxià ba.","speaker":"安妮","vi":"Mình đưa cậu đến bệnh viện, để bác sĩ kiểm tra một chút nhé."},{"hanzi":"我先回去睡一觉，可能休息休息就好了。","pinyin":"Wǒ xiān huíqù shuì yí jiào, kěnéng xiūxi xiūxi jiù hǎo le.","speaker":"陈天中","vi":"Mình về ngủ một giấc trước đã, có lẽ nghỉ ngơi một chút là khỏi thôi."},{"hanzi":"好吧，如果下午还发烧，就一定要去看医生。","pinyin":"Hǎo ba, rúguǒ xiàwǔ hái fāshāo, jiù yídìng yào qù kàn yīshēng.","speaker":"安妮","vi":"Được thôi, nếu buổi chiều vẫn còn sốt, thì nhất định phải đi khám bác sĩ đấy."},{"hanzi":"谢谢关心，我会注意的。","pinyin":"Xièxie guānxīn, wǒ huì zhùyì de.","speaker":"陈天中","vi":"Cảm ơn đã quan tâm, mình sẽ chú ý."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài Trần Thiên Trung nói \"昨天游完泳以后，耳朵一直有点儿疼\" (Hôm qua sau khi bơi xong, tai cứ hơi đau) và \"好像发低烧了\" (Hình như hơi sốt nhẹ rồi).","options":["昨天游完泳后腿疼，还发高烧","耳朵一直有点儿疼，而且好像发低烧了","肚子疼得厉害，不能去上课","今天早上跑步以后头疼"],"q":"陈天中哪里不舒服？"},{"answerIdx":1,"explanation":"Trong bài Trần Thiên Trung nói với Anny \"我先回去睡一觉，可能休息休息就好了\" (Mình về ngủ một giấc trước đã, có thể nghỉ ngơi một chút sẽ khỏi), nên cậu ấy dự định về ngủ một giấc, nghỉ ngơi trước.","options":["立刻让安妮送他去医院","先回去睡一觉，休息一下","继续留在教室里上课","去体育馆再游一次泳"],"q":"陈天中现在打算先做什么？"}],"scene":"在教室，安妮问候陈天中。","sceneVi":"Trong lớp học, An Ni hỏi thăm Trần Thiên Trung."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"你怎么突然住院了？大家都很担心你。","pinyin":"Nǐ zěnme tūrán zhùyuàn le? Dàjiā dōu hěn dānxīn nǐ.","speaker":"安妮","vi":"Sao cậu đột nhiên phải nhập viện thế? Mọi người đều rất lo lắng cho cậu."},{"hanzi":"我的腿疼了几个星期了，医生说需要住院做检查。","pinyin":"Wǒ de tuǐ téng le jǐ gè xīngqī le, yīshēng shuō xūyào zhùyuàn zuò jiǎnchá.","speaker":"陈天中","vi":"Chân mình đau mấy tuần rồi, bác sĩ nói cần phải nhập viện để làm kiểm tra."},{"hanzi":"你看起来一点儿也不像病人。","pinyin":"Nǐ kàn qǐlái yìdiǎnr yě bú xiàng bìngrén.","speaker":"安妮","vi":"Cậu trông chẳng giống người bệnh chút nào."},{"hanzi":"是啊，我很少生病。我上次来医院已经过去差不多两年了。","pinyin":"Shì a, wǒ hěn shǎo shēngbìng. Wǒ shàngcì lái yīyuàn yǐjīng guòqù chàbuduō liǎng nián le.","speaker":"陈天中","vi":"Đúng vậy, mình rất ít khi ốm. Lần trước mình đến bệnh viện đã trôi qua gần hai năm rồi."},{"hanzi":"你每天跑步，有时候还去游泳，是不是运动太多了？","pinyin":"Nǐ měitiān pǎobù, yǒu shíhou hái qù yóuyǒng, shì bú shì yùndòng tài duō le?","speaker":"安妮","vi":"Cậu ngày nào cũng chạy bộ, có lúc còn đi bơi, có phải vận động nhiều quá rồi không?"},{"hanzi":"医生也这么说，但是还得做完检查才能知道。","pinyin":"Yīshēng yě zhème shuō, dànshì hái děi zuòwán jiǎnchá cái néng zhīdào.","speaker":"陈天中","vi":"Bác sĩ cũng nói vậy, nhưng vẫn phải làm xong kiểm tra mới biết được."},{"hanzi":"别担心！听医生的话，好好休息，你的腿一定能好。","pinyin":"Bié dānxīn! Tīng yīshēng de huà, hǎohāo xiūxi, nǐ de tuǐ yídìng néng hǎo.","speaker":"安妮","vi":"Đừng lo! Nghe lời bác sĩ, nghỉ ngơi cho tốt, chân của cậu nhất định sẽ khỏi."},{"hanzi":"谢谢。有人来看我，我就开心多了。","pinyin":"Xièxie. Yǒu rén lái kàn wǒ, wǒ jiù kāixīn duō le.","speaker":"陈天中","vi":"Cảm ơn nhé. Có người đến thăm mình, mình vui hơn nhiều rồi."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài Trần Thiên Trung giải thích \"我的腿疼了几个星期了，医生说需要住院做检查\" (Chân mình đau mấy tuần rồi, bác sĩ nói cần nhập viện để kiểm tra).","options":["因为他的耳朵发炎，一直在发烧","因为他的腿疼了几个星期，需要住院做检查","因为他在医院工作，顺便做检查","因为医生发现他跑步时摔伤了"],"q":"陈天中为什么需要住院？"},{"answerIdx":2,"explanation":"Trong bài Trần Thiên Trung nói \"我上次来医院已经过去差不多两年了\" (Lần trước mình đến bệnh viện đã qua gần hai năm rồi), nên lần gần nhất là khoảng hai năm trước.","options":["几个星期以前","上个月","差不多两年以前","他从来没有来过医院"],"q":"陈天中上一次来医院是什么时候？"}],"scene":"在医院病房，安妮探望陈天中。","sceneVi":"Ở phòng bệnh viện, An Ni đến thăm Trần Thiên Trung."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"今天我出院了。","pinyin":"Jīntiān wǒ chūyuàn le.","speaker":"Đoạn văn","vi":"Hôm nay tôi đã xuất viện rồi."},{"hanzi":"出院前，医生给我开了几种药，而且告诉了我吃药的方法。","pinyin":"Chūyuàn qián, yīshēng gěi wǒ kāi le jǐ zhǒng yào, érqiě gàosu le wǒ chīyào de fāngfǎ.","speaker":"Đoạn văn","vi":"Trước khi xuất viện, bác sĩ đã kê cho tôi mấy loại thuốc, đồng thời nói cho tôi biết cách uống thuốc."},{"hanzi":"有一种药需要每天睡前吃一次，其他几种每天吃三次，饭后吃。","pinyin":"Yǒu yì zhǒng yào xūyào měitiān shuìqián chī yí cì, qítā jǐ zhǒng měitiān chī sān cì, fànhòu chī.","speaker":"Đoạn văn","vi":"Có một loại thuốc cần uống mỗi ngày một lần trước khi đi ngủ, mấy loại khác mỗi ngày uống ba lần, uống sau bữa ăn."},{"hanzi":"除了吃药，医生还说最重要的是多休息。","pinyin":"Chúle chīyào, yīshēng hái shuō zuì zhòngyào de shì duō xiūxi.","speaker":"Đoạn văn","vi":"Ngoài uống thuốc ra, bác sĩ còn nói điều quan trọng nhất là nghỉ ngơi nhiều."},{"hanzi":"我都记在心里了，回家以后一定会多注意。","pinyin":"Wǒ dōu jì zài xīnli le, huíjiā yǐhòu yídìng huì duō zhùyì.","speaker":"Đoạn văn","vi":"Tôi đều ghi nhớ trong lòng rồi, sau khi về nhà nhất định sẽ chú ý nhiều hơn."},{"hanzi":"希望我的腿能快一点儿好。","pinyin":"Xīwàng wǒ de tuǐ néng kuài yìdiǎnr hǎo.","speaker":"Đoạn văn","vi":"Hy vọng chân của tôi có thể nhanh chóng khỏe lại một chút."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"有一种药需要每天睡前吃一次，其他几种每天吃三次，饭后吃\" (Có một loại thuốc cần uống mỗi ngày một lần trước khi đi ngủ, mấy loại khác uống mỗi ngày ba lần sau bữa ăn).","options":["所有药都必须每天饭前吃三次","一种药每天睡前吃一次，其他的每天饭后吃三次","所有药都是每天睡觉以前吃一次","只有腿疼的时候才需要吃药"],"q":"按照医生的要求，陈天中应该怎么吃药？"},{"answerIdx":2,"explanation":"Trong bài có câu \"除了吃药，医生还说最重要的是多休息\" (Ngoài uống thuốc ra, bác sĩ còn nói điều quan trọng nhất là nghỉ ngơi nhiều).","options":["每天坚持跑步锻炼","按时去医院做检查","多休息","多喝水，少吃饭"],"q":"除了吃药以外，医生认为最重要的是什么？"}],"scene":"在家里，陈天中吃药、休息。","sceneVi":"Ở nhà, Trần Thiên Trung uống thuốc, nghỉ ngơi."}],"hsk3-9":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"家月，对不起，我昨天忘了还你校园卡了。","pinyin":"Jiāyuè, duìbuqǐ, wǒ zuótiān wàngle huán nǐ xiàoyuán kǎ le.","speaker":"李文","vi":"Gia Nguyệt, xin lỗi nhé, hôm qua mình quên trả thẻ trường cho cậu rồi."},{"hanzi":"没关系。你怎么这么快就过来了？","pinyin":"Méi guānxi. Nǐ zěnme zhème kuài jiù guòlái le?","speaker":"白家月","vi":"Không sao đâu. Sao cậu qua đây nhanh thế?"},{"hanzi":"我正在球场打球呢，接了你的电话就跑过来了。","pinyin":"Wǒ zhèngzài qiúchǎng dǎqiú ne, jiēle nǐ de diànhuà jiù pǎo guòlái le.","speaker":"李文","vi":"Mình đang chơi bóng ở sân bóng, nhận được điện thoại của cậu là chạy qua ngay."},{"hanzi":"听说为了准备运动会，你们几个男生每天都练球。","pinyin":"Tīngshuō wèile zhǔnbèi yùndònghuì, nǐmen jǐ gè nánshēng měitiān dōu liàn qiú.","speaker":"白家月","vi":"Nghe nói để chuẩn bị cho hội thao, mấy bạn nam các cậu ngày nào cũng tập bóng."},{"hanzi":"是啊！你打算参加运动会吗？","pinyin":"Shì a! Nǐ dǎsuàn cānjiā yùndònghuì ma?","speaker":"李文","vi":"Đúng vậy! Cậu có định tham gia hội thao không?"},{"hanzi":"我想参加网球比赛，最近一直在练习。","pinyin":"Wǒ xiǎng cānjiā wǎngqiú bǐsài, zuìjìn yìzhí zài liànxí.","speaker":"白家月","vi":"Mình muốn tham gia thi đấu quần vợt, dạo này mình vẫn luôn tập luyện."},{"hanzi":"好，到时候我去看你的比赛。","pinyin":"Hǎo, dào shíhou wǒ qù kàn nǐ de bǐsài.","speaker":"李文","vi":"Được, đến lúc đó mình sẽ đi xem trận đấu của cậu."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài Lý Văn xin lỗi Bạch Gia Nguyệt \"家月，对不起，我昨天忘了还你校园卡了\" (Gia Nguyệt, xin lỗi, hôm qua mình quên trả thẻ trường cho cậu rồi).","options":["忘了去球场练球","忘了给白家月打电话","忘了还白家月校园卡","忘了报名参加运动会"],"q":"李文昨天忘了做什么事？"},{"answerIdx":0,"explanation":"Trong bài Bạch Gia Nguyệt nói \"我想参加网球比赛，最近一直在练习\" (Mình muốn tham gia thi đấu quần vợt, dạo này vẫn luôn luyện tập).","options":["网球比赛","羽毛球比赛","足球比赛","跑步比赛"],"q":"在运动会上，白家月想参加什么比赛？"}],"scene":"在图书馆门口，李文向白家月跑过去。","sceneVi":"Ở cổng thư viện, Lý Văn chạy về phía Bạch Gia Nguyệt."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"家月，你跟我们一起打羽毛球吧？","pinyin":"Jiāyuè, nǐ gēn wǒmen yìqǐ dǎ yǔmáoqiú ba?","speaker":"李文","vi":"Gia Nguyệt, cậu chơi cầu lông cùng tụi mình đi?"},{"hanzi":"我好多年没打羽毛球了，几乎忘了怎么打了。","pinyin":"Wǒ hǎoduō nián méi dǎ yǔmáoqiú le, jīhū wàngle zěnme dǎ le.","speaker":"白家月","vi":"Mình nhiều năm không chơi cầu lông rồi, gần như quên cách đánh rồi."},{"hanzi":"不是比赛，打不好没关系。","pinyin":"Bú shì bǐsài, dǎ bu hǎo méi guānxi.","speaker":"李文","vi":"Không phải thi đấu đâu, đánh không tốt cũng không sao."},{"hanzi":"这么多同学一起打，如果总是接不住球，就太不好意思了。","pinyin":"Zhème duō tóngxué yìqǐ dǎ, rúguǒ zǒngshì jiē bu zhù qiú, jiù tài bù hǎoyìsi le.","speaker":"白家月","vi":"Nhiều bạn học cùng chơi như vậy, nếu cứ không đỡ được cầu thì ngại lắm."},{"hanzi":"你想得太多了！大家打球只是为了锻炼身体。","pinyin":"Nǐ xiǎng de tài duō le! Dàjiā dǎqiú zhǐshì wèile duànliàn shēntǐ.","speaker":"李文","vi":"Cậu nghĩ nhiều quá rồi! Mọi người chơi cầu chỉ là để rèn luyện sức khỏe thôi."},{"hanzi":"我先自己练练吧，下周再跟你们一起打。","pinyin":"Wǒ xiān zìjǐ liànlian ba, xià zhōu zài gēn nǐmen yìqǐ dǎ.","speaker":"白家月","vi":"Để mình tự tập trước đã, tuần sau lại chơi cùng các cậu."},{"hanzi":"我在教天中打羽毛球，你可以过来跟我们一起练。","pinyin":"Wǒ zài jiāo Tiānzhōng dǎ yǔmáoqiú, nǐ kěyǐ guòlái gēn wǒmen yìqǐ liàn.","speaker":"李文","vi":"Mình đang dạy Thiên Trung chơi cầu lông, cậu có thể qua đây tập cùng tụi mình."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài Bạch Gia Nguyệt nói \"我好多年没打羽毛球了，几乎忘了怎么打了\" (Mình nhiều năm không đánh cầu lông rồi, gần như quên cách đánh) và \"这么多同学一起打，如果总是接不住球，就太不好意思了\" (Nhiều bạn học cùng đánh như vậy, nếu cứ không đỡ được cầu thì ngại lắm).","options":["因为她最近没有时间锻炼身体","因为她好多年没打了，怕总是接不住球会不好意思","因为她觉得跟陈天中一起练太累了","因为她马上要参加羽毛球比赛，很紧张"],"q":"白家月一开始为什么不想跟大家一起打羽毛球？"},{"answerIdx":2,"explanation":"Trong bài Lý Văn nói \"大家打球只是为了锻炼身体\" (Mọi người chơi cầu chỉ là để rèn luyện sức khỏe thôi).","options":["为了准备下周的比赛","为了认识更多新同学","为了锻炼身体","为了教陈天中打球"],"q":"李文认为大家一起打球是为了什么？"}],"scene":"在校园里，李文和白家月在聊天儿。","sceneVi":"Trong khuôn viên trường, Lý Văn và Bạch Gia Nguyệt đang trò chuyện."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"足球比赛已经开始了，快过来看吧！","pinyin":"Zúqiú bǐsài yǐjīng kāishǐ le, kuài guòlái kàn ba!","speaker":"陈天中","vi":"Trận đấu bóng đá bắt đầu rồi, mau qua đây xem đi!"},{"hanzi":"你们先看，冰箱里有啤酒和饮料，我去拿一下。","pinyin":"Nǐmen xiān kàn, bīngxiāng lǐ yǒu píjiǔ hé yǐnliào, wǒ qù ná yíxià.","speaker":"李文","vi":"Các cậu xem trước đi, trong tủ lạnh có bia và đồ uống, mình đi lấy một chút."},{"hanzi":"今天怎么回事？总是踢不进去！","pinyin":"Jīntiān zěnme huí shì? Zǒngshì tī bu jìnqù!","speaker":"白家月","vi":"Hôm nay làm sao thế nhỉ? Cứ sút mãi không vào!"},{"hanzi":"几个老球员生病了，新球员第一次参加这么重要的比赛，太紧张了。","pinyin":"Jǐ gè lǎo qiúyuán shēngbìng le, xīn qiúyuán dì-yī cì cānjiā zhème zhòngyào de bǐsài, tài jǐnzhāng le.","speaker":"陈天中","vi":"Mấy cầu thủ cũ bị ốm rồi, các cầu thủ mới lần đầu tham gia trận đấu quan trọng như thế nên căng thẳng quá."},{"hanzi":"是啊，主要的球员没参加比赛，所以大家也都受到影响了。","pinyin":"Shì a, zhǔyào de qiúyuán méi cānjiā bǐsài, suǒyǐ dàjiā yě dōu shòudào yǐngxiǎng le.","speaker":"李文","vi":"Đúng vậy, những cầu thủ chủ chốt không tham gia thi đấu nên mọi người cũng đều bị ảnh hưởng."},{"hanzi":"越看越着急。我不看了，你们告诉我得分吧。","pinyin":"Yuè kàn yuè zháojí. Wǒ bú kàn le, nǐmen gàosu wǒ défēn ba.","speaker":"白家月","vi":"Càng xem càng sốt ruột. Mình không xem nữa đâu, các cậu báo tỷ số cho mình nhé."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài Trần Thiên Trung nói \"几个老球员生病了，新球员第一次参加这么重要的比赛，太紧张了\" (Mấy cầu thủ kỳ cựu bị ốm rồi, cầu thủ mới lần đầu tham gia trận đấu quan trọng như vậy nên quá căng thẳng) và Lý Văn bổ sung \"主要的球员没参加比赛，所以大家也都受到影响了\" (Các cầu thủ chủ chốt không tham gia thi đấu nên mọi người cũng bị ảnh hưởng).","options":["因为今天天气不好，球员看不清楚球","因为几个主要的老球员生病没参加，新球员太紧张了","因为新球员不想参加这么重要的比赛","因为对手的水平比他们高得多"],"q":"这场足球比赛为什么总是踢不进去？"},{"answerIdx":1,"explanation":"Trong bài Bạch Gia Nguyệt nói \"越看越着急。我不看了，你们告诉我得分吧\" (Càng xem càng sốt ruột. Mình không xem nữa đâu, các cậu báo tỷ số cho mình nhé).","options":["她去冰箱拿啤酒和饮料了","她太着急了，决定先不看了，让李文和天中告诉她得分","她继续紧张地看着比赛结束","她和陈天中一起换了别的电视节目"],"q":"对话最后，白家月做了什么决定？"}],"scene":"在李文家，李文、白家月和陈天中一起看电视。","sceneVi":"Ở nhà Lý Văn, Lý Văn, Bạch Gia Nguyệt và Trần Thiên Trung cùng nhau xem ti vi."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"我喜欢看体育比赛，最爱看的就是奥运会。","pinyin":"Wǒ xǐhuan kàn tǐyù bǐsài, zuì ài kàn de jiùshì Àoyùnhuì.","speaker":"Đoạn văn","vi":"Tôi thích xem các trận thi đấu thể thao, thích xem nhất chính là Thế vận hội Olympic."},{"hanzi":"奥运会是世界上影响最大的体育比赛。","pinyin":"Àoyùnhuì shì shìjiè shang yǐngxiǎng zuì dà de tǐyù bǐsài.","speaker":"Đoạn văn","vi":"Thế vận hội Olympic là giải đấu thể thao có sức ảnh hưởng lớn nhất trên thế giới."},{"hanzi":"从1896年到2024年，每次奥运会都有非常多的运动员参加。","pinyin":"Cóng yībājiǔliù nián dào èrlíng'èrsì nián, měi cì Àoyùnhuì dōu yǒu fēicháng duō de yùndòngyuán cānjiā.","speaker":"Đoạn văn","vi":"Từ năm 1896 đến năm 2024, mỗi kỳ Thế vận hội đều có rất nhiều vận động viên tham gia."},{"hanzi":"第一位参加奥运会的中国运动员是刘长春，他1932年参加了100米和200米短跑比赛。","pinyin":"Dì-yī wèi cānjiā Àoyùnhuì de Zhōngguó yùndòngyuán shì Liú Chángchūn, tā yījiǔsān'èr nián cānjiāle yībǎi mǐ hé èrbǎi mǐ duǎnpǎo bǐsài.","speaker":"Đoạn văn","vi":"Vận động viên Trung Quốc đầu tiên tham gia Thế vận hội Olympic là Lưu Trường Xuân, năm 1932 ông đã tham gia thi đấu chạy ngắn 100 mét và 200 mét."},{"hanzi":"虽然他没有得到好成绩，但是他让世界认识了中国。","pinyin":"Suīrán tā méiyǒu dédào hǎo chéngjì, dànshì tā ràng shìjiè rènshi le Zhōngguó.","speaker":"Đoạn văn","vi":"Tuy ông không đạt được thành tích tốt, nhưng ông đã giúp thế giới biết đến Trung Quốc."}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài có câu \"第一位参加奥运会的中国运动员是刘长春，他1932年参加了100米和200米短跑比赛\" (Vận động viên Trung Quốc đầu tiên tham gia Thế vận hội là Lưu Trường Xuân, năm 1932 ông đã tham gia thi đấu chạy ngắn 100 mét và 200 mét).","options":["100米和200米短跑比赛","100米和400米短跑比赛","游泳和网球比赛","200米和800米短跑比赛"],"q":"1932年，刘长春在奥运会上参加了什么比赛？"},{"answerIdx":1,"explanation":"Trong bài có câu \"虽然他没有得到好成绩，但是他让世界认识了中国\" (Tuy ông không đạt được thành tích tốt, nhưng ông đã khiến thế giới biết đến Trung Quốc).","options":["他得到了非常好的比赛成绩","他让世界认识了中国","他带动很多中国运动员去打球","他成为了历史上最年轻的运动员"],"q":"刘长春参加1932年奥运会最大的意义是什么？"}],"scene":"在家里，李文准备演讲稿。","sceneVi":"Ở nhà, Lý Văn chuẩn bị bài diễn thuyết."}],"hsk3-10":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"你的数学越来越好，能不能介绍一下学习方法？","pinyin":"Nǐ de shùxué yuèláiyuè hǎo, néng bu néng jièshào yíxià xuéxí fāngfǎ?","speaker":"同学","vi":"Môn toán của cậu ngày càng giỏi, cậu có thể giới thiệu một chút phương pháp học tập được không?"},{"hanzi":"没有什么特别的方法，认真听课，认真记笔记。","pinyin":"Méiyǒu shénme tèbié de fāngfǎ, rènzhēn tīngkè, rènzhēn jì bǐjì.","speaker":"刘小雪","vi":"Không có phương pháp gì đặc biệt đâu, chăm chú nghe giảng, nghiêm túc ghi chép bài."},{"hanzi":"我看过你的笔记，记得非常清楚。","pinyin":"Wǒ kànguo nǐ de bǐjì, jì de fēicháng qīngchu.","speaker":"同学","vi":"Mình đã xem vở ghi của cậu rồi, ghi chép vô cùng rõ ràng."},{"hanzi":"老师写在黑板上的题都很重要，所以我会把这些题都记在本子上。","pinyin":"Lǎoshī xiě zài hēibǎn shang de tí dōu hěn zhòngyào, suǒyǐ wǒ huì bǎ zhèxiē tí dōu jì zài běnzi shang.","speaker":"刘小雪","vi":"Những bài tập thầy cô viết trên bảng đen đều rất quan trọng, vì vậy mình đều ghi hết những bài này vào vở."},{"hanzi":"你说得对。我没有记笔记的习惯。","pinyin":"Nǐ shuō de duì. Wǒ méiyǒu jì bǐjì de xíguàn.","speaker":"同学","vi":"Cậu nói đúng lắm. Mình không có thói quen ghi chép bài."},{"hanzi":"笔记挺重要的，我每天写作业以前，都要看一遍。","pinyin":"Bǐjì tǐng zhòngyào de, wǒ měitiān xiě zuòyè yǐqián, dōu yào kàn yí biàn.","speaker":"刘小雪","vi":"Ghi chép rất quan trọng đấy, mỗi ngày trước khi làm bài tập về nhà mình đều xem lại một lượt."},{"hanzi":"这个方法真好！我以后也试试，希望能提高成绩。","pinyin":"Zhège fāngfǎ zhēn hǎo! Wǒ yǐhòu yě shìshi, xīwàng néng tígāo chéngjì.","speaker":"同学","vi":"Phương pháp này hay thật đấy! Sau này mình cũng thử xem, hy vọng có thể nâng cao thành tích."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài Lưu Tiểu Tuyết nói \"认真听课，认真记笔记\" (Nghe giảng nghiêm túc, ghi chép cẩn thận) và \"我每天写作业以前，都要看一遍\" (Mỗi ngày trước khi làm bài tập mình đều xem lại ghi chép một lượt).","options":["每天多做几本数学练习册","上课前先预习黑板上的题","认真听课、记笔记，写作业前看一遍笔记","下课以后常去请教同学"],"q":"刘小雪学好数学的方法是什么？"},{"answerIdx":1,"explanation":"Trong bài bạn học nói \"这个方法真好！我以后也试试，希望能提高成绩\" (Phương pháp này hay quá! Sau này mình cũng thử xem, hy vọng có thể nâng cao thành tích).","options":["借刘小雪的笔记来抄一遍","也试着记笔记，希望能提高成绩","每天写完作业以后再看笔记","请老师把重要的题写在黑板上"],"q":"听了刘小雪的话，同学打算以后怎么做？"}],"scene":"在教室里，刘小雪跟同学聊学习方法。","sceneVi":"Trong phòng học, Lưu Tiểu Tuyết nói chuyện với bạn học về phương pháp học tập."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"小雪，昨天的考试，你考得怎么样？","pinyin":"Xiǎoxuě, zuótiān de kǎoshì, nǐ kǎo de zěnmeyàng?","speaker":"同学","vi":"Tiểu Tuyết, bài kiểm tra hôm qua cậu làm thế nào?"},{"hanzi":"我觉得历史有点儿难，你呢？","pinyin":"Wǒ juéde lìshǐ yǒudiǎnr nán, nǐ ne?","speaker":"刘小雪","vi":"Mình thấy môn lịch sử hơi khó một chút, còn cậu?"},{"hanzi":"数学考试我没看清楚要求，做错了好几个题，考得挺差的。","pinyin":"Shùxué kǎoshì wǒ méi kàn qīngchu yāoqiú, zuòcuò le hǎojǐ gè tí, kǎo de tǐng chà de.","speaker":"同学","vi":"Bài thi toán mình không đọc kỹ yêu cầu, làm sai mấy câu liền, thi kém lắm."},{"hanzi":"明天还有考试呢，别想那么多了，先复习外语吧。","pinyin":"Míngtiān hái yǒu kǎoshì ne, bié xiǎng nàme duō le, xiān fùxí wàiyǔ ba.","speaker":"刘小雪","vi":"Ngày mai vẫn còn bài thi nữa mà, đừng nghĩ nhiều thế nữa, ôn tập ngoại ngữ trước đi."},{"hanzi":"外语作业里有几个问题，我可以问问你吗？","pinyin":"Wàiyǔ zuòyè lǐ yǒu jǐ gè wèntí, wǒ kěyǐ wènwen nǐ ma?","speaker":"同学","vi":"Trong bài tập ngoại ngữ có mấy câu hỏi, mình có thể hỏi cậu một chút được không?"},{"hanzi":"当然可以。在学习上，遇到什么问题都可以问我。","pinyin":"Dāngrán kěyǐ. Zài xuéxí shang, yùdào shénme wèntí dōu kěyǐ wèn wǒ.","speaker":"刘小雪","vi":"Tất nhiên là được. Trong việc học, gặp vấn đề gì cũng đều có thể hỏi mình."},{"hanzi":"不好意思，这几个题我也不会。咱们还是一起去办公室问问李老师吧。","pinyin":"Bù hǎoyìsi, zhè jǐ gè tí wǒ yě bú huì. Zánmen háishì yìqǐ qù bàngōngshì wènwen Lǐ lǎoshī ba.","speaker":"刘小雪","vi":"Ngại quá, mấy câu này mình cũng không biết làm. Hay là tụi mình cùng đến văn phòng hỏi cô Lý đi."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài bạn học nói \"数学考试我没看清楚要求，做错了好几个题，考得挺差的\" (Bài thi toán mình không đọc kỹ yêu cầu, làm sai mấy câu liền, thi kém lắm).","options":["因为数学题比历史题难得多","因为他没复习数学，一直在做外语作业","因为他没看清楚要求，做错了好几个题","因为他考试的时候太紧张了，没做完"],"q":"同学昨天的数学考试为什么考得不好？"},{"answerIdx":1,"explanation":"Trong bài Lưu Tiểu Tuyết nói \"不好意思，这几个题我也不会。咱们还是一起去办公室问问李老师吧\" (Ngại quá, mấy câu này mình cũng không biết làm. Chúng ta vẫn là cùng lên văn phòng hỏi cô Lý đi).","options":["刘小雪马上教同学怎么做","两个人一起去办公室问李老师","先不做这几个题，明天考试后再说","回家查书自己解决"],"q":"对于外语作业里不会的几个问题，他们最后决定怎么办？"}],"scene":"在教室里，刘小雪跟同学聊昨天的考试。","sceneVi":"Trong phòng học, Lưu Tiểu Tuyết nói chuyện với bạn học về bài kiểm tra hôm qua."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"李老师，书上有几个问题，我们想问问您。","pinyin":"Lǐ lǎoshī, shū shang yǒu jǐ gè wèntí, wǒmen xiǎng wènwen nín.","speaker":"同学","vi":"Thưa cô Lý, trong sách có mấy câu hỏi, chúng em muốn hỏi cô ạ."},{"hanzi":"好，坐下说吧，哪个题不会？","pinyin":"Hǎo, zuòxia shuō ba, nǎge tí bú huì?","speaker":"李老师","vi":"Được, ngồi xuống nói đi, câu nào không biết làm?"},{"hanzi":"书上第五页的这个对话我看不懂，小雪也不明白。","pinyin":"Shū shang dì-wǔ yè de zhège duìhuà wǒ kàn bu dǒng, Xiǎoxuě yě bù míngbai.","speaker":"同学","vi":"Đoạn hội thoại ở trang 5 trong sách này em đọc không hiểu, Tiểu Tuyết cũng không hiểu ạ."},{"hanzi":"我课上讲过这几句话，再给你们讲一遍。","pinyin":"Wǒ kè shang jiǎngguo zhè jǐ jù huà, zài gěi nǐmen jiǎng yí biàn.","speaker":"李老师","vi":"Trên lớp cô đã giảng mấy câu này rồi, để cô giảng lại cho các em một lượt nữa."},{"hanzi":"我终于懂了。这些句子一点儿也不难。","pinyin":"Wǒ zhōngyú dǒng le. Zhèxiē jùzi yìdiǎnr yě bù nán.","speaker":"同学","vi":"Cuối cùng em cũng hiểu rồi. Những câu này chẳng khó chút nào."},{"hanzi":"我也明白了，谢谢您，李老师。","pinyin":"Wǒ yě míngbai le, xièxie nín, Lǐ lǎoshī.","speaker":"刘小雪","vi":"Em cũng hiểu rồi ạ, cảm ơn cô Lý."},{"hanzi":"我这本书上还有几个练习，你们回家也做一做，明天再把书还给我。","pinyin":"Wǒ zhè běn shū shang hái yǒu jǐ gè liànxí, nǐmen huíjiā yě zuò yi zuò, míngtiān zài bǎ shū huán gěi wǒ.","speaker":"李老师","vi":"Trên quyển sách này của cô vẫn còn mấy bài tập, các em về nhà làm thêm đi, ngày mai rồi trả sách lại cho cô."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài bạn học nói với cô Lý \"书上第五页的这个对话我看不懂，小雪也不明白\" (Đoạn hội thoại ở trang thứ năm trong sách em đọc không hiểu, Tiểu Tuyết cũng không rõ).","options":["第三页","第四页","第五页","第六页"],"q":"刘小雪和同学看不懂的对话在书的第几页？"},{"answerIdx":1,"explanation":"Trong bài cô Lý dặn \"我这本书上还有几个练习，你们回家也做一做，明天再把书还给我\" (Trên quyển sách này của cô còn mấy bài tập nữa, các em về nhà cũng làm thử đi, ngày mai trả lại sách cho cô).","options":["在办公室里把第五页的句子再读一遍","回家做老师书上的几个练习，明天再把书还给她","明天上课的时候再问其他问题","把这几句话记在笔记本上"],"q":"讲完题以后，李老师让他们做什么？"}],"scene":"在李老师办公室，刘小雪跟同学问问题。","sceneVi":"Ở văn phòng cô Lý, Lưu Tiểu Tuyết và bạn học đang hỏi bài."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"家月姐姐：你最近怎么样？","pinyin":"Jiāyuè jiějie: Nǐ zuìjìn zěnmeyàng?","speaker":"Đoạn văn","vi":"Chị Gia Nguyệt: Dạo này chị thế nào?"},{"hanzi":"忙不忙？","pinyin":"Máng bu máng?","speaker":"Đoạn văn","vi":"Có bận không ạ?"},{"hanzi":"我现在上初中二年级，学习越来越忙，后年就要考高中了。","pinyin":"Wǒ xiànzài shàng chūzhōng èr niánjí, xuéxí yuèláiyuè máng, hòunián jiù yào kǎo gāozhōng le.","speaker":"Đoạn văn","vi":"Hiện tại em đang học lớp 8 (năm hai trung học cơ sở), việc học ngày càng bận rộn, năm kia là phải thi lên cấp ba rồi."},{"hanzi":"中国的学校一般是小学六年，初中三年，高中三年。","pinyin":"Zhōngguó de xuéxiào yìbān shì xiǎoxué liù nián, chūzhōng sān nián, gāozhōng sān nián.","speaker":"Đoạn văn","vi":"Trường học ở Trung Quốc thông thường là tiểu học 6 năm, trung học cơ sở 3 năm, trung học phổ thông 3 năm."},{"hanzi":"妈妈说想考上好大学，就得上一个好高中；为了考上好高中，初中就得有一个不错的成绩，所以我现在非常努力。","pinyin":"Māma shuō xiǎng kǎoshàng hǎo dàxué, jiù děi shàng yí gè hǎo gāozhōng; wèile kǎoshàng hǎo gāozhōng, chūzhōng jiù děi yǒu yí gè búcuò de chéngjì, suǒyǐ wǒ xiànzài fēicháng nǔlì.","speaker":"Đoạn văn","vi":"Mẹ nói muốn thi đỗ đại học tốt thì phải vào được trường cấp ba tốt; để thi đỗ cấp ba tốt thì cấp hai phải có thành tích khá tốt, vì vậy hiện giờ em đang vô cùng cố gắng."},{"hanzi":"家月姐姐，你知道吗？","pinyin":"Jiāyuè jiějie, nǐ zhīdào ma?","speaker":"Đoạn văn","vi":"Chị Gia Nguyệt ơi, chị có biết không?"},{"hanzi":"在你的影响下，我也开始喜欢拍照了。","pinyin":"Zài nǐ de yǐngxiǎng xià, wǒ yě kāishǐ xǐhuan pāizhào le.","speaker":"Đoạn văn","vi":"Dưới sự ảnh hưởng của chị, em cũng bắt đầu thích chụp ảnh rồi đấy."},{"hanzi":"下次你再来北京，我给你看看我照的照片。","pinyin":"Xià cì nǐ zài lái Běijīng, wǒ gěi nǐ kànkan wǒ zhào de zhàopiàn.","speaker":"Đoạn văn","vi":"Lần sau chị đến Bắc Kinh nữa, em sẽ cho chị xem những bức ảnh em chụp."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài Lưu Tiểu Tuyết viết \"我现在上初中二年级，学习越来越忙，后年就要考高中了\" (Hiện tại em đang học lớp hai trung học cơ sở, việc học ngày càng bận, năm kia là thi lên cấp ba rồi).","options":["小学六年级","初中二年级","初中三年级","高中一年级"],"q":"刘小雪现在上几年级？"},{"answerIdx":2,"explanation":"Trong bài Lưu Tiểu Tuyết viết \"在你的影响下，我也开始喜欢拍照了\" (Dưới sự ảnh hưởng của chị, em cũng bắt đầu thích chụp ảnh rồi).","options":["写邮件","去北京旅游","拍照","看高中书"],"q":"在家月姐姐的影响下，刘小雪开始喜欢做什么了？"}],"scene":"在家里，刘小雪在写邮件。","sceneVi":"Ở nhà, Lưu Tiểu Tuyết đang viết email."}],"hsk3-11":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"会议下午几点开始？","pinyin":"Huìyì xiàwǔ jǐ diǎn kāishǐ?","speaker":"王一雪","vi":"Cuộc họp chiều nay mấy giờ bắt đầu vậy?"},{"hanzi":"今天下午经理不在，不开会了。","pinyin":"Jīntiān xiàwǔ jīnglǐ bú zài, bù kāihuì le.","speaker":"杨同乐","vi":"Chiều nay giám đốc không có ở đây, không họp nữa."},{"hanzi":"那什么时候开会？","pinyin":"Nà shénme shíhou kāihuì?","speaker":"王一雪","vi":"Vậy khi nào họp?"},{"hanzi":"后天上午十点，会议地点换到第一会议室。我正要给大家发邮件。","pinyin":"Hòutiān shàngwǔ shí diǎn, huìyì dìdiǎn huàn dào dì-yī huìyìshì. Wǒ zhèng yào gěi dàjiā fā yóujiàn.","speaker":"杨同乐","vi":"10 giờ sáng ngày kia, địa điểm họp đổi sang phòng họp số 1. Tôi đang định gửi email cho mọi người."},{"hanzi":"开会的时候，我们用会议室的电脑还是自己的笔记本电脑？","pinyin":"Kāihuì de shíhou, wǒmen yòng huìyìshì de diànnǎo háishi zìjǐ de bǐjìběn diànnǎo?","speaker":"王一雪","vi":"Lúc họp, chúng ta dùng máy tính của phòng họp hay máy tính xách tay của mình?"},{"hanzi":"会议室的电脑或者自己的电脑都可以。","pinyin":"Huìyìshì de diànnǎo huòzhě zìjǐ de diànnǎo dōu kěyǐ.","speaker":"杨同乐","vi":"Máy tính của phòng họp hoặc máy tính của mình đều được."},{"hanzi":"那到时候咱们早点儿过去，你帮我把电脑接好吧。","pinyin":"Nà dào shíhou zánmen zǎodiǎnr guòqù, nǐ bāng wǒ bǎ diànnǎo jiēhǎo ba.","speaker":"王一雪","vi":"Vậy đến lúc đó chúng ta qua sớm một chút, cậu giúp tôi kết nối sẵn máy tính nhé."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài Dương Đồng Nhạc nói: \"今天下午经理不在，不开会了。\" (Chiều nay giám đốc không có mặt nên không họp nữa), nên đáp án đúng là 因为今天下午经理不在。","options":["因为会议室的电脑坏了","因为今天下午经理不在","因为大家还没收到邮件","因为第一会议室有人在用"],"q":"为什么今天下午不开会了？"},{"answerIdx":2,"explanation":"Trong bài có câu: \"后天上午十点，会议地点换到第一会议室。\" (10 giờ sáng ngày kia, địa điểm họp đổi sang phòng họp số 1), nên đáp án đúng là 后天上午十点，第一会议室。","options":["明天上午十点，第二会议室","后天下午十点，第一会议室","后天上午十点，第一会议室","明天下午两点，办公室"],"q":"会议改在什么时候、什么地方举行？"}],"scene":"在办公室里，王一雪跟杨同乐在讨论工作。","sceneVi":"Trong văn phòng, Vương Nhất Tuyết và Dương Đồng Nhạc đang thảo luận công việc."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"电脑接好了吗？","pinyin":"Diànnǎo jiēhǎo le ma?","speaker":"王一雪","vi":"Máy tính đã kết nối xong chưa?"},{"hanzi":"已经接好了，您开机看看有没有问题。","pinyin":"Yǐjīng jiēhǎo le, nín kāijī kànkan yǒu méiyǒu wèntí.","speaker":"杨同乐","vi":"Kết nối xong rồi, chị bật máy xem thử có vấn đề gì không."},{"hanzi":"现在什么都看不见。","pinyin":"Xiànzài shénme dōu kànbujiàn.","speaker":"王一雪","vi":"Bây giờ chẳng nhìn thấy gì cả."},{"hanzi":"我检查一下哪里出问题了……您再试一下。","pinyin":"Wǒ jiǎnchá yíxià nǎlǐ chū wèntí le…… nín zài shì yíxià.","speaker":"杨同乐","vi":"Để tôi kiểm tra xem chỗ nào bị lỗi... Chị thử lại lần nữa xem."},{"hanzi":"看见了，但是听不见声音。","pinyin":"Kànjiàn le, dànshì tīngbujiàn shēngyīn.","speaker":"王一雪","vi":"Thấy hình rồi, nhưng không nghe thấy âm thanh."},{"hanzi":"现在呢？","pinyin":"Xiànzài ne?","speaker":"杨同乐","vi":"Bây giờ thì sao ạ?"},{"hanzi":"听得见声音，但是声音有点儿小，听不清楚。","pinyin":"Tīngdejiàn shēngyīn, dànshì shēngyīn yǒudiǎnr xiǎo, tīngbuqīngchu.","speaker":"王一雪","vi":"Nghe thấy âm thanh rồi, nhưng tiếng hơi nhỏ, nghe không rõ."},{"hanzi":"看来我没办法解决这个问题，只能找别人来帮帮忙了。","pinyin":"Kànlái wǒ méi bànfǎ jiějué zhège wèntí, zhǐ néng zhǎo biérén lái bāngbang máng le.","speaker":"杨同乐","vi":"Xem ra tôi không có cách nào giải quyết vấn đề này rồi, đành phải tìm người khác đến giúp một tay vậy."}],"readingQuiz":[{"answerIdx":2,"explanation":"Sau khi Dương Đồng Nhạc nói: \"我检查一下哪里出问题了……您再试一下。\", Vương Nhất Tuyết trả lời: \"看见了，但是听不见声音。\" (Nhìn thấy rồi, nhưng không nghe thấy tiếng), nên đáp án đúng là 能看见了，可是听不见声音。","options":["声音很清楚，但是什么都看不见","既能看见画面，也能听见大声的声音","能看见了，可是听不见声音","电脑完全修好了，没有任何问题"],"q":"杨同乐第一次检查以后，电脑怎么样了？"},{"answerIdx":2,"explanation":"Ở cuối bài Dương Đồng Nhạc nói: \"看来我没办法解决这个问题，只能找别人来帮帮忙了。\" (Xem ra tôi không giải quyết được vấn đề này, đành phải tìm người khác đến giúp vậy), nên đáp án đúng là 请别人过来帮忙解决问题。","options":["换一台自己的笔记本电脑","再检查一次声音为什么小","请别人过来帮忙解决问题","告诉大家今天的会不开了"],"q":"最后杨同乐打算怎么办？"}],"scene":"在会议室，王一雪跟杨同乐在做会前准备。","sceneVi":"Trong phòng họp, Vương Nhất Tuyết và Dương Đồng Nhạc đang chuẩn bị trước cuộc họp."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"同乐，你看见老张了吗？","pinyin":"Tónglè, nǐ kànjiàn Lǎo Zhāng le ma?","speaker":"王一雪","vi":"Đồng Nhạc, cậu có thấy Lão Trương không?"},{"hanzi":"老张没来。他说家里有点儿事，所以请假了。","pinyin":"Lǎo Zhāng méi lái. Tā shuō jiāli yǒudiǎnr shì, suǒyǐ qǐngjià le.","speaker":"杨同乐","vi":"Lão Trương không đến. Anh ấy nói ở nhà có chút việc nên xin nghỉ phép rồi."},{"hanzi":"好几个同事都休假了，开会前这么多工作我怕干不完。","pinyin":"Hǎo jǐ ge tóngshì dōu xiūjià le, kāihuì qián zhème duō gōngzuò wǒ pà gànbuwán.","speaker":"王一雪","vi":"Mấy đồng nghiệp đều nghỉ phép cả rồi, trước cuộc họp nhiều việc thế này tôi sợ làm không xuể."},{"hanzi":"十二点多了，咱们先去吃饭吧。吃完饭，我跟您一起把这些工作做完。","pinyin":"Shí'èr diǎn duō le, zánmen xiān qù chīfàn ba. Chīwán fàn, wǒ gēn nín yìqǐ bǎ zhèxiē gōngzuò zuòwán.","speaker":"杨同乐","vi":"Hơn mười hai giờ rồi, chúng ta đi ăn cơm trước đi. Ăn xong, tôi sẽ cùng chị làm hết đống việc này."},{"hanzi":"你先去吃，我想再干一会儿。明天开会前要发到公司的邮箱里。","pinyin":"Nǐ xiān qù chī, wǒ xiǎng zài gàn yíhuìr. Míngtiān kāihuì qián yào fā dào gōngsī de yóuxiāng li.","speaker":"王一雪","vi":"Cậu đi ăn trước đi, tôi muốn làm thêm một lát nữa. Trước cuộc họp ngày mai phải gửi vào hộp thư của công ty rồi."},{"hanzi":"您没看到邮件吗？经理还没回来呢，下周才能开会。","pinyin":"Nín méi kàndào yóujiàn ma? Jīnglǐ hái méi huílái ne, xià zhōu cái néng kāihuì.","speaker":"杨同乐","vi":"Chị chưa xem email sao? Giám đốc vẫn chưa về đâu, tuần sau mới có thể họp được."},{"hanzi":"那不着急了。走，吃饭去。","pinyin":"Nà bù zháojí le. Zǒu, chīfàn qù.","speaker":"王一雪","vi":"Thế thì không phải vội nữa rồi. Đi, đi ăn cơm thôi."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài Vương Nhất Tuyết nói: \"你先去吃，我想再干一会儿。明天开会前要发到公司的邮箱里。\" (Cậu đi ăn trước đi, tôi muốn làm thêm một lát. Trước buổi họp ngày mai phải gửi vào hòm thư của công ty), nên đáp án đúng là 她以为明天开会前要把工作发到公司邮箱。","options":["她还不太饿，想等老张回来一起吃","她以为明天开会前要把工作发到公司邮箱","她正在给经理和同事们发邮件","她已经点好了外卖，不想出去吃"],"q":"王一雪一开始为什么不想马上去吃饭？"},{"answerIdx":1,"explanation":"Trong bài Dương Đồng Nhạc nói: \"您没看到邮件吗？经理还没回来呢，下周才能开会。\" (Chị chưa xem email sao? Giám đốc vẫn chưa về, tuần sau mới họp được), nghe xong Vương Nhất Tuyết mới yên tâm đi ăn cơm, nên đáp án đúng là 经理还没回来，下周才开会。","options":["老张下午就会回来帮她工作","经理还没回来，下周才开会","其他休假的同事已经把工作做完了","杨同乐已经把邮件发到公司邮箱了"],"q":"王一雪知道了什么消息以后，才决定去吃饭？"}],"scene":"在办公室里，王一雪跟杨同乐在聊天儿。","sceneVi":"Trong văn phòng, Vương Nhất Tuyết và Dương Đồng Nhạc đang trò chuyện."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"前几天，上海的同事来北京了。","pinyin":"Qián jǐ tiān, Shànghǎi de tóngshì lái Běijīng le.","speaker":"Đoạn văn","vi":"Mấy hôm trước, các đồng nghiệp ở Thượng Hải đã đến Bắc Kinh."},{"hanzi":"一起吃饭时，他们跟我说最近有不少同事去上海工作了，问我愿意不愿意也去上海。","pinyin":"Yìqǐ chīfàn shí, tāmen gēn wǒ shuō zuìjìn yǒu bù shǎo tóngshì qù Shànghǎi gōngzuò le, wèn wǒ yuànyì bu yuànyì yě qù Shànghǎi.","speaker":"Đoạn văn","vi":"Khi ăn cơm cùng nhau, họ nói với tôi gần đây có không ít đồng nghiệp đã đến Thượng Hải làm việc, hỏi tôi có muốn cũng đến Thượng Hải không."},{"hanzi":"我是这样想的：现在丈夫和孩子都在北京，刘明的工作很忙，小雪和小明也还小，我去别的城市工作就要离开他们。","pinyin":"Wǒ shì zhèyàng xiǎng de: xiànzài zhàngfu hé háizi dōu zài Běijīng, Liú Míng de gōngzuò hěn máng, Xiǎo Xuě hé Xiǎo Míng yě hái xiǎo, wǒ qù biéde chéngshì gōngzuò jiù yào líkāi tāmen.","speaker":"Đoạn văn","vi":"Tôi nghĩ thế này: hiện tại chồng và các con đều ở Bắc Kinh, công việc của Lưu Minh rất bận, Tiểu Tuyết và Tiểu Minh cũng còn nhỏ, nếu tôi đi thành phố khác làm việc thì sẽ phải rời xa họ."},{"hanzi":"虽然去上海可能会有更好的机会，但是对我来说，生活也很重要，我不愿意为工作或学习离开家人。","pinyin":"Suīrán qù Shànghǎi kěnéng huì yǒu gèng hǎo de jīhuì, dànshì duì wǒ láishuō, shēnghuó yě hěn zhòngyào, wǒ bú yuànyì wèi gōngzuò huò xuéxí líkāi jiārén.","speaker":"Đoạn văn","vi":"Tuy rằng đến Thượng Hải có thể sẽ có cơ hội tốt hơn, nhưng đối với tôi mà nói, cuộc sống cũng rất quan trọng, tôi không muốn vì công việc hay học tập mà rời xa gia đình."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu: \"一起吃饭时，他们跟我说最近有不少同事去上海工作了，问我愿意不愿意也去上海。\" (Khi ăn cơm cùng nhau, họ nói với tôi gần đây có khá nhiều đồng nghiệp đến Thượng Hải làm việc, hỏi tôi có muốn cũng đến Thượng Hải không), nên đáp án đúng là 问她愿不愿意也去上海工作。","options":["问她为什么不让刘明去上海工作","问她愿不愿意也去上海工作","问她小雪和小明喜欢不喜欢北京","问她最近在北京的工作忙不忙"],"q":"上海的同事来北京一起吃饭时，问了王一雪什么问题？"},{"answerIdx":2,"explanation":"Trong bài Vương Nhất Tuyết viết: \"现在丈夫和孩子都在北京……我不愿意为工作或学习离开家人。\" (Hiện tại chồng và các con đều ở Bắc Kinh... tôi không muốn vì công việc hay học tập mà rời xa gia đình), nên đáp án đúng là 因为她不愿意为了工作离开在北京的家人。","options":["因为她觉得上海没有更好的机会","因为她不喜欢跟上海的同事一起工作","因为她不愿意为了工作离开在北京的家人","因为她觉得北京的工作比上海更重要"],"q":"王一雪为什么不想去上海工作？"}],"scene":"在家里，王一雪在写日记。","sceneVi":"Ở nhà, Vương Nhất Tuyết đang viết nhật ký."}],"hsk3-12":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"王老师，您看，这条街上的树都开花了。","pinyin":"Wáng lǎoshī, nín kàn, zhè tiáo jiē shàng de shù dōu kāihuā le.","speaker":"白家月","vi":"Cô Vương ơi, cô nhìn kìa, cây trên con phố này đều nở hoa hết rồi."},{"hanzi":"上周我去公园坐船了，公园里的花也开了。","pinyin":"Shàng zhōu wǒ qù gōngyuán zuòchuán le, gōngyuán li de huā yě kāi le.","speaker":"王一飞","vi":"Tuần trước cô đi công viên ngồi thuyền, hoa trong công viên cũng nở rồi."},{"hanzi":"天气这么好，下午我也想去公园坐船。","pinyin":"Tiānqì zhème hǎo, xiàwǔ wǒ yě xiǎng qù gōngyuán zuòchuán.","speaker":"白家月","vi":"Thời tiết đẹp thế này, chiều nay em cũng muốn đi công viên ngồi thuyền."},{"hanzi":"去吧！今天是工作日，人应该不多。","pinyin":"Qù ba! Jīntiān shì gōngzuòrì, rén yīnggāi bù duō.","speaker":"王一飞","vi":"Đi đi! Hôm nay là ngày làm việc, chắc là không đông người đâu."},{"hanzi":"您有时间吗？我想跟您一起去。","pinyin":"Nín yǒu shíjiān ma? Wǒ xiǎng gēn nín yìqǐ qù.","speaker":"白家月","vi":"Cô có thời gian không ạ? Em muốn đi cùng với cô."},{"hanzi":"我今天下午有课，不能去太远的地方。","pinyin":"Wǒ jīntiān xiàwǔ yǒu kè, bù néng qù tài yuǎn de dìfang.","speaker":"王一飞","vi":"Chiều nay cô có tiết dạy, không thể đi nơi quá xa được."},{"hanzi":"那咱们换一天去？","pinyin":"Nà zánmen huàn yì tiān qù?","speaker":"白家月","vi":"Vậy chúng ta đổi sang hôm khác đi nhé?"},{"hanzi":"行。或者明天去，或者后天去，我给你打电话。","pinyin":"Xíng. Huòzhě míngtiān qù, huòzhě hòutiān qù, wǒ gěi nǐ dǎ diànhuà.","speaker":"王一飞","vi":"Được đấy. Hoặc ngày mai đi, hoặc ngày kia đi, cô sẽ gọi điện cho em."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài thầy/cô Vương nói: \"我今天下午有课，不能去太远的地方。\" (Chiều nay tôi có tiết học, không thể đi nơi quá xa), nên đáp án đúng là 因为王老师今天下午有课。","options":["因为公园里的花还没有开","因为今天是工作日，公园人太多","因为王老师今天下午有课","因为王老师上周刚去过，不想再去了"],"q":"今天下午王老师为什么不能跟白家月一起去公园？"},{"answerIdx":1,"explanation":"Trong bài Vương Nhất Phi hẹn: \"或者明天去，或者后天去，我给你打电话。\" (Hoặc ngày mai đi, hoặc ngày kia đi, tôi sẽ gọi điện cho em), nên đáp án đúng là 明天或者后天。","options":["今天下午下课以后","明天或者后天","下周的工作日","这周六上午"],"q":"他们打算什么时候去公园？"}],"scene":"在街上，王一飞和白家月边走边聊。","sceneVi":"Trên phố, Vương Nhất Phi và Bạch Gia Nguyệt vừa đi vừa trò chuyện."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"刚才还是大晴天呢，怎么突然就刮起风来了？","pinyin":"Gāngcái háishi dà qíngtiān ne, zěnme tūrán jiù guā qǐ fēng lái le?","speaker":"白家月","vi":"Vừa nãy trời còn nắng to mà, sao tự nhiên lại nổi gió lên thế?"},{"hanzi":"好像新闻里说今天有雨。","pinyin":"Hǎoxiàng xīnwén li shuō jīntiān yǒu yǔ.","speaker":"王一飞","vi":"Hình như trong bản tin nói hôm nay có mưa đấy."},{"hanzi":"啊？我每天书包里都放着雨伞，就今天没带。","pinyin":"Á? Wǒ měitiān shūbāo li dōu fàngzhe yǔsǎn, jiù jīntiān méi dài.","speaker":"白家月","vi":"Á? Ngày nào trong cặp sách em cũng để sẵn ô, chỉ có hôm nay là không mang."},{"hanzi":"我可以借给你，我车里有一把伞和一件雨衣。","pinyin":"Wǒ kěyǐ jiè gěi nǐ, wǒ chē li yǒu yì bǎ sǎn hé yí jiàn yǔyī.","speaker":"王一飞","vi":"Cô có thể cho em mượn, trong xe cô có một cái ô và một chiếc áo mưa."},{"hanzi":"谢谢，希望下午天气能变好。","pinyin":"Xièxie, xīwàng xiàwǔ tiānqì néng biànhǎo.","speaker":"白家月","vi":"Cảm ơn cô, hy vọng buổi chiều thời tiết có thể tốt lên."},{"hanzi":"这个季节天气变化很快。","pinyin":"Zhège jìjié tiānqì biànhuà hěn kuài.","speaker":"王一飞","vi":"Mùa này thời tiết thay đổi nhanh lắm."},{"hanzi":"雨已经下起来了，咱们快点儿走吧。","pinyin":"Yǔ yǐjīng xià qǐlái le, zánmen kuài diǎnr zǒu ba.","speaker":"白家月","vi":"Mưa đã bắt đầu rơi rồi, chúng ta đi nhanh lên thôi."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài Bạch Gia Nguyệt nói: \"我每天书包里都放着雨伞，就今天没带。\" (Ngày nào em cũng để ô trong cặp sách, chỉ có hôm nay là không mang), nên đáp án đúng là 她每天都把伞放在书包里，只有今天没带。","options":["她平时不带伞，今天书包里正好有一把","她每天都把伞放在书包里，只有今天没带","她的雨伞和雨衣都忘在教室里了","她看到新闻说有雨，所以带了一把伞"],"q":"关于白家月带伞的事，下面哪句话是对的？"},{"answerIdx":2,"explanation":"Trong bài Vương Nhất Phi nói: \"我可以借给你，我车里有一把伞和一件雨衣。\" (Tôi có thể cho em mượn, trong xe tôi có một cái ô và một chiếc áo mưa), nên đáp án đúng là 一把雨伞和一件雨衣。","options":["两把雨伞","两件雨衣","一把雨伞和一件雨衣","一个书包和一把雨伞"],"q":"王一飞的车里有什么东西可以借给白家月？"}],"scene":"在街上，王一飞和白家月一起散步。","sceneVi":"Trên phố, Vương Nhất Phi và Bạch Gia Nguyệt cùng nhau đi dạo."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"您来这里已经一年多了，习惯了吧？","pinyin":"Nín lái zhèlǐ yǐjīng yì nián duō le, xíguàn le ba?","speaker":"白家月","vi":"Cô đến đây đã hơn một năm rồi, quen rồi chứ ạ?"},{"hanzi":"别的早就习惯了，就是天气我还不太习惯。","pinyin":"Biéde zǎo jiù xíguàn le, jiùshì tiānqì wǒ hái bú tài xíguàn.","speaker":"王一飞","vi":"Những thứ khác thì quen từ lâu rồi, chỉ có thời tiết là cô vẫn chưa quen lắm."},{"hanzi":"为什么？您不喜欢这里的天气吗？","pinyin":"Wèishénme? Nín bù xǐhuan zhèlǐ de tiānqì ma?","speaker":"白家月","vi":"Tại sao vậy ạ? Cô không thích thời tiết ở đây sao?"},{"hanzi":"我觉得冬天太冷了。","pinyin":"Wǒ juéde dōngtiān tài lěng le.","speaker":"王一飞","vi":"Cô thấy mùa đông lạnh quá."},{"hanzi":"冬天虽然冷，但是下雪的时候特别漂亮。","pinyin":"Dōngtiān suīrán lěng, dànshì xiàxuě de shíhou tèbié piàoliang.","speaker":"白家月","vi":"Mùa đông tuy lạnh, nhưng lúc tuyết rơi thì đặc biệt đẹp."},{"hanzi":"我也喜欢雪。北京常常下雪，但听说今年就下了一次。","pinyin":"Wǒ yě xǐhuan xuě. Běijīng chángcháng xiàxuě, dàn tīngshuō jīnnián jiù xià le yí cì.","speaker":"王一飞","vi":"Cô cũng thích tuyết. Bắc Kinh thường hay có tuyết rơi, nhưng nghe nói năm nay chỉ rơi có một lần."},{"hanzi":"我没关注过北京的天气，但是新闻里说过，今年冬天很多地方雪下得都少了。","pinyin":"Wǒ méi guānzhù guo Běijīng de tiānqì, dànshì xīnwén li shuō guo, jīnnián dōngtiān hěn duō dìfang xuě xià de dōu shǎo le.","speaker":"白家月","vi":"Em chưa từng theo dõi thời tiết ở Bắc Kinh, nhưng trong bản tin từng nói, mùa đông năm nay nhiều nơi tuyết rơi đều ít đi rồi."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài Vương Nhất Phi nói: \"别的早就习惯了，就是天气我还不太习惯。\" (Những thứ khác tôi quen từ lâu rồi, chỉ có thời tiết là tôi vẫn chưa quen lắm), nên đáp án đúng là 这里的天气。","options":["这里的饭菜","这里的天气","这里的教室","这里的交通"],"q":"来这里一年多了，王一飞对什么还不太习惯？"},{"answerIdx":1,"explanation":"Trong bài Bạch Gia Nguyệt nói: \"新闻里说过，今年冬天很多地方雪下得都少了。\" (Trong bản tin có nói, mùa đông năm nay nhiều nơi tuyết đều rơi ít đi), nên đáp án đúng là 今年冬天很多地方的雪都下得少了。","options":["北京今年冬天一次雪也没下","今年冬天很多地方的雪都下得少了","北京的冬天比这里更冷","今年冬天很快就要下大雨了"],"q":"白家月从新闻里知道了什么？"}],"scene":"在教室里，王一飞和白家月躲雨。","sceneVi":"Trong phòng học, Vương Nhất Phi và Bạch Gia Nguyệt đang trú mưa."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"我离开北京到这里工作一年多了。","pinyin":"Wǒ líkāi Běijīng dào zhèlǐ gōngzuò yì nián duō le.","speaker":"Đoạn văn","vi":"Tôi rời Bắc Kinh đến đây làm việc đã hơn một năm rồi."},{"hanzi":"这一年多住下来，我还是更喜欢北京的四季。","pinyin":"Zhè yì nián duō zhù xiàlái, wǒ háishi gèng xǐhuan Běijīng de sìjì.","speaker":"Đoạn văn","vi":"Sống ở đây suốt hơn một năm qua, tôi vẫn thích bốn mùa của Bắc Kinh hơn."},{"hanzi":"北京的春天最舒服，天气不冷不热。","pinyin":"Běijīng de chūntiān zuì shūfu, tiānqì bù lěng bú rè.","speaker":"Đoạn văn","vi":"Mùa xuân ở Bắc Kinh dễ chịu nhất, thời tiết không lạnh không nóng."},{"hanzi":"夏天白天很热，但是晚上比较凉快。","pinyin":"Xiàtiān báitiān hěn rè, dànshì wǎnshang bǐjiào liángkuai.","speaker":"Đoạn văn","vi":"Mùa hè ban ngày rất nóng, nhưng buổi tối khá mát mẻ."},{"hanzi":"秋天树上的叶子都变成了红色、黄色，非常漂亮。","pinyin":"Qiūtiān shù shàng de yèzi dōu biànchéng le hóngsè, huángsè, fēicháng piàoliang.","speaker":"Đoạn văn","vi":"Mùa thu lá trên cây đều biến thành màu đỏ, màu vàng, vô cùng đẹp."},{"hanzi":"冬天不但冷，而且风很大，我最不喜欢冬天。","pinyin":"Dōngtiān búdàn lěng, érqiě fēng hěn dà, wǒ zuì bù xǐhuan dōngtiān.","speaker":"Đoạn văn","vi":"Mùa đông không những lạnh mà gió còn rất to, tôi không thích mùa đông nhất."},{"hanzi":"每个人都有自己最喜欢的季节，你最喜欢哪个季节呢？","pinyin":"Měi ge rén dōu yǒu zìjǐ zuì xǐhuan de jìjié, nǐ zuì xǐhuan nǎge jìjié ne?","speaker":"Đoạn văn","vi":"Mỗi người đều có mùa mà mình thích nhất, còn bạn thích nhất mùa nào vậy?"}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài có câu: \"北京的春天最舒服，天气不冷不热。\" (Mùa xuân ở Bắc Kinh dễ chịu nhất, thời tiết không lạnh không nóng), nên đáp án đúng là 春天。","options":["春天","夏天","秋天","冬天"],"q":"王一飞觉得北京的哪个季节最舒服？"},{"answerIdx":2,"explanation":"Trong bài có câu: \"冬天不但冷，而且风很大，我最不喜欢冬天。\" (Mùa đông không những lạnh mà gió còn rất lớn, tôi không thích mùa đông nhất), nên đáp án đúng là 因为冬天不但冷，而且风很大。","options":["因为冬天树上的叶子都掉了","因为冬天几乎不下雪","因为冬天不但冷，而且风很大","因为冬天晚上太热，不凉快"],"q":"王一飞为什么最不喜欢冬天？"}],"scene":"在家里，王一飞在写日记。","sceneVi":"Ở nhà, Vương Nhất Phi đang viết nhật ký."}],"hsk3-13":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"今天我请客，你们想吃什么就点什么！","pinyin":"Jīntiān wǒ qǐngkè, nǐmen xiǎng chī shénme jiù diǎn shénme!","speaker":"杨同乐","vi":"Hôm nay tôi mời, mọi người muốn ăn gì thì cứ gọi món đó!"},{"hanzi":"那我就不客气了。听说这家饭馆的鱼做得很特别？","pinyin":"Nà wǒ jiù bú kèqi le. Tīngshuō zhè jiā fànguǎn de yú zuò de hěn tèbié?","speaker":"王一雪","vi":"Vậy thì tôi không khách sáo nữa. Nghe nói món cá của nhà hàng này làm rất đặc biệt à?"},{"hanzi":"对，南方菜跟你们北方菜的做法不同。除了鱼，你们还想吃什么？","pinyin":"Duì, nánfāng cài gēn nǐmen běifāng cài de zuòfǎ bù tóng. Chúle yú, nǐmen hái xiǎng chī shénme?","speaker":"杨同乐","vi":"Đúng vậy, cách làm món ăn miền Nam khác với món ăn miền Bắc của các bạn. Ngoài cá ra, mọi người còn muốn ăn gì nữa?"},{"hanzi":"我不常吃南方菜，还是你决定吧。","pinyin":"Wǒ bù cháng chī nánfāng cài, háishi nǐ juédìng ba.","speaker":"同事","vi":"Tôi không thường ăn món miền Nam, hay là anh quyết định đi."},{"hanzi":"好，那再加一个鸡肉，一个……","pinyin":"Hǎo, nà zài jiā yí gè jīròu, yí gè……","speaker":"杨同乐","vi":"Được, vậy gọi thêm một món thịt gà, một……"},{"hanzi":"咱们就三个人，别点那么多。","pinyin":"Zánmen jiù sān gè rén, bié diǎn nàme duō.","speaker":"王一雪","vi":"Chúng ta chỉ có ba người thôi, đừng gọi nhiều thế."},{"hanzi":"好，那先来这几个菜。","pinyin":"Hǎo, nà xiān lái zhè jǐ gè cài.","speaker":"杨同乐","vi":"Được, vậy lên trước mấy món này nhé."},{"hanzi":"对了，下周我儿子过生日，你们有时间的话，就来我家做客，我给你们做北京菜。","pinyin":"Duìle, xià zhōu wǒ érzi guò shēngrì, nǐmen yǒu shíjiān dehuà, jiù lái wǒ jiā zuòkè, wǒ gěi nǐmen zuò Běijīng cài.","speaker":"王一雪","vi":"À đúng rồi, tuần sau con trai tôi đón sinh nhật, nếu mọi người có thời gian thì đến nhà tôi chơi nhé, tôi sẽ nấu món Bắc Kinh cho mọi người ăn."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài Vương Nhất Tuyết hỏi: \"听说这家饭馆的鱼做得很特别？\" và Dương Đồng Nhạc đáp: \"对，南方菜跟你们北方菜的做法不同。\" (Đúng vậy, món miền Nam có cách làm khác với món miền Bắc của các bạn), nên đáp án đúng là 这家饭馆的鱼是南方菜，做法很特别。","options":["这家饭馆主要做北方菜","这家饭馆的鱼是南方菜，做法很特别","同事常吃南方菜，所以点了很多菜","他们三个人一共点了十几个菜"],"q":"关于这家饭馆和菜，下面哪句话是对的？"},{"answerIdx":1,"explanation":"Ở cuối bài Vương Nhất Tuyết nói: \"下周我儿子过生日，你们有时间的话，就来我家做客，我给你们做北京菜。\" (Tuần sau con trai tôi sinh nhật, nếu mọi người có thời gian thì đến nhà tôi chơi, tôi sẽ làm món Bắc Kinh cho mọi người ăn), nên đáp án đúng là 因为她儿子下周过生日。","options":["因为她想请大家去家里喝茶聊天儿","因为她儿子下周过生日","因为她刚搬了新家，想请大家吃饭","因为杨同乐很想学做北京菜"],"q":"王一雪为什么请同事们下周去她家做客？"}],"scene":"在饭馆，杨同乐请同事吃饭。","sceneVi":"Ở nhà hàng, Dương Đồng Lạc mời đồng nghiệp ăn cơm."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"第一次请新邻居来做客，总是担心有什么没准备好。","pinyin":"Dì-yī cì qǐng xīn línjū lái zuòkè, zǒngshì dānxīn yǒu shénme méi zhǔnbèi hǎo.","speaker":"王一雪","vi":"Lần đầu tiên mời hàng xóm mới sang nhà chơi, lúc nào cũng lo có thứ gì đó chưa chuẩn bị xong."},{"hanzi":"放心吧，我帮你看了，都已经准备好了。","pinyin":"Fàngxīn ba, wǒ bāng nǐ kàn le, dōu yǐjīng zhǔnbèi hǎo le.","speaker":"刘明","vi":"Yên tâm đi, anh đã xem giúp em rồi, mọi thứ đều đã chuẩn bị xong cả rồi."},{"hanzi":"我记得刚才已经把饮料拿出来了，怎么不见了？","pinyin":"Wǒ jìde gāngcái yǐjīng bǎ yǐnliào ná chūlái le, zěnme bú jiàn le?","speaker":"王一雪","vi":"Em nhớ lúc nãy đã lấy đồ uống ra rồi mà, sao lại không thấy đâu nữa?"},{"hanzi":"我把饮料和酒都放进冰箱里了，客人来了再拿出来。","pinyin":"Wǒ bǎ yǐnliào hé jiǔ dōu fàng jìn bīngxiāng lǐ le, kèrén lái le zài ná chūlái.","speaker":"刘明","vi":"Anh bỏ cả đồ uống và rượu vào trong tủ lạnh rồi, khách đến rồi lấy ra."},{"hanzi":"音乐的声音合适吗？","pinyin":"Yīnyuè de shēngyīn héshì ma?","speaker":"王一雪","vi":"Âm lượng của nhạc có vừa không?"},{"hanzi":"你把声音开得太大了，我去关小一点儿。","pinyin":"Nǐ bǎ shēngyīn kāi de tài dà le, wǒ qù guān xiǎo yìdiǎnr.","speaker":"刘明","vi":"Em mở tiếng to quá rồi, anh đi vặn nhỏ lại một chút."},{"hanzi":"好，那我们就等客人来吧。","pinyin":"Hǎo, nà wǒmen jiù děng kèrén lái ba.","speaker":"王一雪","vi":"Được, vậy chúng ta chờ khách đến thôi."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài Lưu Minh nói: \"我把饮料和酒都放进冰箱里了，客人来了再拿出来。\" (Anh để cả đồ uống và rượu vào tủ lạnh rồi, khách đến rồi mới lấy ra), nên đáp án đúng là 被刘明放进冰箱里了。","options":["被孩子喝完了","被刘明放进冰箱里了","忘在超市里没有买","还在桌子上，她没看见"],"q":"王一雪刚才拿出来的饮料去哪儿了？"},{"answerIdx":2,"explanation":"Trong bài Lưu Minh nói: \"你把声音开得太大了，我去关小一点儿。\" (Em mở tiếng to quá rồi, anh đi vặn nhỏ lại một chút), nên đáp án đúng là 声音太大了，需要关小一点儿。","options":["声音太小了，听不见","声音正好，很合适","声音太大了，需要关小一点儿","音乐不好听，要换一首"],"q":"刘明觉得音乐的声音怎么样？"}],"scene":"在家里，王一雪和刘明为生日会做准备。","sceneVi":"Ở nhà, Vương Nhất Tuyết và Lưu Minh đang chuẩn bị cho tiệc sinh nhật."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"谢谢你们来参加我儿子的生日晚会，希望大家今晚玩得开心。","pinyin":"Xièxie nǐmen lái cānjiā wǒ érzi de shēngrì wǎnhuì, xīwàng dàjiā jīnwǎn wán de kāixīn.","speaker":"王一雪","vi":"Cảm ơn mọi người đã đến tham gia tiệc sinh nhật con trai tôi, hy vọng tối nay mọi người chơi vui vẻ."},{"hanzi":"小明，生日快乐！我准备了一个小礼物，希望你喜欢！","pinyin":"Xiǎomíng, shēngrì kuàilè! Wǒ zhǔnbèi le yí gè xiǎo lǐwù, xīwàng nǐ xǐhuan!","speaker":"杨同乐","vi":"Tiểu Minh, sinh nhật vui vẻ! Chú chuẩn bị một món quà nhỏ, hy vọng cháu thích!"},{"hanzi":"谢谢您，我可以打开吗？","pinyin":"Xièxie nín, wǒ kěyǐ dǎkāi ma?","speaker":"刘小明","vi":"Cảm ơn chú ạ, cháu có thể mở ra không ạ?"},{"hanzi":"当然可以，你妈妈说你跟姐姐一样，都喜欢画画，对吗？","pinyin":"Dāngrán kěyǐ, nǐ māma shuō nǐ gēn jiějie yíyàng, dōu xǐhuan huàhuà, duì ma?","speaker":"杨同乐","vi":"Tất nhiên là được, mẹ cháu nói cháu cũng giống chị gái, đều thích vẽ tranh, đúng không?"},{"hanzi":"对，我想做一名画家。啊！画板和画笔，这正是我需要的。我太喜欢了。","pinyin":"Duì, wǒ xiǎng zuò yì míng huàjiā. À! Huàbǎn hé huàbǐ, zhè zhèng shì wǒ xūyào de. Wǒ tài xǐhuan le.","speaker":"刘小明","vi":"Vâng, cháu muốn trở thành một họa sĩ. Ôi! Bảng vẽ và bút vẽ, đây đúng là thứ cháu đang cần. Cháu thích quá đi mất."},{"hanzi":"我去把盘子拿过来，咱们一边吃蛋糕，一边聊天儿吧。","pinyin":"Wǒ qù bǎ pánzi ná guòlái, zánmen yìbiān chī dàngāo, yìbiān liáotiānr ba.","speaker":"王一雪","vi":"Tôi đi lấy đĩa lại đây, chúng ta vừa ăn bánh kem vừa trò chuyện nhé."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài Lưu Tiểu Minh mở quà ra và nói: \"啊！画板和画笔，这正是我需要的。我太喜欢了。\" (A! Bảng vẽ và bút vẽ, đây đúng là thứ cháu đang cần. Cháu thích lắm), nên đáp án đúng là 画板和画笔。","options":["一个生日蛋糕","画板和画笔","一本画画儿的书","几个漂亮的盘子"],"q":"杨同乐送给刘小明什么生日礼物？"},{"answerIdx":2,"explanation":"Ở cuối bài Vương Nhất Tuyết nói: \"我去把盘子拿过来，咱们一边吃蛋糕，一边聊天儿吧。\" (Tôi đi lấy đĩa lại đây, chúng ta vừa ăn bánh kem vừa trò chuyện nhé), nên đáp án đúng là 一边吃蛋糕，一边聊天儿。","options":["一起看小明画画儿","先喝茶，再打开其他礼物","一边吃蛋糕，一边聊天儿","一边听音乐，一边做游戏"],"q":"小明打开礼物后，王一雪建议大家做什么？"}],"scene":"在家里，王一雪和刘明办生日会。","sceneVi":"Ở nhà, Vương Nhất Tuyết và Lưu Minh tổ chức tiệc sinh nhật."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"我的新邻居是来自英国的夫妻。","pinyin":"Wǒ de xīn línjū shì láizì Yīngguó de fūqī.","speaker":"Đoạn văn","vi":"Hàng xóm mới của tôi là một cặp vợ chồng đến từ nước Anh."},{"hanzi":"上周我去他们家做客了。","pinyin":"Shàng zhōu wǒ qù tāmen jiā zuòkè le.","speaker":"Đoạn văn","vi":"Tuần trước tôi đã đến nhà họ chơi."},{"hanzi":"他们做了很多好吃的，还准备了英国的红茶。","pinyin":"Tāmen zuò le hěn duō hǎochī de, hái zhǔnbèi le Yīngguó de hóngchá.","speaker":"Đoạn văn","vi":"Họ làm rất nhiều món ngon, còn chuẩn bị cả hồng trà Anh nữa."},{"hanzi":"那天我跟他们一边喝红茶，一边聊天儿，直到十二点多才回家。","pinyin":"Nà tiān wǒ gēn tāmen yìbiān hē hóngchá, yìbiān liáotiānr, zhídào shí'èr diǎn duō cái huí jiā.","speaker":"Đoạn văn","vi":"Hôm đó tôi vừa uống hồng trà vừa trò chuyện với họ, mãi đến hơn mười hai giờ mới về nhà."},{"hanzi":"他们年轻的时候喜欢旅游，他家有一张世界地图，上面每一个红点都是他们去过的地方。","pinyin":"Tāmen niánqīng de shíhou xǐhuan lǚyóu, tā jiā yǒu yì zhāng shìjiè dìtú, shàngmian měi yí gè hóngdiǎn dōu shì tāmen qù guo de dìfang.","speaker":"Đoạn văn","vi":"Hồi trẻ họ rất thích đi du lịch, nhà họ có một tấm bản đồ thế giới, mỗi chấm đỏ trên đó đều là nơi họ từng đi qua."},{"hanzi":"后来，他们感到东方的文化很特别，就开始学习中文。","pinyin":"Hòulái, tāmen gǎndào dōngfāng de wénhuà hěn tèbié, jiù kāishǐ xuéxí Zhōngwén.","speaker":"Đoạn văn","vi":"Sau này, họ cảm thấy văn hóa phương Đông rất đặc biệt nên bắt đầu học tiếng Trung."},{"hanzi":"今天是小明的生日，我请他们到我家玩，来看看中国人的家，也尝尝中国菜。","pinyin":"Jīntiān shì Xiǎomíng de shēngrì, wǒ qǐng tāmen dào wǒ jiā wán, lái kànkan Zhōngguórén de jiā, yě chángchang Zhōngguó cài.","speaker":"Đoạn văn","vi":"Hôm nay là sinh nhật của Tiểu Minh, tôi mời họ đến nhà tôi chơi, đến xem nhà của người Trung Quốc và cũng nếm thử món ăn Trung Quốc."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu: \"他家有一张世界地图，上面每一个红点都是他们去过的地方。\" (Nhà họ có một tấm bản đồ thế giới, mỗi chấm đỏ trên đó đều là nơi họ đã từng đến), nên đáp án đúng là 他们以前去过的地方。","options":["他们想去还没去的地方","他们以前去过的地方","他们住过超过一年的城市","英国和中国有名的城市"],"q":"新邻居家世界地图上的每一个红点表示什么？"},{"answerIdx":1,"explanation":"Trong bài có câu: \"后来，他们感到东方的文化很特别，就开始学习中文。\" (Sau này, họ cảm thấy văn hóa phương Đông rất đặc biệt nên bắt đầu học tiếng Trung), nên đáp án đúng là 因为他们觉得东方文化很特别。","options":["因为他们要来中国做生意","因为他们觉得东方文化很特别","因为王一雪请他们教自己英文","因为他们想看懂世界地图"],"q":"那对英国夫妻为什么开始学习中文？"}],"scene":"在家里，王一雪在写日记。","sceneVi":"Ở nhà, Vương Nhất Tuyết đang viết nhật ký."}],"hsk3-14":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"我借的这本词典最好今天还，但是我没时间去。","pinyin":"Wǒ jiè de zhè běn cídiǎn zuìhǎo jīntiān huán, dànshì wǒ méi shíjiān qù.","speaker":"李文","vi":"Cuốn từ điển này tôi mượn tốt nhất hôm nay phải trả, nhưng tôi không có thời gian đi."},{"hanzi":"下午我只有两节课，可以帮你去图书馆还书。","pinyin":"Xiàwǔ wǒ zhǐ yǒu liǎng jié kè, kěyǐ bāng nǐ qù túshūguǎn huán shū.","speaker":"白家月","vi":"Buổi chiều mình chỉ có hai tiết học, có thể giúp cậu đến thư viện trả sách."},{"hanzi":"那太谢谢了。你能再帮我借本书吗？","pinyin":"Nà tài xièxie le. Nǐ néng zài bāng wǒ jiè běn shū ma?","speaker":"李文","vi":"Vậy thì cảm ơn nhiều quá. Cậu có thể mượn giúp mình thêm một cuốn sách nữa không?"},{"hanzi":"行，你告诉我书名。","pinyin":"Xíng, nǐ gàosu wǒ shūmíng.","speaker":"白家月","vi":"Được, cậu nói cho mình biết tên sách đi."},{"hanzi":"我把名字写在纸上吧。我去了好几次图书馆，这本书都被别人借走了。","pinyin":"Wǒ bǎ míngzi xiě zài zhǐ shàng ba. Wǒ qù le hǎo jǐ cì túshūguǎn, zhè běn shū dōu bèi biérén jiè zǒu le.","speaker":"李文","vi":"Để mình viết tên lên giấy nhé. Mình đến thư viện mấy lần rồi, lần nào cuốn sách này cũng bị người khác mượn mất rồi."},{"hanzi":"《名人的故事》？我有这本书。明天我借给你吧。","pinyin":"《Míngrén de Gùshi》? Wǒ yǒu zhè běn shū. Míngtiān wǒ jiè gěi nǐ ba.","speaker":"白家月","vi":"\"Câu chuyện về những người nổi tiếng\" à? Mình có cuốn sách này đấy. Ngày mai mình cho cậu mượn nhé."}],"readingQuiz":[{"answerIdx":0,"explanation":"Ở đầu bài Lý Văn nói: \"我借的这本词典最好今天还，但是我没时间去。\" và Bạch Gia Nguyệt nhận lời: \"下午我只有两节课，可以帮你去图书馆还书。\" (Buổi chiều mình chỉ có hai tiết, có thể giúp cậu đến thư viện trả sách), nên đáp án đúng là 去图书馆帮他还一本词典。","options":["去图书馆帮他还一本词典","去书店帮他买一本《名人的故事》","帮他写下书的名字","借给他一本中文词典"],"q":"李文一开始请白家月帮什么忙？"},{"answerIdx":2,"explanation":"Ở cuối bài Bạch Gia Nguyệt nói: \"《名人的故事》？我有这本书。明天我借给你吧。\" (\"Câu chuyện danh nhân\" à? Mình có cuốn sách này đấy. Ngày mai mình cho cậu mượn nhé), nên đáp án đúng là 她自己有这本书，明天借给他。","options":["她今天下午去图书馆帮他借","这本书太难借了，让他再等等","她自己有这本书，明天借给他","她也没看过这本书，也想借来看"],"q":"知道李文想借《名人的故事》以后，白家月怎么说？"}],"scene":"在校园餐厅，李文和白家月在聊天儿。","sceneVi":"Ở nhà ăn trong khuôn viên trường, Lý Văn và Bạch Gia Nguyệt đang trò chuyện."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"今天下课早，你一会儿做什么？","pinyin":"Jīntiān xiàkè zǎo, nǐ yíhuìr zuò shénme?","speaker":"安妮","vi":"Hôm nay tan học sớm, lát nữa cậu làm gì thế?"},{"hanzi":"我今天忙得很，要先去图书馆借书，然后去游泳。","pinyin":"Wǒ jīntiān máng de hěn, yào xiān qù túshūguǎn jiè shū, ránhòu qù yóuyǒng.","speaker":"白家月","vi":"Hôm nay mình bận lắm, phải đến thư viện mượn sách trước, sau đó đi bơi."},{"hanzi":"咱们一起走吧，我想去图书馆看看中文报纸。","pinyin":"Zánmen yìqǐ zǒu ba, wǒ xiǎng qù túshūguǎn kànkan Zhōngwén bàozhǐ.","speaker":"安妮","vi":"Chúng mình đi cùng đi, mình muốn đến thư viện đọc báo tiếng Trung."},{"hanzi":"等等，我的校园卡不见了，没有卡进不去图书馆。","pinyin":"Děngdeng, wǒ de xiàoyuánkǎ bú jiàn le, méiyǒu kǎ jìn bu qù túshūguǎn.","speaker":"白家月","vi":"Đợi đã, thẻ sinh viên của mình mất đâu rồi, không có thẻ thì không vào được thư viện."},{"hanzi":"你想想上一次用是什么时候？","pinyin":"Nǐ xiǎngxiang shàng yí cì yòng shì shénme shíhou?","speaker":"安妮","vi":"Cậu thử nghĩ xem lần trước dùng là lúc nào?"},{"hanzi":"我忘记了，可能被我放在家里了。","pinyin":"Wǒ wàngjì le, kěnéng bèi wǒ fàng zài jiā lǐ le.","speaker":"白家月","vi":"Mình quên mất rồi, có thể bị mình để quên ở nhà rồi."},{"hanzi":"进不去图书馆也没关系，上网看看有没有电子书。","pinyin":"Jìn bu qù túshūguǎn yě méi guānxi, shàngwǎng kànkan yǒu méiyǒu diànzǐshū.","speaker":"安妮","vi":"Không vào được thư viện cũng không sao, lên mạng xem thử có sách điện tử không."},{"hanzi":"不行，我必须去，我还得帮李文还书呢。","pinyin":"Bù xíng, wǒ bìxū qù, wǒ hái děi bāng Lǐ Wén huán shū ne.","speaker":"白家月","vi":"Không được, mình nhất định phải đi, mình còn phải trả sách giúp Lý Văn nữa."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài Bạch Gia Nguyệt nói: \"等等，我的校园卡不见了，没有卡进不去图书馆。\" (Khoan đã, thẻ sinh viên của mình mất rồi, không có thẻ thì không vào được thư viện), nên đáp án đúng là 她的校园卡不见了，进不去图书馆。","options":["她把李文的书忘在家里了","她的校园卡不见了，进不去图书馆","图书馆今天关门，不能借书","游泳馆快关门了，她没有时间"],"q":"白家月准备跟安妮一起去图书馆时，发现了什么问题？"},{"answerIdx":2,"explanation":"Ở cuối bài Bạch Gia Nguyệt nói: \"不行，我必须去，我还得帮李文还书呢。\" (Không được, mình nhất định phải đi, mình còn phải trả sách giúp Lý Văn nữa), nên đáp án đúng là 因为她还要帮李文还书。","options":["因为她一定要借到中文报纸","因为她必须去那里找她的校园卡","因为她还要帮李文还书","因为她不喜欢看网上的电子书"],"q":"白家月为什么说她必须去图书馆？"}],"scene":"在校园里，白家月和安妮在聊天儿。","sceneVi":"Trong khuôn viên trường, Bạch Gia Nguyệt và Anne đang trò chuyện."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"下周学校有晚会，你知道吗？","pinyin":"Xià zhōu xuéxiào yǒu wǎnhuì, nǐ zhīdào ma?","speaker":"李文","vi":"Tuần sau trường có buổi dạ hội, cậu biết không?"},{"hanzi":"知道，我和几个女生要表演一个节目。你也参加吗？","pinyin":"Zhīdào, wǒ hé jǐ gè nǚshēng yào biǎoyǎn yí gè jiémù. Nǐ yě cānjiā ma?","speaker":"白家月","vi":"Biết chứ, mình và mấy bạn nữ sẽ biểu diễn một tiết mục. Cậu cũng tham gia à?"},{"hanzi":"我想唱中文歌，但是还没找到人一起表演，不知道怎么办。","pinyin":"Wǒ xiǎng chàng Zhōngwén gē, dànshì hái méi zhǎodào rén yìqǐ biǎoyǎn, bù zhīdào zěnme bàn.","speaker":"李文","vi":"Mình muốn hát bài hát tiếng Trung, nhưng vẫn chưa tìm được người biểu diễn cùng, không biết phải làm sao nữa."},{"hanzi":"找不到人，你就一个人唱吧。","pinyin":"Zhǎo bu dào rén, nǐ jiù yí gè rén chàng ba.","speaker":"白家月","vi":"Không tìm được người thì cậu hát một mình đi."},{"hanzi":"一想到要在校长、老师和那么多同学面前表演，我就有些紧张。","pinyin":"Yì xiǎngdào yào zài xiàozhǎng, lǎoshī hé nàme duō tóngxué miànqián biǎoyǎn, wǒ jiù yǒuxiē jǐnzhāng.","speaker":"李文","vi":"Hễ nghĩ đến việc phải biểu diễn trước mặt hiệu trưởng, thầy cô và nhiều bạn học như thế, mình lại thấy hơi hồi hộp."},{"hanzi":"紧张什么啊，我们都喜欢听你唱歌，你要相信自己。","pinyin":"Jǐnzhāng shénme a, wǒmen dōu xǐhuan tīng nǐ chànggē, nǐ yào xiāngxìn zìjǐ.","speaker":"白家月","vi":"Hồi hộp cái gì chứ, bọn mình đều thích nghe cậu hát, cậu phải tin vào bản thân mình chứ."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài Lý Văn nói: \"一想到要在校长、老师和那么多同学面前表演，我就有些紧张。\" (Hễ nghĩ đến việc phải biểu diễn trước hiệu trưởng, thầy cô và nhiều bạn học như vậy là mình hơi căng thẳng), nên đáp án đúng là 他一个人表演，在这么多人面前会有些紧张。","options":["他不知道怎么参加晚会","他还没学会唱那首中文歌","他一个人表演，在这么多人面前会有些紧张","校长和老师不喜欢听他唱中文歌"],"q":"关于下周学校的晚会，李文在担心什么？"},{"answerIdx":1,"explanation":"Ở cuối bài Bạch Gia Nguyệt động viên: \"紧张什么啊，我们都喜欢听你唱歌，你要相信自己。\" (Căng thẳng gì chứ, bọn mình đều thích nghe cậu hát, cậu phải tin vào bản thân mình), nên đáp án đúng là 她说大家都喜欢听他唱歌，让他相信自己。","options":["她说可以陪李文一起唱中文歌","她说大家都喜欢听他唱歌，让他相信自己","她建议李文不要参加这次晚会了","她说校长和老师那天不会来看晚会"],"q":"白家月是怎么鼓励李文的？"}],"scene":"在校园餐厅，李文和白家月边吃边聊。","sceneVi":"Ở nhà ăn trong khuôn viên trường, Lý Văn và Bạch Gia Nguyệt vừa ăn vừa trò chuyện."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"昨天是我们学校的新年晚会，每个班级的同学都表演节目了。","pinyin":"Zuótiān shì wǒmen xuéxiào de xīnnián wǎnhuì, měi gè bānjí de tóngxué dōu biǎoyǎn jiémù le.","speaker":"Đoạn văn","vi":"Hôm qua là buổi dạ hội năm mới của trường chúng tôi, các bạn học ở mỗi lớp đều đã biểu diễn tiết mục."},{"hanzi":"晚会是八点开始的，差不多十二点才结束。","pinyin":"Wǎnhuì shì bā diǎn kāishǐ de, chàbuduō shí'èr diǎn cái jiéshù.","speaker":"Đoạn văn","vi":"Buổi dạ hội bắt đầu lúc tám giờ, gần mười hai giờ mới kết thúc."},{"hanzi":"我一个晚上跟大家一起又唱又跳，开心极了，也累坏了。","pinyin":"Wǒ yí gè wǎnshang gēn dàjiā yìqǐ yòu chàng yòu tiào, kāixīn jíle, yě lèi huài le.","speaker":"Đoạn văn","vi":"Cả buổi tối tôi cùng mọi người vừa hát vừa nhảy, vui cực kỳ, mà cũng mệt lử luôn."},{"hanzi":"我最喜欢的节目是留学生们跳舞，最后老师和校长也被叫起来一块儿跳，特别有意思。","pinyin":"Wǒ zuì xǐhuan de jiémù shì liúxuéshēngmen tiàowǔ, zuìhòu lǎoshī hé xiàozhǎng yě bèi jiào qǐlái yíkuàir tiào, tèbié yǒu yìsi.","speaker":"Đoạn văn","vi":"Tiết mục tôi thích nhất là các lưu học sinh múa, cuối cùng thầy cô và hiệu trưởng cũng được gọi lên nhảy cùng nhau, vô cùng thú vị."},{"hanzi":"过几天学校的网站上会有晚会的视频，我打算再看一遍。","pinyin":"Guò jǐ tiān xuéxiào de wǎngzhàn shàng huì yǒu wǎnhuì de shìpín, wǒ dǎsuàn zài kàn yí biàn.","speaker":"Đoạn văn","vi":"Vài ngày nữa trên trang web của trường sẽ có video của buổi dạ hội, tôi dự định sẽ xem lại một lần nữa."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu: \"晚会是八点开始的，差不多十二点才结束。\" (Buổi dạ hội bắt đầu lúc 8 giờ, gần 12 giờ mới kết thúc), nên đáp án đúng là 八点开始，差不多十二点结束。","options":["七点开始，十一点结束","八点开始，差不多十二点结束","八点半开始，十点半结束","下午开始，晚上八点结束"],"q":"学校的新年晚会是什么时候开始、什么时候结束的？"},{"answerIdx":2,"explanation":"Trong bài Bạch Gia Nguyệt viết: \"我最喜欢的节目是留学生们跳舞，最后老师和校长也被叫起来一块儿跳，特别有意思。\" (Tiết mục mình thích nhất là các du học sinh nhảy múa, cuối cùng thầy cô và hiệu trưởng cũng được gọi lên nhảy cùng, rất thú vị), nên đáp án đúng là 留学生们跳舞。","options":["她和几个女生一起表演的节目","李文一个人唱的中文歌","留学生们跳舞","每个班级的合唱节目"],"q":"白家月最喜欢晚会上的哪个节目？"}],"scene":"在家里，白家月在写日记。","sceneVi":"Ở nhà, Bạch Gia Nguyệt đang viết nhật ký."}],"hsk3-15":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"您搬到蓝天小区一段时间了，觉得怎么样？","pinyin":"Nín bān dào Lántiān Xiǎoqū yí duàn shíjiān le, juéde zěnmeyàng?","speaker":"杨同乐","vi":"Chị chuyển đến khu dân cư Lam Thiên được một thời gian rồi, cảm thấy thế nào?"},{"hanzi":"小区环境挺好的，附近买东西也很方便，过马路就是超市。","pinyin":"Xiǎoqū huánjìng tǐng hǎo de, fùjìn mǎi dōngxi yě hěn fāngbiàn, guò mǎlù jiù shì chāoshì.","speaker":"王一雪","vi":"Môi trường khu dân cư khá tốt, gần đây mua đồ cũng rất tiện, qua đường là tới siêu thị."},{"hanzi":"平时孩子们在哪儿玩？","pinyin":"Píngshí háizimen zài nǎr wán?","speaker":"杨同乐","vi":"Bình thường bọn trẻ chơi ở đâu?"},{"hanzi":"小区里有很多树，孩子们放学后就在树下做游戏。你想买房子吗？","pinyin":"Xiǎoqū lǐ yǒu hěn duō shù, háizimen fàngxué hòu jiù zài shù xià zuò yóuxì. Nǐ xiǎng mǎi fángzi ma?","speaker":"王一雪","vi":"Trong khu dân cư có rất nhiều cây, bọn trẻ sau khi tan học liền chơi trò chơi dưới gốc cây. Cậu muốn mua nhà à?"},{"hanzi":"是。我想买一个大房子，让我爸妈过来跟我一起住。","pinyin":"Shì. Wǒ xiǎng mǎi yí gè dà fángzi, ràng wǒ bàmā guòlái gēn wǒ yìqǐ zhù.","speaker":"杨同乐","vi":"Vâng. Tôi muốn mua một căn nhà lớn để bố mẹ tôi qua ở cùng tôi."},{"hanzi":"蓝天小区的老人挺多的，这几年小区根据他们的需要，有了很多变化。","pinyin":"Lántiān Xiǎoqū de lǎorén tǐng duō de, zhè jǐ nián xiǎoqū gēnjù tāmen de xūyào, yǒu le hěn duō biànhuà.","speaker":"王一雪","vi":"Người cao tuổi ở khu dân cư Lam Thiên khá đông, mấy năm nay khu dân cư dựa theo nhu cầu của họ đã có rất nhiều thay đổi."},{"hanzi":"真不错！过几天我去蓝天小区看看。","pinyin":"Zhēn búcuò! Guò jǐ tiān wǒ qù Lántiān Xiǎoqū kànkan.","speaker":"杨同乐","vi":"Thật tuyệt! Mấy hôm nữa tôi sẽ đến khu dân cư Lam Thiên xem thử."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, Vương Nhất Tuyết nói \"小区环境挺好的，附近买东西也很方便，过马路就是超市。\" (Môi trường khu dân cư khá tốt, gần đó mua đồ cũng rất tiện, qua đường là tới siêu thị.), nên đáp án đúng là môi trường tốt và mua sắm thuận tiện.","options":["买东西不太方便，超市很远","环境不错，买东西很方便","小区里没有树，也没有老人","这几年小区一点儿变化也没有"],"q":"关于蓝天小区，王一雪觉得怎么样？"},{"answerIdx":2,"explanation":"Trong bài có câu \"我想买一个大房子，让我爸妈过来跟我一起住。\" (Tôi muốn mua một căn nhà lớn để bố mẹ tôi qua sống cùng tôi.), nên đáp án đúng là vì muốn đón bố mẹ đến ở cùng.","options":["因为现在的房子离公司太远","因为想让孩子们在树下做游戏","因为想让爸爸妈妈过来一起住","因为王一雪劝他马上买房子"],"q":"杨同乐为什么想买一个大房子？"}],"scene":"在办公室里，王一雪和杨同乐在聊天儿。","sceneVi":"Ở trong văn phòng, Vương Nhất Tuyết và Dương Đồng Lạc đang trò chuyện."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"假期我想去南京旅游，但是我不太了解那里。","pinyin":"Jiàqī wǒ xiǎng qù Nánjīng lǚyóu, dànshì wǒ bú tài liǎojiě nàli.","speaker":"王一雪","vi":"Kỳ nghỉ tôi muốn đi Nam Kinh du lịch, nhưng tôi không hiểu rõ nơi đó lắm."},{"hanzi":"我虽然不是南京人，可是我是在南京上的大学，可以说是半个南京人。","pinyin":"Wǒ suīrán bú shì Nánjīng rén, kěshì wǒ shì zài Nánjīng shàng de dàxué, kěyǐ shuō shì bàn gè Nánjīng rén.","speaker":"杨同乐","vi":"Tôi tuy không phải người Nam Kinh, nhưng tôi học đại học ở Nam Kinh, có thể nói là nửa người Nam Kinh rồi."},{"hanzi":"太好了！你快给我介绍一下南京吧。","pinyin":"Tài hǎo le! Nǐ kuài gěi wǒ jièshào yíxià Nánjīng ba.","speaker":"王一雪","vi":"Tuyệt quá! Cậu mau giới thiệu cho tôi một chút về Nam Kinh đi."},{"hanzi":"南京有两千年以上的历史，有老城、老街，还有很多有名的景点，每年去旅游的游客特别多。","pinyin":"Nánjīng yǒu liǎngqiān nián yǐshàng de lìshǐ, yǒu lǎochéng, lǎojiē, hái yǒu hěn duō yǒumíng de jǐngdiǎn, měinián qù lǚyóu de yóukè tèbié duō.","speaker":"杨同乐","vi":"Nam Kinh có lịch sử hơn hai nghìn năm, có thành cổ, phố cổ, còn có rất nhiều danh lam thắng cảnh nổi tiếng, mỗi năm du khách đến du lịch đặc biệt đông."},{"hanzi":"除了这些以外，你再告诉我一些外地人不知道的地方。","pinyin":"Chúle zhèxiē yǐwài, nǐ zài gàosu wǒ yìxiē wàidì rén bù zhīdào de dìfang.","speaker":"王一雪","vi":"Ngoài những chỗ này ra, cậu kể thêm cho tôi một số nơi mà người từ nơi khác đến không biết đi."},{"hanzi":"那太多了，我得一点儿一点儿给您讲。","pinyin":"Nà tài duō le, wǒ děi yìdiǎnr yìdiǎnr gěi nín jiǎng.","speaker":"杨同乐","vi":"Nhiều lắm luôn đấy, tôi phải kể từ từ cho chị nghe."},{"hanzi":"行，下班后我请你吃晚饭，咱们边吃边聊。","pinyin":"Xíng, xiàbān hòu wǒ qǐng nǐ chī wǎnfàn, zánmen biān chī biān liáo.","speaker":"王一雪","vi":"Được, sau giờ làm tôi mời cậu ăn bữa tối, chúng ta vừa ăn vừa trò chuyện."}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài, Dương Đồng Lạc nói \"我虽然不是南京人，可是我是在南京上的大学，可以说是半个南京人。\" (Tuy tôi không phải người Nam Kinh, nhưng tôi học đại học ở Nam Kinh, có thể coi là nửa người Nam Kinh.), nên đáp án đúng là vì anh ấy đã học đại học ở Nam Kinh.","options":["因为他在南京上了大学","因为他的爸爸妈妈是南京人","因为他每年都去南京旅游","因为他在南京工作了很多年"],"q":"杨同乐为什么说自己是“半个南京人”？"},{"answerIdx":3,"explanation":"Ở cuối đoạn hội thoại, Vương Nhất Tuyết nói \"行，下班后我请你吃晚饭，咱们边吃边聊。\" (Được, sau khi tan làm tôi mời cậu ăn tối, chúng ta vừa ăn vừa nói chuyện.), nên đáp án đúng là mời Dương Đồng Lạc ăn tối và vừa ăn vừa trò chuyện.","options":["自己回家查南京的景点","马上坐火车去南京旅游","跟杨同乐一起去参观老街","请杨同乐吃晚饭，边吃边聊"],"q":"下班以后，王一雪打算做什么？"}],"scene":"在办公室里，王一雪和杨同乐在聊天儿。","sceneVi":"Ở trong văn phòng, Vương Nhất Tuyết và Dương Đồng Lạc đang trò chuyện."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"小明，中国有一条大河，它的名字跟颜色有关系，你知道是什么河吗？","pinyin":"Xiǎomíng, Zhōngguó yǒu yì tiáo dàhé, tā de míngzi gēn yánsè yǒu guānxi, nǐ zhīdào shì shénme hé ma?","speaker":"王一雪","vi":"Tiểu Minh, Trung Quốc có một con sông lớn, tên của nó có liên quan đến màu sắc, con có biết là sông gì không?"},{"hanzi":"我知道，是黄河！","pinyin":"Wǒ zhīdào, shì Huáng Hé!","speaker":"刘小明","vi":"Con biết ạ, là sông Hoàng Hà!"},{"hanzi":"你说对了。我再问问你，你知道它为什么叫黄河吗？","pinyin":"Nǐ shuō duì le. Wǒ zài wènwen nǐ, nǐ zhīdào tā wèishénme jiào Huáng Hé ma?","speaker":"王一雪","vi":"Con nói đúng rồi. Mẹ hỏi con thêm nhé, con có biết tại sao nó gọi là sông Hoàng Hà không?"},{"hanzi":"因为河水看起来是黄色的，所以叫这个名字。黄河是中国最长的河吗？","pinyin":"Yīnwèi héshuǐ kàn qǐlái shì huángsè de, suǒyǐ jiào zhège míngzi. Huáng Hé shì Zhōngguó zuì cháng de hé ma?","speaker":"刘小明","vi":"Bởi vì nước sông trông có màu vàng, nên gọi bằng tên này ạ. Sông Hoàng Hà có phải là con sông dài nhất Trung Quốc không ạ?"},{"hanzi":"不是。黄河虽然不是最长的河，可是在历史上很重要。","pinyin":"Bú shì. Huáng Hé suīrán bú shì zuì cháng de hé, kěshì zài lìshǐ shàng hěn zhòngyào.","speaker":"王一雪","vi":"Không phải. Sông Hoàng Hà tuy không phải con sông dài nhất, nhưng trong lịch sử lại rất quan trọng."},{"hanzi":"这个我知道。很久以前，很多中国人都住在黄河边上。","pinyin":"Zhège wǒ zhīdào. Hěn jiǔ yǐqián, hěn duō Zhōngguórén dōu zhù zài Huáng Hé biānshang.","speaker":"刘小明","vi":"Điều này con biết ạ. Rất lâu trước đây, rất nhiều người Trung Quốc đều sống ở ven sông Hoàng Hà."},{"hanzi":"对。在我们中国人看来，黄河像妈妈一样，养了我们几千年。","pinyin":"Duì. Zài wǒmen Zhōngguórén kànlái, Huáng Hé xiàng māma yíyàng, yǎng le wǒmen jǐ qiān nián.","speaker":"王一雪","vi":"Đúng vậy. Trong mắt người Trung Quốc chúng ta, sông Hoàng Hà giống như người mẹ vậy, đã nuôi dưỡng chúng ta hàng nghìn năm."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, Lưu Tiểu Minh trả lời \"因为河水看起来是黄色的，所以叫这个名字。\" (Vì nước sông trông có màu vàng nên gọi bằng cái tên này.), nên đáp án đúng là vì nước sông trông có màu vàng.","options":["因为它是中国最长的河","因为它的河水看起来是黄色的","因为河边种着很多黄色的花","因为中国人像妈妈一样喜欢它"],"q":"在刘小明看来，黄河为什么叫“黄河”？"},{"answerIdx":2,"explanation":"Trong bài, Vương Nhất Tuyết nói \"黄河虽然不是最长的河，可是在历史上很重要。\" (Hoàng Hà tuy không phải con sông dài nhất, nhưng trong lịch sử rất quan trọng.), nên đáp án đúng là sông Hoàng Hà rất quan trọng trong lịch sử.","options":["它是中国最长的河","很久以前没有人住在河边","它在历史上非常重要","它的名字跟颜色没有关系"],"q":"根据王一雪的话，关于黄河哪句话是对的？"}],"scene":"在家里，王一雪和刘小明在聊天儿。","sceneVi":"Ở nhà, Vương Nhất Tuyết và Lưu Tiểu Minh đang trò chuyện."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"我小时候住在北京的西北边，有一条非常有名的河经过那里。","pinyin":"Wǒ xiǎoshíhou zhù zài Běijīng de xīběibiān, yǒu yì tiáo fēicháng yǒumíng de hé jīngguò nàli.","speaker":"Đoạn văn","vi":"Hồi nhỏ tôi sống ở phía tây bắc Bắc Kinh, có một con sông rất nổi tiếng chảy qua nơi đó."},{"hanzi":"我家就住在河边。","pinyin":"Wǒ jiā jiù zhù zài hébiān.","speaker":"Đoạn văn","vi":"Nhà tôi sống ngay bên bờ sông."},{"hanzi":"那里有高高的大树和绿绿的草地。","pinyin":"Nàli yǒu gāogāo de dàshù hé lǜlǜ de cǎodì.","speaker":"Đoạn văn","vi":"Ở đó có những cây to cao vút và bãi cỏ xanh mướt."},{"hanzi":"春天，河边的花都开了，看起来特别漂亮。","pinyin":"Chūntiān, hébiān de huā dōu kāi le, kàn qǐlái tèbié piàoliang.","speaker":"Đoạn văn","vi":"Mùa xuân, hoa bên bờ sông đều nở rộ, trông đặc biệt xinh đẹp."},{"hanzi":"还记得小时候，一到夏天我就去河里游泳。","pinyin":"Hái jìde xiǎoshíhou, yí dào xiàtiān wǒ jiù qù hé lǐ yóuyǒng.","speaker":"Đoạn văn","vi":"Còn nhớ hồi nhỏ, cứ đến mùa hè là tôi lại xuống sông bơi lội."},{"hanzi":"长大以后，遇到什么不开心的事情，我就去河边的树下坐着，听听鸟叫，看看河水，跟遇见的朋友聊聊天儿，难过的事情不一会儿就忘了。","pinyin":"Zhǎngdà yǐhòu, yùdào shénme bù kāixīn de shìqing, wǒ jiù qù hébiān de shù xià zuòzhe, tīngting niǎo jiào, kànkan héshuǐ, gēn yùjiàn de péngyou liáoliaotiānr, nánguò de shìqing bùyìhuìr jiù wàng le.","speaker":"Đoạn văn","vi":"Sau khi lớn lên, hễ gặp chuyện gì không vui, tôi liền ra ngồi dưới gốc cây bên bờ sông, nghe tiếng chim hót, ngắm nhìn nước sông, trò chuyện với những người bạn gặp gỡ, chuyện buồn chẳng mấy chốc đã quên hết."},{"hanzi":"那是我最喜欢的地方。","pinyin":"Nà shì wǒ zuì xǐhuan de dìfang.","speaker":"Đoạn văn","vi":"Đó là nơi tôi thích nhất."}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài nhật ký viết \"我小时候住在北京的西北边，有一条非常有名的河经过那里。我家就住在河边。\" (Hồi nhỏ tôi sống ở phía tây bắc Bắc Kinh, có một con sông rất nổi tiếng chảy qua đó. Nhà tôi sống ngay bên bờ sông.), nên đáp án đúng là bên một con sông nổi tiếng ở phía tây bắc Bắc Kinh.","options":["北京西北边一条有名的河边","南京老街旁边的小区里","动物园附近的高楼里","北京南边草地上的房子里"],"q":"王一雪小时候住在哪里？"},{"answerIdx":3,"explanation":"Trong bài có câu \"长大以后，遇到什么不开心的事情，我就去河边的树下坐着，听听鸟叫，看看河水，跟遇见的朋友聊聊天儿...\" (Sau khi lớn lên, hễ gặp chuyện gì không vui, tôi lại ra dưới tán cây bên bờ sông ngồi, nghe tiếng chim hót, ngắm nước sông, trò chuyện với bạn bè tình cờ gặp...), nên đáp án đúng là ra ngồi dưới tán cây bên bờ sông nghe chim hót và ngắm nước sông.","options":["去河里游泳","去超市买喜欢的东西","在家写日记或者睡觉","去河边的树下坐着听鸟叫、看河水"],"q":"长大以后，遇到不开心的事情时，王一雪常做什么？"}],"scene":"在家里，王一雪在写日记。","sceneVi":"Ở nhà, Vương Nhất Tuyết đang viết nhật ký."}],"hsk3-16":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"这只小猫你们养了多久了？","pinyin":"Zhè zhī xiǎomāo nǐmen yǎng le duōjiǔ le?","speaker":"刘小雪","vi":"Chú mèo con này anh chị nuôi được bao lâu rồi ạ?"},{"hanzi":"已经一年多了。第一天看见它的时候，它又脏又小。","pinyin":"Yǐjīng yì nián duō le. Dì-yī tiān kànjiàn tā de shíhou, tā yòu zāng yòu xiǎo.","speaker":"服务员","vi":"Đã hơn một năm rồi. Ngày đầu tiên nhìn thấy nó, nó vừa bẩn vừa nhỏ."},{"hanzi":"现在它变得又干净又漂亮了。","pinyin":"Xiànzài tā biàn de yòu gānjìng yòu piàoliang le.","speaker":"刘小雪","vi":"Bây giờ nó trở nên vừa sạch sẽ vừa xinh đẹp rồi."},{"hanzi":"是啊。它还特别可爱，一会儿在你脚边睡觉，一会儿在你身上爬。","pinyin":"Shì a. Tā hái tèbié kě'ài, yíhuìr zài nǐ jiǎobiān shuìjiào, yíhuìr zài nǐ shēnshang pá.","speaker":"服务员","vi":"Đúng vậy. Nó còn đặc biệt đáng yêu nữa, lúc thì ngủ bên cạnh chân em, lúc thì trèo lên người em."},{"hanzi":"你们把它照顾得真好。","pinyin":"Nǐmen bǎ tā zhàogù de zhēn hǎo.","speaker":"刘小雪","vi":"Anh chị chăm sóc nó thật tốt."},{"hanzi":"它就好像我们的孩子，我们照顾它，它也认得我们了。","pinyin":"Tā jiù hǎoxiàng wǒmen de háizi, wǒmen zhàogù tā, tā yě rènde wǒmen le.","speaker":"服务员","vi":"Nó cứ như con của chúng tôi vậy, chúng tôi chăm sóc nó, nó cũng nhận ra chúng tôi rồi."},{"hanzi":"妈妈，我们家也养一只小猫吧。","pinyin":"Māma, wǒmen jiā yě yǎng yì zhī xiǎomāo ba.","speaker":"刘小雪","vi":"Mẹ ơi, nhà mình cũng nuôi một con mèo con đi ạ."},{"hanzi":"咱们没时间照顾，还是别养了，我周末带你们去北京动物园看动物吧。","pinyin":"Zánmen méi shíjiān zhàogù, háishi bié yǎng le, wǒ zhōumò dài nǐmen qù Běijīng Dòngwùyuán kàn dòngwù ba.","speaker":"王一雪","vi":"Nhà mình không có thời gian chăm sóc, thôi đừng nuôi nữa, cuối tuần mẹ đưa các con đi Vườn thú Bắc Kinh xem động vật nhé."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, nhân viên cửa hàng nói \"已经一年多了。第一天看见它的时候，它又脏又小。\" (Đã hơn một năm rồi. Ngày đầu tiên nhìn thấy nó, nó vừa bẩn vừa nhỏ.), nên đáp án đúng là ngày đầu tiên nhìn thấy nó, nó vừa bẩn vừa nhỏ.","options":["店员才养了它一个星期","第一天看见它时，它又脏又小","它现在还是很脏，不太漂亮","它不认得照顾它的店员"],"q":"关于店里的这只小猫，下面哪句话是对的？"},{"answerIdx":2,"explanation":"Trong bài, Vương Nhất Tuyết nói \"咱们没时间照顾，还是别养了\" (Nhà mình không có thời gian chăm sóc, thôi đừng nuôi nữa), nên đáp án đúng là vì cả nhà không có thời gian chăm sóc nó.","options":["因为小猫不可爱","因为她不喜欢小动物","因为家里没有时间照顾它","因为动物园里已经有很多猫了"],"q":"王一雪为什么不想在家里养小猫？"}],"scene":"在一家宠物领养店，王一雪和孩子们在看动物。","sceneVi":"Tại một cửa hàng nhận nuôi thú cưng, Vương Nhất Tuyết và các con đang ngắm nhìn các con vật."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"妈妈，大熊猫这个名字很奇怪，它们跟猫有什么关系？","pinyin":"Māma, dàxióngmāo zhège míngzi hěn qíguài, tāmen gēn māo yǒu shénme guānxi?","speaker":"刘小明","vi":"Mẹ ơi, cái tên gấu trúc lớn (đại hùng miêu) rất kỳ lạ, chúng có quan hệ gì với mèo không ạ?"},{"hanzi":"这个问题问得好，它们跟猫没什么关系，其实应该叫大猫熊。","pinyin":"Zhège wèntí wèn de hǎo, tāmen gēn māo méi shénme guānxi, qíshí yīnggāi jiào dà māoxióng.","speaker":"王一雪","vi":"Câu hỏi này hay đấy, chúng chẳng có quan hệ gì với mèo cả, thật ra phải gọi là gấu mèo lớn (đại miêu hùng)."},{"hanzi":"大熊猫为什么只吃竹子不吃肉？","pinyin":"Dàxióngmāo wèishénme zhǐ chī zhúzi bù chī ròu?","speaker":"刘小明","vi":"Tại sao gấu trúc lớn chỉ ăn trúc mà không ăn thịt ạ?"},{"hanzi":"它们跟人一样，也可以吃肉，但是对肉不感兴趣。","pinyin":"Tāmen gēn rén yíyàng, yě kěyǐ chī ròu, dànshì duì ròu bù gǎn xìngqù.","speaker":"王一雪","vi":"Chúng giống như con người vậy, cũng có thể ăn thịt, nhưng không có hứng thú với thịt."},{"hanzi":"大熊猫为什么是中国的国宝？","pinyin":"Dàxióngmāo wèishénme shì Zhōngguó de guóbǎo?","speaker":"刘小明","vi":"Tại sao gấu trúc lớn lại là quốc bảo của Trung Quốc ạ?"},{"hanzi":"全世界只有中国有野生大熊猫，中国是大熊猫的家。","pinyin":"Quán shìjiè zhǐyǒu Zhōngguó yǒu yěshēng dàxióngmāo, Zhōngguó shì dàxióngmāo de jiā.","speaker":"王一雪","vi":"Trên toàn thế giới chỉ có Trung Quốc có gấu trúc lớn hoang dã, Trung Quốc là nhà của gấu trúc lớn."},{"hanzi":"我听说有的熊猫出国了，它们去哪儿了？","pinyin":"Wǒ tīngshuō yǒude xióngmāo chūguó le, tāmen qù nǎr le?","speaker":"刘小明","vi":"Con nghe nói có một số gấu trúc ra nước ngoài rồi, chúng đi đâu vậy ạ?"},{"hanzi":"关于这个问题，我得慢慢给你讲。","pinyin":"Guānyú zhège wèntí, wǒ děi mànmàn gěi nǐ jiǎng.","speaker":"王一雪","vi":"Về vấn đề này, mẹ phải kể từ từ cho con nghe."},{"hanzi":"弟弟，你真是“十万个为什么”。","pinyin":"Dìdi, nǐ zhēn shì “shíwàn gè wèishénme”.","speaker":"刘小雪","vi":"Em trai à, em đúng là “mười vạn câu hỏi vì sao” đấy."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, Vương Nhất Tuyết giải thích \"它们跟人一样，也可以吃肉，但是对肉不感兴趣。\" (Chúng giống con người, cũng có thể ăn thịt, nhưng không có hứng thú với thịt.), nên đáp án đúng là vì chúng không hứng thú với thịt.","options":["因为它们不能吃肉","因为它们对肉不感兴趣","因为动物园里没有肉","因为吃肉会让它们生病"],"q":"按照王一雪的回答，大熊猫为什么不吃肉？"},{"answerIdx":0,"explanation":"Trong đoạn hội thoại, Lưu Tiểu Minh liên tiếp hỏi nhiều câu về gấu trúc nên chị gái nói \"弟弟，你真是‘十万个为什么’。\" (Em trai, em đúng là “mười vạn câu hỏi vì sao”.), hàm ý em đã hỏi rất nhiều câu hỏi.","options":["因为弟弟问了很多问题","因为弟弟正在读一本叫这个名字的书","因为弟弟知道很多关于熊猫的知识","因为弟弟能回答十万个问题"],"q":"刘小雪为什么叫弟弟“十万个为什么”？"}],"scene":"在动物园，王一雪和孩子们边走边聊。","sceneVi":"Ở vườn thú, Vương Nhất Tuyết và các con vừa đi vừa trò chuyện."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"这只大熊猫一会儿爬上去，一会儿跳下来，可爱极了！","pinyin":"Zhè zhī dàxióngmāo yíhuìr pá shàngqù, yíhuìr tiào xiàlái, kě'ài jí le!","speaker":"刘小雪","vi":"Con gấu trúc lớn này lúc thì trèo lên, lúc thì nhảy xuống, đáng yêu cực kỳ!"},{"hanzi":"它好像还没吃饱，站起来张着嘴找吃的呢。","pinyin":"Tā hǎoxiàng hái méi chībǎo, zhàn qǐlái zhāngzhe zuǐ zhǎo chī de ne.","speaker":"王一雪","vi":"Nó hình như vẫn chưa ăn no, đứng dậy há miệng tìm đồ ăn kìa."},{"hanzi":"它身边那只熊猫半天没动，是不是在睡觉呢？","pinyin":"Tā shēnbiān nà zhī xióngmāo bàntiān méi dòng, shì bu shì zài shuìjiào ne?","speaker":"刘小雪","vi":"Con gấu trúc bên cạnh nó mãi không nhúc nhích, có phải đang ngủ không ạ?"},{"hanzi":"我看不见它的脸，可能是吧。一般来说，熊猫每天要睡很多次觉。","pinyin":"Wǒ kàn bú jiàn tā de liǎn, kěnéng shì ba. Yìbān lái shuō, xióngmāo měitiān yào shuì hěn duō cì jiào.","speaker":"王一雪","vi":"Mẹ không nhìn thấy mặt nó, chắc là vậy đấy. Nói chung, gấu trúc mỗi ngày phải ngủ rất nhiều lần."},{"hanzi":"对，除了睡觉以外，很多时间都在吃东西。","pinyin":"Duì, chúle shuìjiào yǐwài, hěn duō shíjiān dōu zài chī dōngxi.","speaker":"刘小雪","vi":"Đúng rồi, ngoài ngủ ra, rất nhiều thời gian đều đang ăn uống."},{"hanzi":"大熊猫的生活真舒服啊！","pinyin":"Dàxióngmāo de shēnghuó zhēn shūfu a!","speaker":"刘小明","vi":"Cuộc sống của gấu trúc lớn thật thoải mái quá đi!"},{"hanzi":"妈妈，您帮我和这两只大熊猫照一张照片吧。","pinyin":"Māma, nín bāng wǒ hé zhè liǎng zhī dàxióngmāo zhào yì zhāng zhàopiàn ba.","speaker":"刘小雪","vi":"Mẹ ơi, mẹ chụp giúp con một tấm ảnh với hai con gấu trúc lớn này đi ạ."}],"readingQuiz":[{"answerIdx":3,"explanation":"Trong bài, Vương Nhất Tuyết nói \"它好像还没吃饱，站起来张着嘴找吃的呢。\" (Hình như nó vẫn chưa ăn no, đang đứng dậy há miệng tìm đồ ăn kìa.), nên đáp án đúng là vì nó đứng dậy há miệng tìm thức ăn.","options":["因为它一直在睡觉","因为它的脸看起来很不高兴","因为它一直跳下来找妈妈","因为它站起来张着嘴找吃的"],"q":"王一雪为什么觉得那只动来动去的大熊猫还没吃饱？"},{"answerIdx":0,"explanation":"Trong bài có câu \"一般来说，熊猫每天要睡很多次觉。\" và \"对，除了睡觉以外，很多时间都在吃东西。\" (Thông thường gấu trúc mỗi ngày phải ngủ rất nhiều lần. / Đúng vậy, ngoài ngủ ra thì phần lớn thời gian đều đang ăn.), nên đáp án đúng là ngoài ngủ ra thì phần lớn thời gian đều ăn uống.","options":["除了睡觉以外，很多时间都在吃东西","每天只睡一次觉，然后一直爬树","跟游客一起照相和做游戏","站起来张着嘴看别的动物"],"q":"按照她们的聊天，大熊猫每天大部分时间都在做什么？"}],"scene":"在熊猫馆，王一雪和孩子们在看大熊猫。","sceneVi":"Ở khu nuôi gấu trúc, Vương Nhất Tuyết và các con đang xem gấu trúc lớn."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"今天我带小雪和小明去动物园玩了。","pinyin":"Jīntiān wǒ dài Xiǎoxuě hé Xiǎomíng qù dòngwùyuán wán le.","speaker":"Đoạn văn","vi":"Hôm nay tôi đưa Tiểu Tuyết và Tiểu Minh đi vườn thú chơi."},{"hanzi":"北京动物园是中国很有名的动物园，里面有非常多的动物，当然，大人和孩子最喜爱的还是大熊猫。","pinyin":"Běijīng Dòngwùyuán shì Zhōngguó hěn yǒumíng de dòngwùyuán, lǐmiàn yǒu fēicháng duō de dòngwù, dāngrán, dàren hé háizi zuì xǐ'ài de háishi dàxióngmāo.","speaker":"Đoạn văn","vi":"Vườn thú Bắc Kinh là vườn thú rất nổi tiếng của Trung Quốc, bên trong có rất nhiều loài động vật, tất nhiên, loài được người lớn và trẻ em yêu thích nhất vẫn là gấu trúc lớn."},{"hanzi":"每天有很多游客去熊猫馆，他们带着相机去给可爱的大熊猫拍照。","pinyin":"Měitiān yǒu hěn duō yóukè qù Xióngmāoguǎn, tāmen dàizhe xiàngjī qù gěi kě'ài de dàxióngmāo pāizhào.","speaker":"Đoạn văn","vi":"Mỗi ngày có rất nhiều du khách đến khu nuôi gấu trúc, họ mang theo máy ảnh đến chụp ảnh cho những chú gấu trúc lớn đáng yêu."},{"hanzi":"动物园早上七点半开门，晚上七点关门，冬天比夏天游客少，所以也比平时早关门一个小时。","pinyin":"Dòngwùyuán zǎoshang qī diǎn bàn kāimén, wǎnshang qī diǎn guānmén, dōngtiān bǐ xiàtiān yóukè shǎo, suǒyǐ yě bǐ píngshí zǎo guānmén yí gè xiǎoshí.","speaker":"Đoạn văn","vi":"Vườn thú mở cửa lúc 7 giờ 30 sáng, đóng cửa lúc 7 giờ tối, mùa đông ít khách hơn mùa hè nên cũng đóng cửa sớm hơn bình thường một tiếng."},{"hanzi":"如果第一次来北京旅游，跟家人一起去北京动物园是个不错的选择。","pinyin":"Rúguǒ dì-yī cì lái Běijīng lǚyóu, gēn jiārén yìqǐ qù Běijīng Dòngwùyuán shì gè búcuò de xuǎnzé.","speaker":"Đoạn văn","vi":"Nếu lần đầu tiên đến Bắc Kinh du lịch, cùng gia đình đi Vườn thú Bắc Kinh là một lựa chọn không tồi."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài nhật ký có câu \"每天有很多游客去熊猫馆，他们带着相机去给可爱的大熊猫拍照。\" (Mỗi ngày có rất nhiều du khách đến khu gấu trúc, họ mang theo máy ảnh để chụp ảnh cho những chú gấu trúc đáng yêu.), nên đáp án đúng là nhiều du khách mang máy ảnh đến chụp ảnh gấu trúc.","options":["只有小孩子喜欢看大熊猫","冬天的游客比夏天多","很多游客带着相机去给大熊猫拍照","游客晚上八点还可以进动物园"],"q":"根据这篇日记，关于北京动物园的游客，哪句话是对的？"},{"answerIdx":0,"explanation":"Trong bài viết \"动物园早上七点半开门，晚上七点关门，冬天比夏天游客少，所以也比平时早关门一个小时。\" (Vườn thú mở cửa lúc 7 giờ 30 sáng, đóng cửa lúc 7 giờ tối; mùa đông ít khách hơn mùa hè nên đóng cửa sớm hơn bình thường một tiếng.), nên vào mùa đông vườn thú đóng cửa lúc 6 giờ tối (六点).","options":["六点","七点","七点半","八点"],"q":"冬天的时候，北京动物园晚上几点关门？"}],"scene":"在家里，王一雪在写日记。","sceneVi":"Ở nhà, Vương Nhất Tuyết đang viết nhật ký."}],"hsk3-17":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"别再向前走了，李老师的办公室已经到了。","pinyin":"Bié zài xiàng qián zǒu le, Lǐ lǎoshī de bàngōngshì yǐjīng dào le.","speaker":"刘小雪","vi":"Đừng đi về phía trước nữa, đến văn phòng thầy Lý rồi."},{"hanzi":"你进去吧，我在楼梯那儿等你。我害怕见李老师。","pinyin":"Nǐ jìnqù ba, wǒ zài lóutī nàr děng nǐ. Wǒ hàipà jiàn Lǐ lǎoshī.","speaker":"同学","vi":"Cậu vào đi, tớ đợi cậu ở chỗ cầu thang. Tớ sợ gặp thầy Lý."},{"hanzi":"怎么回事？","pinyin":"Zěnme huíshì?","speaker":"刘小雪","vi":"Có chuyện gì vậy?"},{"hanzi":"最近我做错了好几件事，我怕李老师生气。","pinyin":"Zuìjìn wǒ zuòcuò le hǎojǐ jiàn shì, wǒ pà Lǐ lǎoshī shēngqì.","speaker":"同学","vi":"Gần đây tớ làm sai mấy việc liền, tớ sợ thầy Lý giận."},{"hanzi":"你想多了，做错事情是很常见的。","pinyin":"Nǐ xiǎng duō le, zuòcuò shìqing shì hěn chángjiàn de.","speaker":"刘小雪","vi":"Cậu nghĩ nhiều quá rồi, làm sai việc là chuyện rất thường gặp mà."},{"hanzi":"我把简单的事情做错了，李老师一定觉得我不认真。","pinyin":"Wǒ bǎ jiǎndān de shìqing zuòcuò le, Lǐ lǎoshī yídìng juéde wǒ bú rènzhēn.","speaker":"同学","vi":"Tớ làm sai những việc đơn giản, thầy Lý nhất định sẽ nghĩ tớ không cẩn thận."},{"hanzi":"有的人虽然很聪明，但是会在简单的事情中出错，因为他们认为事情简单，就不会认真去做了。","pinyin":"Yǒude rén suīrán hěn cōngmíng, dànshì huì zài jiǎndān de shìqing zhōng chūcuò, yīnwèi tāmen rènwéi shìqing jiǎndān, jiù bú huì rènzhēn qù zuò le.","speaker":"刘小雪","vi":"Có người tuy rất thông minh, nhưng lại hay mắc lỗi ở những việc đơn giản, vì họ cho rằng việc đơn giản nên không nghiêm túc làm nữa."},{"hanzi":"你说的就是我，以后我要多向认真的人学习。","pinyin":"Nǐ shuō de jiù shì wǒ, yǐhòu wǒ yào duō xiàng rènzhēn de rén xuéxí.","speaker":"同学","vi":"Cậu nói đúng là tớ đấy, sau này tớ phải học hỏi nhiều hơn từ những người cẩn thận."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, người bạn học nói \"我害怕见李老师。... 最近我做错了好几件事，我怕李老师生气。\" (Mình sợ gặp thầy Lý... Gần đây mình làm sai mấy việc liền, mình sợ thầy Lý giận.), nên đáp án đúng là vì gần đây bạn ấy làm sai mấy việc nên sợ thầy giận.","options":["因为他迷路了，找不到楼梯","因为最近他做错了好几件事，怕老师生气","因为李老师现在不在办公室里","因为他觉得李老师太严格，不聪明"],"q":"同学为什么不想进李老师的办公室？"},{"answerIdx":3,"explanation":"Trong bài, Lưu Tiểu Tuyết nói \"有的人虽然很聪明，但是会在简单的事情中出错，因为他们认为事情简单，就不会认真去做了。\" (Có người tuy rất thông minh nhưng lại mắc lỗi ở những việc đơn giản, bởi vì họ cho rằng việc đơn giản nên sẽ không nghiêm túc làm.), nên đáp án đúng là vì họ nghĩ việc đơn giản nên không làm một cách nghiêm túc.","options":["因为他们太害怕老师了","因为简单的事情其实很难","因为他们没有向别人学习","因为他们觉得事情简单，就不认真去做"],"q":"在刘小雪看来，聪明人为什么有时会在简单的事情上出错？"}],"scene":"在教学楼里，刘小雪和同学边走边聊。","sceneVi":"Trong tòa nhà giảng đường, Lưu Tiểu Tuyết và bạn học vừa đi vừa trò chuyện."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"太阳从西边出来了？这几天怎么总是在图书馆看见你？","pinyin":"Tàiyáng cóng xībiān chūlái le? Zhè jǐ tiān zěnme zǒngshì zài túshūguǎn kànjiàn nǐ?","speaker":"白家月","vi":"Mặt trời mọc đằng tây à? Mấy hôm nay sao lúc nào cũng thấy cậu ở thư viện thế?"},{"hanzi":"这有什么奇怪的？我是来学习的。","pinyin":"Zhè yǒu shénme qíguài de? Wǒ shì lái xuéxí de.","speaker":"陈天中","vi":"Chuyện này có gì lạ đâu? Tớ đến để học mà."},{"hanzi":"你怎么还来图书馆学习？同学们都在到处找工作呢。","pinyin":"Nǐ zěnme hái lái túshūguǎn xuéxí? Tóngxuémen dōu zài dàochù zhǎo gōngzuò ne.","speaker":"白家月","vi":"Sao cậu vẫn còn đến thư viện học? Các bạn đều đang đi khắp nơi tìm việc làm đấy."},{"hanzi":"我不想现在就工作，还想继续学习，我爸妈也同意。可我还没想好学什么，所以来图书馆看看。","pinyin":"Wǒ bù xiǎng xiànzài jiù gōngzuò, hái xiǎng jìxù xuéxí, wǒ bàmā yě tóngyì. Kě wǒ hái méi xiǎnghǎo xué shénme, suǒyǐ lái túshūguǎn kànkan.","speaker":"陈天中","vi":"Tớ chưa muốn đi làm ngay bây giờ, vẫn muốn học tiếp, bố mẹ tớ cũng đồng ý. Nhưng tớ vẫn chưa nghĩ kỹ xem nên học gì, nên đến thư viện xem thử."},{"hanzi":"你不是喜欢玩电脑吗？你可以去看看跟电脑有关系的书。","pinyin":"Nǐ bú shì xǐhuan wán diànnǎo ma? Nǐ kěyǐ qù kànkan gēn diànnǎo yǒu guānxì de shū.","speaker":"白家月","vi":"Không phải cậu thích dùng máy tính sao? Cậu có thể đi xem mấy quyển sách liên quan đến máy tính."},{"hanzi":"你说得对，我记得那个屋子里有些跟电脑有关的书，我去找找。","pinyin":"Nǐ shuō de duì, wǒ jìde nàge wūzi lǐ yǒuxiē gēn diànnǎo yǒuguān de shū, wǒ qù zhǎozhao.","speaker":"陈天中","vi":"Cậu nói đúng đấy, tớ nhớ trong căn phòng kia có một ít sách liên quan đến máy tính, tớ đi tìm thử xem."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài, Trần Thiên Trung nói \"我不想现在就工作，还想继续学习，我爸妈也同意。可我还没想好学什么，所以来图书馆看看。\" (Mình không muốn đi làm ngay bây giờ, vẫn muốn học tiếp, bố mẹ mình cũng đồng ý. Nhưng mình chưa nghĩ ra học gì nên đến thư viện xem thử.), nên đáp án đúng là vì muốn học tiếp nhưng chưa chọn được ngành học nên đến thư viện xem thử.","options":["因为他想找一份跟电脑有关的工作","因为他想在图书馆等白家月","因为他想继续学习，但还没想好学什么，来这里看看","因为他爸妈不同意他现在去工作"],"q":"陈天中这几天为什么总来图书馆？"},{"answerIdx":0,"explanation":"Trong bài, Bạch Gia Nguyệt gợi ý \"你不是喜欢玩电脑吗？你可以去看看跟电脑有关系的书。\" (Chẳng phải cậu thích dùng máy tính sao? Cậu có thể đi xem những cuốn sách liên quan đến máy tính.), nên đáp án đúng là đi xem sách liên quan đến máy tính.","options":["看看跟电脑有关的书","跟同学们一起到处找工作","先问问爸爸妈妈的意见","去阅览室外面玩电脑"],"q":"白家月建议陈天中去做什么？"}],"scene":"在阅览室门口，白家月碰到了陈天中。","sceneVi":"Ở cửa phòng đọc sách, Bạch Gia Nguyệt tình cờ gặp Trần Thiên Trung."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"天中，你的手机怎么关机了？","pinyin":"Tiānzhōng, nǐ de shǒujī zěnme guānjī le?","speaker":"李文","vi":"Thiên Trung, sao điện thoại của cậu lại tắt máy rồi?"},{"hanzi":"我的手机没电了。你找我有事吗？","pinyin":"Wǒ de shǒujī méi diàn le. Nǐ zhǎo wǒ yǒu shì ma?","speaker":"陈天中","vi":"Điện thoại tớ hết pin rồi. Cậu tìm tớ có việc gì à?"},{"hanzi":"前天我看见家月了，她告诉我你打算继续留学？","pinyin":"Qiántiān wǒ kànjiàn Jiāyuè le, tā gàosu wǒ nǐ dǎsuàn jìxù liúxué?","speaker":"李文","vi":"Hôm kia tớ gặp Gia Nguyệt, cậu ấy nói với tớ là cậu định tiếp tục đi du học à?"},{"hanzi":"是，可是我还没想好学什么，更没想好去哪个国家。","pinyin":"Shì, kěshì wǒ hái méi xiǎnghǎo xué shénme, gèng méi xiǎnghǎo qù nǎge guójiā.","speaker":"陈天中","vi":"Ừ, nhưng tớ vẫn chưa nghĩ kỹ xem học ngành gì, lại càng chưa nghĩ ra sẽ đi nước nào."},{"hanzi":"你可以去中国学中文啊。比如可以去北京、上海这样的大城市，那里有很多好大学，也有很多留学生。","pinyin":"Nǐ kěyǐ qù Zhōngguó xué Zhōngwén a. Bǐrú kěyǐ qù Běijīng, Shànghǎi zhèyàng de dà chéngshì, nàlǐ yǒu hěn duō hǎo dàxué, yě yǒu hěn duō liúxuéshēng.","speaker":"李文","vi":"Cậu có thể sang Trung Quốc học tiếng Trung đấy. Ví dụ có thể đến những thành phố lớn như Bắc Kinh, Thượng Hải, ở đó có rất nhiều trường đại học tốt, cũng có rất nhiều du học sinh."},{"hanzi":"好，那我上网查一查。","pinyin":"Hǎo, nà wǒ shàngwǎng chá yi chá.","speaker":"陈天中","vi":"Được, vậy để tớ lên mạng tra thử xem."},{"hanzi":"我给你介绍几个有用的网站。","pinyin":"Wǒ gěi nǐ jièshào jǐ gè yǒuyòng de wǎngzhàn.","speaker":"李文","vi":"Để tớ giới thiệu cho cậu vài trang web hữu ích."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, Trần Thiên Trung nói \"是，可是我还没想好学什么，更没想好去哪个国家。\" (Đúng vậy, nhưng mình vẫn chưa nghĩ xong học gì, càng chưa nghĩ ra đi nước nào.), nên đáp án đúng là chưa nghĩ ra học gì và cũng chưa quyết định đi nước nào.","options":["已经决定去北京学中文了","还没想好学什么，也没想好去哪个国家","已经上网找好了合适的大学","不打算出国留学，只想用手机查资料"],"q":"关于留学的打算，陈天中现在的情况是什么？"},{"answerIdx":3,"explanation":"Trong bài, Lý Văn khuyên \"你可以去中国学中文啊。比如可以去北京、上海这样的大城市...\" (Cậu có thể đến Trung Quốc học tiếng Trung đấy. Ví dụ có thể đến những thành phố lớn như Bắc Kinh, Thượng Hải...) và nói thêm \"我给你介绍几个有用的网站。\" (Mình giới thiệu cho cậu vài trang web hữu ích.), nên đáp án đúng là gợi ý đi Trung Quốc học tiếng Trung và giới thiệu các trang web hữu ích.","options":["借给陈天中一个有电的手机","帮陈天中问了家月的意见","带陈天中去北京和上海参观大学","建议他去中国学中文，并给他介绍有用的网站"],"q":"李文是怎么帮助陈天中的？"}],"scene":"在校园里，李文和陈天中在聊天儿。","sceneVi":"Trong khuôn viên trường, Lý Văn và Trần Thiên Trung đang trò chuyện."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"大学生活马上就要结束了，我最近经常被问到一个问题——“你以后想做什么”，这个问题真不容易回答。","pinyin":"Dàxué shēnghuó mǎshàng jiù yào jiéshù le, wǒ zuìjìn jīngcháng bèi wèn dào yí gè wèntí —— “nǐ yǐhòu xiǎng zuò shénme”, zhège wèntí zhēn bù róngyì huídá.","speaker":"Đoạn văn","vi":"Cuộc sống đại học sắp kết thúc rồi, gần đây tôi thường xuyên bị hỏi một câu hỏi —— “Sau này cậu muốn làm gì?”, câu hỏi này thật sự không dễ trả lời."},{"hanzi":"我也问了几个同学，大家选择的方向都不同。","pinyin":"Wǒ yě wèn le jǐ gè tóngxué, dàjiā xuǎnzé de fāngxiàng dōu bù tóng.","speaker":"Đoạn văn","vi":"Tôi cũng đã hỏi vài bạn học, hướng đi mà mọi người lựa chọn đều khác nhau."},{"hanzi":"有的想继续在学校学习，有的打算出国留学，还有的决定先找工作。","pinyin":"Yǒude xiǎng jìxù zài xuéxiào xuéxí, yǒude dǎsuàn chūguó liúxué, háiyǒude juédìng xiān zhǎo gōngzuò.","speaker":"Đoạn văn","vi":"Có bạn muốn tiếp tục học ở trường, có bạn dự định đi du học nước ngoài, lại có bạn quyết định tìm việc làm trước."},{"hanzi":"我认为只有想清楚自己真正喜欢什么，才能做出最合适的选择。","pinyin":"Wǒ rènwéi zhǐyǒu xiǎng qīngchu zìjǐ zhēnzhèng xǐhuan shénme, cái néng zuòchū zuì héshì de xuǎnzé.","speaker":"Đoạn văn","vi":"Tôi cho rằng chỉ khi nghĩ rõ mình thực sự thích gì thì mới có thể đưa ra lựa chọn phù hợp nhất."},{"hanzi":"对我来说，想清楚“真正喜欢什么”是个难题。","pinyin":"Duì wǒ lái shuō, xiǎng qīngchu “zhēnzhèng xǐhuan shénme” shì gè nántí.","speaker":"Đoạn văn","vi":"Đối với tôi, nghĩ rõ xem “mình thực sự thích gì” là một bài toán khó."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài nhật ký viết \"有的想继续在学校学习，有的打算出国留学，还有的决定先找工作。\" (Có người muốn học tiếp ở trường, có người dự định ra nước ngoài du học, còn có người quyết định đi tìm việc trước.), nên đáp án đúng là có người học tiếp, có người đi du học và có người tìm việc trước.","options":["所有同学都打算先找工作","大家都想出国留学，不想继续在学校学习","有的继续学习，有的出国留学，还有的先找工作","大家都在等老师告诉他们选择什么方向"],"q":"关于大学毕业以后，陈天中的同学们有什么不同的打算？"},{"answerIdx":0,"explanation":"Trong bài có câu \"我认为只有想清楚自己真正喜欢什么，才能做出最合适的选择。\" (Tôi cho rằng chỉ khi nghĩ rõ bản thân thực sự thích gì thì mới có thể đưa ra lựa chọn phù hợp nhất.), nên đáp án đúng là phải nghĩ rõ bản thân thực sự thích gì.","options":["想清楚自己真正喜欢什么","多问几个同学选了什么方向","先随便找一份工作试试","尽快结束大学生活去旅游"],"q":"陈天中认为，怎样才能做出最合适的选择？"}],"scene":"在家里，陈天中在写日记。","sceneVi":"Ở nhà, Trần Thiên Trung đang viết nhật ký."}],"hsk3-18":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"我要在中国过年，真开心。","pinyin":"Wǒ yào zài Zhōngguó guònián, zhēn kāixīn.","speaker":"白家月","vi":"Tớ sắp được đón Tết ở Trung Quốc rồi, vui quá đi."},{"hanzi":"第一次请外国朋友来家里过春节，我也很高兴。","pinyin":"Dì-yī cì qǐng wàiguó péngyou lái jiālǐ guò Chūnjié, wǒ yě hěn gāoxìng.","speaker":"李文","vi":"Lần đầu tiên mời bạn nước ngoài về nhà đón Tết Nguyên đán, tớ cũng rất vui."},{"hanzi":"你们怎样过节？","pinyin":"Nǐmen zěnyàng guòjié?","speaker":"白家月","vi":"Mọi người đón Tết như thế nào?"},{"hanzi":"春节是中国最重要的节日，我们一般会回家，跟家人一起过。","pinyin":"Chūnjié shì Zhōngguó zuì zhòngyào de jiérì, wǒmen yìbān huì huíjiā, gēn jiārén yìqǐ guò.","speaker":"李文","vi":"Tết Nguyên đán là ngày lễ quan trọng nhất ở Trung Quốc, bọn tớ thường sẽ về nhà, đón Tết cùng gia đình."},{"hanzi":"那你跟家人会一起做什么？","pinyin":"Nà nǐ gēn jiārén huì yìqǐ zuò shénme?","speaker":"白家月","vi":"Vậy cậu với gia đình sẽ cùng nhau làm gì?"},{"hanzi":"我们家会一边包饺子，一边看春节联欢晚会，一直到十二点以后才睡觉。","pinyin":"Wǒmen jiā huì yìbiān bāo jiǎozi, yìbiān kàn Chūnjié Liánhuān Wǎnhuì, yìzhí dào shí'èr diǎn yǐhòu cái shuìjiào.","speaker":"李文","vi":"Nhà tớ sẽ vừa gói bánh chẻo, vừa xem Chương trình Đêm hội Mừng Xuân, mãi đến sau 12 giờ mới đi ngủ."},{"hanzi":"听起来很有意思。春节放几天假？","pinyin":"Tīng qǐlái hěn yǒu yìsi. Chūnjié fàng jǐ tiān jià?","speaker":"白家月","vi":"Nghe thú vị quá. Tết Nguyên đán được nghỉ mấy ngày?"},{"hanzi":"大概七八天。","pinyin":"Dàgài qī bā tiān.","speaker":"李文","vi":"Khoảng bảy tám ngày."}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài, Lý Văn nói \"第一次请外国朋友来家里过春节，我也很高兴。\" (Lần đầu tiên mời bạn nước ngoài về nhà đón Tết Nguyên đán, mình cũng rất vui.), nên đáp án đúng là vì đây là lần đầu tiên anh ấy mời bạn nước ngoài về nhà đón Tết.","options":["因为这是他第一次请外国朋友来家里过春节","因为他终于坐飞机回到中国了","因为他特别喜欢吃饺子和看晚会","因为春节只放七八天假"],"q":"李文为什么也很高兴？"},{"answerIdx":2,"explanation":"Trong bài, Lý Văn cho biết \"我们家会一边包饺子，一边看春节联欢晚会，一直到十二点以后才睡觉。\" (Nhà mình sẽ vừa gói sủi cảo vừa xem chương trình Gặp nhau cuối năm, mãi đến sau 12 giờ mới đi ngủ.) và \"大概七八天。\" (Khoảng 7-8 ngày.), nên đáp án đúng là vừa gói sủi cảo vừa xem Gala Xuân Vãn và nghỉ khoảng 7-8 ngày.","options":["出去旅游，放十天假","十二点以前睡觉，放五六天假","一边包饺子一边看春节联欢晚会，放七八天假","跟外国朋友在飞机上过节，不放假"],"q":"李文一家过春节时一般做什么，春节大概放几天假？"}],"scene":"在飞机上，白家月和李文在聊天儿。","sceneVi":"Trên máy bay, Bạch Gia Nguyệt và Lý Văn đang trò chuyện."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"张阿姨，李叔叔。过年好！这是我准备的礼物，请收下。","pinyin":"Zhāng āyí, Lǐ shūshu. Guònián hǎo! Zhè shì wǒ zhǔnbèi de lǐwù, qǐng shōuxià.","speaker":"白家月","vi":"Cô Trương, chú Lý. Chúc mừng năm mới ạ! Đây là món quà cháu chuẩn bị, xin cô chú nhận cho ạ."},{"hanzi":"谢谢家月，你太客气了！","pinyin":"Xièxie Jiāyuè, nǐ tài kèqi le!","speaker":"李叔叔","vi":"Cảm ơn Gia Nguyệt, cháu khách sáo quá rồi!"},{"hanzi":"总听小文说起你，今天终于有机会见面了。","pinyin":"Zǒng tīng Xiǎowén shuōqǐ nǐ, jīntiān zhōngyú yǒu jīhuì jiànmiàn le.","speaker":"张阿姨","vi":"Cô vẫn luôn nghe Tiểu Văn nhắc đến cháu, hôm nay cuối cùng cũng có cơ hội gặp mặt rồi."},{"hanzi":"谢谢您和叔叔请我来家里做客。","pinyin":"Xièxie nín hé shūshu qǐng wǒ lái jiālǐ zuòkè.","speaker":"白家月","vi":"Cháu cảm ơn cô và chú đã mời cháu đến nhà chơi ạ."},{"hanzi":"桌子上有饮料，还有矿泉水，你想喝什么就自己拿。","pinyin":"Zhuōzi shàng yǒu yǐnliào, hái yǒu kuàngquánshuǐ, nǐ xiǎng hē shénme jiù zìjǐ ná.","speaker":"李叔叔","vi":"Trên bàn có nước ngọt, còn có nước khoáng, cháu muốn uống gì thì cứ tự lấy nhé."},{"hanzi":"你先坐着看会儿电视，饺子很快就包好了。","pinyin":"Nǐ xiān zuòzhe kànhuìr diànshì, jiǎozi hěn kuài jiù bāohǎo le.","speaker":"张阿姨","vi":"Cháu cứ ngồi xem ti vi một lát đi, bánh chẻo sắp gói xong rồi."},{"hanzi":"我刚刚看视频学会了包饺子，我跟你们一起包吧。","pinyin":"Wǒ gānggāng kàn shìpín xuéhuì le bāo jiǎozi, wǒ gēn nǐmen yìqǐ bāo ba.","speaker":"白家月","vi":"Cháu vừa xem video học được cách gói bánh chẻo rồi, để cháu gói cùng cô chú nhé."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, cô Trương nói \"总听小文说起你，今天终于有机会见面了。\" (Cô luôn nghe Tiểu Văn nhắc đến cháu, hôm nay cuối cùng cũng có cơ hội gặp mặt rồi.), chứng tỏ hôm nay là lần đầu tiên hai người gặp nhau.","options":["她们以前见过好几次面","今天是她们第一次见面","张阿姨从来没听过白家月的名字","张阿姨不喜欢白家月带的礼物"],"q":"关于张阿姨和白家月，下面哪句话是对的？"},{"answerIdx":3,"explanation":"Khi cô Trương bảo ngồi xem tivi một lát, Bạch Gia Nguyệt đáp \"我刚刚看视频学会了包饺子，我跟你们一起包吧。\" (Cháu vừa xem video học được cách gói sủi cảo rồi, cháu gói cùng hai bác nhé.), nên đáp án đúng là muốn cùng bố mẹ Lý Văn gói sủi cảo.","options":["先拿桌子上的矿泉水喝","拿出礼物送给李叔叔","坐着看视频学中文","和李文的父母一起包饺子"],"q":"张阿姨让白家月先坐着看会儿电视，白家月想做什么？"}],"scene":"在李文家，白家月给李文的父母拜年。","sceneVi":"Tại nhà Lý Văn, Bạch Gia Nguyệt chúc Tết bố mẹ của Lý Văn."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"这张照片是李文出国前照的吗？","pinyin":"Zhè zhāng zhàopiàn shì Lǐ Wén chūguó qián zhào de ma?","speaker":"白家月","vi":"Bức ảnh này là chụp trước khi Lý Văn ra nước ngoài phải không ạ?"},{"hanzi":"对，这是他从北京出发时，我们全家在机场照的。","pinyin":"Duì, zhè shì tā cóng Běijīng chūfā shí, wǒmen quánjiā zài jīchǎng zhào de.","speaker":"张阿姨","vi":"Đúng rồi, đây là lúc nó xuất phát từ Bắc Kinh, cả nhà cô chụp ở sân bay đấy."},{"hanzi":"那是三四年前吧？","pinyin":"Nà shì sān sì nián qián ba?","speaker":"白家月","vi":"Đó là khoảng ba bốn năm trước phải không ạ?"},{"hanzi":"是啊，时间过得真快，好像是不久前发生的一样。","pinyin":"Shì a, shíjiān guò de zhēn kuài, hǎoxiàng shì bùjiǔ qián fāshēng de yíyàng.","speaker":"张阿姨","vi":"Phải đó, thời gian trôi nhanh thật, cứ như chuyện mới xảy ra cách đây không lâu vậy."},{"hanzi":"您一定特别想李文吧？","pinyin":"Nín yídìng tèbié xiǎng Lǐ Wén ba?","speaker":"白家月","vi":"Chắc cô nhớ Lý Văn lắm nhỉ?"},{"hanzi":"他刚离开家时，我很不习惯，只要几天不跟他视频，就很想他。","pinyin":"Tā gāng líkāi jiā shí, wǒ hěn bù xíguàn, zhǐyào jǐ tiān bù gēn tā shìpín, jiù hěn xiǎng tā.","speaker":"张阿姨","vi":"Lúc nó mới xa nhà, cô không quen chút nào, chỉ cần vài ngày không gọi video cho nó là nhớ nó lắm."},{"hanzi":"还有最后一个学期就要毕业了，他很快就会回来了。","pinyin":"Hái yǒu zuìhòu yí gè xuéqī jiù yào bìyè le, tā hěn kuài jiù huì huílái le.","speaker":"白家月","vi":"Còn một học kỳ cuối nữa là tốt nghiệp rồi, cậu ấy sẽ nhanh chóng về thôi ạ."}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài, cô Trương nói \"对，这是他从北京出发时，我们全家在机场照的。\" (Đúng vậy, đây là ảnh cả nhà cô chụp ở sân bay khi nó xuất phát từ Bắc Kinh.) và xác nhận \"那是三四年前吧？\" (Đó là 3-4 năm trước phải không?), nên đáp án đúng là chụp ở sân bay khi Lý Văn xuất phát từ Bắc Kinh khoảng 3-4 năm trước.","options":["三四年前李文从北京出发时，全家在机场照的","李文刚毕业回国时在家里照的","今年春节全家人包饺子时照的","李文在外国的大学校园里照的"],"q":"白家月和张阿姨看的那张照片是什么时候、在哪里照的？"},{"answerIdx":2,"explanation":"Trong bài, cô Trương nói \"他刚离开家时，我很不习惯，只要几天不跟他视频，就很想他。\" (Lúc nó mới rời nhà, cô rất không quen, hễ mấy ngày không gọi video cho nó là lại rất nhớ nó.), nên đáp án đúng là lúc Lý Văn mới xa nhà, cô Trương rất nhớ anh ấy và không quen.","options":["李文离开家以后，张阿姨从来不跟李文视频","李文还要两年才能毕业","李文刚离开家时，张阿姨很想他，不习惯","张阿姨觉得这三四年过得很慢"],"q":"根据这段对话，下面哪句话是对的？"}],"scene":"在李文家，李文妈妈和白家月在聊天儿。","sceneVi":"Tại nhà Lý Văn, mẹ Lý Văn và Bạch Gia Nguyệt đang trò chuyện."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"这次来中国，我最高兴的是认识了李文的父母。","pinyin":"Zhè cì lái Zhōngguó, wǒ zuì gāoxìng de shì rènshi le Lǐ Wén de fùmǔ.","speaker":"Đoạn văn","vi":"Lần này đến Trung Quốc, điều khiến tôi vui nhất là được quen biết bố mẹ của Lý Văn."},{"hanzi":"他们给我看了李文出生时的照片，还给我讲了很多他过去的故事。","pinyin":"Tāmen gěi wǒ kàn le Lǐ Wén chūshēng shí de zhàopiàn, hái gěi wǒ jiǎng le hěn duō tā guòqù de gùshi.","speaker":"Đoạn văn","vi":"Bác ấy đã cho tôi xem ảnh lúc Lý Văn mới sinh, còn kể cho tôi nghe rất nhiều câu chuyện trước đây của cậu ấy."},{"hanzi":"李文高中的时候想学医，从那时起就努力学习。","pinyin":"Lǐ Wén gāozhōng de shíhou xiǎng xuéyī, cóng nà shí qǐ jiù nǔlì xuéxí.","speaker":"Đoạn văn","vi":"Hồi cấp ba Lý Văn muốn học ngành y, từ lúc đó cậu ấy đã chăm chỉ học tập."},{"hanzi":"高三的时候，因为成绩特别好，他得到了出国留学的机会。","pinyin":"Gāosān de shíhou, yīnwèi chéngjì tèbié hǎo, tā dédào le chūguó liúxué de jīhuì.","speaker":"Đoạn văn","vi":"Năm lớp 12, nhờ thành tích đặc biệt xuất sắc, cậu ấy đã giành được cơ hội đi du học nước ngoài."},{"hanzi":"在他身上，我懂得了，只要一直坚持，就能完成自己的目标。","pinyin":"Zài tā shēnshàng, wǒ dǒngde le, zhǐyào yìzhí jiānchí, jiù néng wánchéng zìjǐ de mùbiāo.","speaker":"Đoạn văn","vi":"Từ cậu ấy, tôi hiểu ra rằng chỉ cần luôn kiên trì thì sẽ có thể hoàn thành được mục tiêu của mình."},{"hanzi":"我相信，他以后一定会发展得更好。","pinyin":"Wǒ xiāngxìn, tā yǐhòu yídìng huì fāzhǎn de gèng hǎo.","speaker":"Đoạn văn","vi":"Tôi tin rằng sau này cậu ấy nhất định sẽ phát triển tốt hơn nữa."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài nhật ký có câu \"高三的时候，因为成绩特别好，他得到了出国留学的机会。\" (Hồi lớp 12, nhờ thành tích đặc biệt tốt nên cậu ấy đã có được cơ hội ra nước ngoài du học.), nên đáp án đúng là vì thành tích của cậu ấy đặc biệt tốt.","options":["因为他有很多外国朋友","因为他的成绩特别好","因为他爸爸妈妈让他出国","因为他不想在高中继续学习"],"q":"高三的时候，李文为什么得到了出国留学的机会？"},{"answerIdx":3,"explanation":"Trong bài có câu \"在他身上，我懂得了，只要一直坚持，就能完成自己的目标。\" (Từ cậu ấy, tôi hiểu ra rằng chỉ cần luôn kiên trì thì sẽ có thể hoàn thành được mục tiêu của mình.), nên đáp án đúng là chỉ cần luôn kiên trì thì sẽ hoàn thành được mục tiêu.","options":["学医是高中生最好的选择","出国留学一定要在高三准备","认识朋友的父母是一件很高兴的事","只要一直坚持，就能完成自己的目标"],"q":"从李文的故事中，白家月明白了什么道理？"}],"scene":"在家里，白家月在写日记。","sceneVi":"Ở nhà, Bạch Gia Nguyệt đang viết nhật ký."}]});
